  FT["PH-H5207"] = {"id":"PH-H5207","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6710_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring September 1 of Each Year as Baguio Charter Day and a Special Non-Working Holiday in the City of Baguio in Order to Commemorate the Anniversary of the Said City","orig":"An Act Declaring September 1 of Each Year as Baguio Charter Day and a Special Non-Working Holiday in the City of Baguio in Order to Commemorate the Anniversary of the Said City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6710","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6710_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5207-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to commemorate the anniversary of the City of Baguio, September 1 of each year is hereby declared as Baguio Charter Day and a special non-working holiday in the said city."}},{"id":"PH-H5207-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, February 10, 1989."}}],"pack":"ph-p74"};
  FT["PH-H5208"] = {"id":"PH-H5208","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6711_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Medicion Elementary School, in Medicion 2nd, Municipality of Imus, Province of Cavite, to Gov. Dominador Camerino Elementary School","orig":"An Act Changing the Name of the Medicion Elementary School, in Medicion 2nd, Municipality of Imus, Province of Cavite, to Gov. Dominador Camerino Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6711","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6711_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5208-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Medicion Elementary School in the Municipality of Imus, Province of Cavite, is hereby changed to Gov. Dominador Camerino Elementary School."}},{"id":"PH-H5208-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, February 10, 1989."}}],"pack":"ph-p74"};
  FT["PH-H5209"] = {"id":"PH-H5209","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6712_1989.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Senator Ninoy Aquino in the Province of Sultan Kudarat","orig":"An Act Creating the Municipality of Senator Ninoy Aquino in the Province of Sultan Kudarat"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6712","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-17","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6712_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5209-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangays Buenaflores, Bugso, Kiadsam, Kadi, Kulaman, Malegdeg and Sewod in the Municipality of Kalamansig and Langgal in the Municipality of Bagumbayan are hereby separated from those municipalities and constituted into an independent municipality, which is hereby created, to be known as the Municipality of Senator Ninoy Aquino, without affecting in any manner the legal existence of the Municipalities of Kalamansig and Bagumbayan. The seat of government of the new municipality shall be in Barangay Kulaman."}},{"id":"PH-H5209-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The territorial jurisdiction of the Municipality of Senator Ninoy Aquino shall be bounded as follows: Starting from a point marked \"1\" on the proposed plan (Southwestern corner of Lot 1302-PLS-604-D, Case 2, of the Bagumbayan Land Subdivision); due South to corner 2; thence, following the centerline upstream of Baluan River, about 1,500 meters to corner 3; thence, due West following the political boundary between the Provinces of Sultan Kudarat and South Cotabato with an approximate distance of 14,000 meters to corner 4; thence, due North, 10,000 meters to corner 5 (common boundary of Palimbang and Kalamansig); thence due North, distance of 12,500 meters to corner 6 (intersecting the centerline of Tran River, common boundary of Bagumbayan and Isulan) to corner 7; thence, following upstream of Kulaman River until the intersection of a certain creek, a distance of 2,000 meters to point 8; thence, Southeastern direction connecting Northeastern corner of Lot 415-PLS-604-D, Case 1 to corner 9; thence, following the boundary lines of Lots 415-PLS-604-D until the common corner of Lots 412 and 415 PLS-604-D to corner 10; thence, following the boundary lines of Lots 413-PLS-604-D to corner 11; thence, following the Eastern boundary lines of Lots 414, 322, 321, 225, 224, 127, and 126-PLS-604-D to corner 12; thence, due East, until the Northeastern corner of Lot 41-PLS-604-D to corner 13; thence, following the Eastern boundary lines of Lots 41, 40, 849, 850, 927, 928, 1005, 1075, 1076, 1143, 1144-PLS-604-D, until the centerline of Baluan River to corner 14; thence, following the centerline upstream of Baluan River until the point of beginning; containing an area of thirty-two thousand (32,000) hectares, more or less. Bounded on the East by the Municipality of Bagumbayan, Sultan Kudarat; on the South by the Province of South Cotabato; on the West by the Municipalities of Palimbang and Kalamansig, both of Sultan Kudarat; and on the North by the Municipality of Isulan, Sultan Kudarat."}},{"id":"PH-H5209-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within sixty (60) days after ratification by the majority of the votes cast in a plebiscite supervised by the Commission on Elections to be conducted in the affected area of the present Municipalities of Kalamansig and Bagumbayan within a period of ninety (90) days after the approval of this Act, the President shall appoint the mayor and other officials to hold elective positions in the new Municipality of Senator Ninoy Aquino."}},{"id":"PH-H5209-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The new municipality shall require corporate existence upon the appointment and qualification of the first mayor and the majority of the members of the municipal council."}},{"id":"PH-H5209-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, executive orders, rules and regulations, or parts thereof, which are inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H5209-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The expenses in holding the plebiscite provided in Section 3 hereof shall be taken out of the contingent fund under the fiscal year appropriations."}},{"id":"PH-H5209-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, February 17, 1989."}}],"pack":"ph-p74"};
  FT["PH-H5210"] = {"id":"PH-H5210","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6713_1989.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a Code of Conduct and Ethical Standards for Public Officials and Employees, to Uphold the Time-Honored Principle of Public Office Being a Public Trust, Granting Incentives and Rewards for Exemplary Service, Enumerating Prohibited Acts and Transactions and Providing Penalties for Violations Thereof and for Other Purposes","orig":"An Act Establishing a Code of Conduct and Ethical Standards for Public Officials and Employees, to Uphold the Time-Honored Principle of Public Office Being a Public Trust, Granting Incentives and Rewards for Exemplary Service, Enumerating Prohibited Acts and Transactions and Providing Penalties for Violations Thereof and for Other Purposes"},"level":"law","status":"active","topics":["labor","criminal","administrative"],"docNumber":"Republic Act No. 6713","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-20","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6713_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5210-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known as the \"Code of Conduct and Ethical Standards for Public Officials and Employees.\""}},{"id":"PH-H5210-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policies. - It is the policy of the State to promote a high standard of ethics in public service. Public officials and employees shall at all times be accountable to the people and shall discharge their duties with utmost responsibility, integrity, competence, and loyalty, act with patriotism and justice, lead modest lives, and uphold public interest over personal interest."}},{"id":"PH-H5210-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - As used in this Act, the term:\n(a) \"Government\" includes the National Government, the local governments, and all other instrumentalities, agencies or branches of the Republic of the Philippines including government-owned or controlled corporations, and their subsidiaries.\n(b) \"Public Officials\" includes elective and appointive officials and employees, permanent or temporary, whether in the career or non-career service, including military and police personnel, whether or not they receive compensation, regardless of amount.\n(c) \"Gift\" refers to a thing or a right to dispose of gratuitously, or any act or liberality, in favor of another who accepts it, and shall include a simulated sale or an ostensibly onerous disposition thereof. It shall not include an unsolicited gift of nominal or insignificant value not given in anticipation of, or in exchange for, a favor from a public official or employee.\n(d) \"Receiving any gift\" includes the act of accepting directly or indirectly, a gift from a person other than a member of his family or relative as defined in this Act, even on the occasion of a family celebration or national festivity like Christmas, if the value of the gift is neither nominal nor insignificant, or the gift is given in anticipation of, or in exchange for, a favor.\n(e) \"Loan\" covers both simple loan and commodatum as well as guarantees, financing arrangements or accommodations intended to ensure its approval.\n(f) \"Substantial stockholder\" means any person who owns, directly or indirectly, shares of stock sufficient to elect a director of a corporation. This term shall also apply to the parties to a voting trust.\n(g) \"Family of public officials or employees\" means their spouses and unmarried children under eighteen (18) years of age.\n(h) \"Person\" includes natural and juridical persons unless the context indicates otherwise.\n(i) \"Conflict of interest\" arises when a public official or employee is a member of a board, an officer, or a substantial stockholder of a private corporation or owner or has a substantial interest in a business, and the interest of such corporation or business, or his rights or duties therein, may be opposed to or affected by the faithful performance of official duty.\n(j) \"Divestment\" is the transfer of title or disposal of interest in property by voluntarily, completely and actually depriving or dispossessing oneself of his right or title to it in favor of a person or persons other than his spouse and relatives as defined in this Act.\n(k) \"Relatives\" refers to any and all persons related to a public official or employee within the fourth civil degree of consanguinity or affinity, including bilas, inso and balae."}},{"id":"PH-H5210-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Norms of Conduct of Public Officials and Employees. - (A) Every public official and employee shall observe the following as standards of personal conduct in the discharge and execution of official duties:\n(a) Commitment to public interest. - Public officials and employees shall always uphold the public interest over and above personal interest. All government resources and powers of their respective offices must be employed and used efficiently, effectively, honestly and economically, particularly to avoid wastage in public funds and revenues.\n(b) Professionalism. - Public officials and employees shall perform and discharge their duties with the highest degree of excellence, professionalism, intelligence and skill. They shall enter public service with utmost devotion and dedication to duty. They shall endeavor to discourage wrong perceptions of their roles as dispensers or peddlers of undue patronage.\n(c) Justness and sincerity. - Public officials and employees shall remain true to the people at all times. They must act with justness and sincerity and shall not discriminate against anyone, especially the poor and the underprivileged. They shall at all times respect the rights of others, and shall refrain from doing acts contrary to law, good morals, good customs, public policy, public order, public safety and public interest. They shall not dispense or extend undue favors on account of their office to their relatives whether by consanguinity or affinity except with respect to appointments of such relatives to positions considered strictly confidential or as members of their personal staff whose terms are coterminous with theirs.\n(d) Political neutrality. - Public officials and employees shall provide service to everyone without unfair discrimination and regardless of party affiliation or preference.\n(e) Responsiveness to the public. - Public officials and employees shall extend prompt, courteous, and adequate service to the public. Unless otherwise provided by law or when required by the public interest, public officials and employees shall provide information of their policies and procedures in clear and understandable language, ensure openness of information, public consultations and hearings whenever appropriate, encourage suggestions, simplify and systematize policy, rules and procedures, avoid red tape and develop an understanding and appreciation of the socio-economic conditions prevailing in the country, especially in the depressed rural and urban areas.\n(f) Nationalism and patriotism. - Public officials and employees shall at all times be loyal to the Republic and to the Filipino people, promote the use of locally produced goods, resources and technology and encourage appreciation and pride of country and people. They shall endeavor to maintain and defend Philippine sovereignty against foreign intrusion.\n(g) Commitment to democracy. - Public officials and employees shall commit themselves to the democratic way of life and values, maintain the principle of public accountability, and manifest by deeds the supremacy of civilian authority over the military. They shall at all times uphold the Constitution and put loyalty to country above loyalty to persons or party.\n(h) Simple living. - Public officials and employees and their families shall lead modest lives appropriate to their positions and income. They shall not indulge in extravagant or ostentatious display of wealth in any form.\n(B) The Civil Service Commission shall adopt positive measures to promote (1) observance of these standards including the dissemination of information programs and workshops authorizing merit increases beyond regular progression steps, to a limited number of employees recognized by their office colleagues to be outstanding in their observance of ethical standards; and (2) continuing research and experimentation on measures which provide positive motivation to public officials and employees in raising the general level of observance of these standards."}},{"id":"PH-H5210-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Duties of Public Officials and Employees. - In the performance of their duties, all public officials and employees are under obligation to:\n(a) Act promptly on letters and requests. - All public officials and employees shall, within fifteen (15) working days from receipt thereof, respond to letters, telegrams or other means of communications sent by the public. The reply must contain the action taken on the request.\n(b) Submit annual performance reports. - All heads or other responsible officers of offices and agencies of the government and of government-owned or controlled corporations shall, within forty-five (45) working days from the end of the year, render a performance report of the agency or office or corporation concerned. Such report shall be open and available to the public within regular office hours.\n(c) Process documents and papers expeditiously. - All official papers and documents must be processed and completed within a reasonable time from the preparation thereof and must contain, as far as practicable, not more than three (3) signatories therein. In the absence of duly authorized signatories, the official next-in-rank or officer in charge shall sign for and in their behalf.\n(d) Act immediately on the public's personal transactions. - All public officials and employees must attend to anyone who wants to avail himself of the services of their offices and must, at all times, act promptly and expeditiously.\n(e) Make documents accessible to the public. - All public documents must be made accessible to, and readily available for inspection by, the public within reasonable working hours."}},{"id":"PH-H5210-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"System of Incentives and Rewards. - A system of annual incentives and rewards is hereby established in order to motivate and inspire public servants to uphold the highest standards of ethics. For this purpose, a Committee on Awards to Outstanding Public Officials and Employees is hereby created composed of the following: the Ombudsman and Chairman of the Civil Service Commission as Co-Chairmen, and the Chairman of the Commission on Audit, and two government employees to be appointed by the President, as members.\nIt shall be the task of this Committee to conduct a periodic, continuing review of the performance of public officials and employees, in all the branches and agencies of Government and establish a system of annual incentives and rewards to the end that due recognition is given to public officials and employees of outstanding merit on the basis of the standards set forth in this Act.\nThe conferment of awards shall take into account, among other things, the following: the years of service and the quality and consistency of performance, the obscurity of the position, the level of salary, the unique and exemplary quality of a certain achievement, and the risks or temptations inherent in the work. Incentives and rewards to government officials and employees of the year to be announced in public ceremonies honoring them may take the form of bonuses, citations, directorships in government-owned or controlled corporations, local and foreign scholarship grants, paid vacations and the like. They shall likewise be automatically promoted to the next higher position with the commensurate salary suitable to their qualifications. In case there is no next higher position or it is not vacant, said position shall be included in the budget of the office in the next General Appropriations Act. The Committee on Awards shall adopt its own rules to govern the conduct of its activities."}},{"id":"PH-H5210-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Prohibited Acts and Transactions. - In addition to acts and omissions of public officials and employees now prescribed in the Constitution and existing laws, the following shall constitute prohibited acts and transactions of any public official and employee and are hereby declared to be unlawful:\n(a) Financial and material interest. - Public officials and employees shall not, directly or indirectly, have any financial or material interest in any transaction requiring the approval of their office.\n(b) Outside employment and other activities related thereto. - Public officials and employees during their incumbency shall not:\n(1) Own, control, manage or accept employment as officer, employee, consultant, counsel, broker, agent, trustee or nominee in any private enterprise regulated, supervised or licensed by their office unless expressly allowed by law;\n(2) Engage in the private practice of their profession unless authorized by the Constitution or law, provided, that such practice will not conflict or tend to conflict with their official functions; or\n(3) Recommend any person to any position in a private enterprise which has a regular or pending official transaction with their office.\nThese prohibitions shall continue to apply for a period of one (1) year after resignation, retirement, or separation from public office, except in the case of subparagraph (b) (2) above, but the professional concerned cannot practice his profession in connection with any matter before the office he used to be with, in which case the one-year prohibition shall likewise apply.\n(c) Disclosure and/or misuse of confidential information. - Public officials and employees shall not use or divulge, confidential or classified information officially known to them by reason of their office and not made available to the public, either:\n(1) To further their private interests, or give undue advantage to anyone; or\n(2) To prejudice the public interest.\n(d) Solicitation or acceptance of gifts. - Public officials and employees shall not solicit or accept, directly or indirectly, any gift, gratuity, favor, entertainment, loan or anything of monetary value from any person in the course of their official duties or in connection with any operation being regulated by, or any transaction which may be affected by the functions of their office.\nAs to gifts or grants from foreign governments, the Congress consents to:\n(i) The acceptance and retention by a public official or employee of a gift of nominal value tendered and received as a souvenir or mark of courtesy;\n(ii) The acceptance by a public official or employee of a gift in the nature of a scholarship or fellowship grant or medical treatment; or\n(iii) The acceptance by a public official or employee of travel grants or expenses for travel taking place entirely outside the Philippine (such as allowances, transportation, food, and lodging) of more than nominal value if such acceptance is appropriate or consistent with the interests of the Philippines, and permitted by the head of office, branch or agency to which he belongs.\nThe Ombudsman shall prescribe such regulations as may be necessary to carry out the purpose of this subsection, including pertinent reporting and disclosure requirements.\nNothing in this Act shall be construed to restrict or prohibit any educational, scientific or cultural exchange programs subject to national security requirements."}},{"id":"PH-H5210-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Statements and Disclosure. - Public officials and employees have an obligation to accomplish and submit declarations under oath of, and the public has the right to know, their assets, liabilities, net worth and financial and business interests including those of their spouses and of unmarried children under eighteen (18) years of age living in their households.\n(A) Statements of Assets and Liabilities and Financial Disclosure. - All public officials and employees, except those who serve in an honorary capacity, laborers and casual or temporary workers, shall file under oath their Statement of Assets, Liabilities and Net Worth and a Disclosure of Business Interests and Financial Connections and those of their spouses and unmarried children under eighteen (18) years of age living in their households.\nThe two documents shall contain information on the following:\n(a) real property, its improvements, acquisition costs, assessed value and current fair market value;\n(b) personal property and acquisition cost;\n(c) all other assets such as investments, cash on hand or in banks, stocks, bonds, and the like;\n(d) liabilities, and;\n(e) all business interests and financial connections.\nThe documents must be filed:\n(a) within thirty (30) days after assumption of office;\n(b) on or before April 30, of every year thereafter; and\n(c) within thirty (30) days after separation from the service.\nAll public officials and employees required under this section to file the aforestated documents shall also execute, within thirty (30) days from the date of their assumption of office, the necessary authority in favor of the Ombudsman to obtain from all appropriate government agencies, including the Bureau of Internal Revenue, such documents as may show their assets, liabilities, net worth, and also their business interests and financial connections in previous years, including, if possible, the year when they first assumed any office in the Government.\nHusband and wife who are both public officials or employees may file the required statements jointly or separately.\nThe Statements of Assets, Liabilities and Net Worth and the Disclosure of Business Interests and Financial Connections shall be filed by:\n(1) Constitutional and national elective officials, with the national office of the Ombudsman;\n(2) Senators and Congressmen, with the Secretaries of the Senate and the House of Representatives, respectively; Justices, with the Clerk of Court of the Supreme Court; Judges, with the Court Administrator; and all national executive officials with the Office of the President.\n(3) Regional and local officials and employees, with the Deputy Ombudsman in their respective regions;\n(4) Officers of the armed forces from the rank of colonel or naval captain, with the Office of the President, and those below said ranks, with the Deputy Ombudsman in their respective regions; and\n(5) All other public officials and employees, defined in Republic Act No. 3019, as amended, with the Civil Service Commission.\n(B) Identification and disclosure of relatives. - It shall be the duty of every public official or employee to identify and disclose, to the best of his knowledge and information, his relatives in the Government in the form, manner and frequency prescribed by the Civil Service Commission.\n(C) Accessibility of documents. - (1) Any and all statements filed under this Act, shall be made available for inspection at reasonable hours.\n(2) Such statements shall be made available for copying or reproduction after ten (10) working days from the time they are filed as required by law.\n(3) Any person requesting a copy of a statement shall be required to pay a reasonable fee to cover the cost of reproduction and mailing of such statement, as well as the cost of certification.\n(4) Any statement filed under this Act shall be available to the public for a period of ten (10) years after receipt of the statement. After such period, the statement may be destroyed unless needed in an ongoing investigation.\n(D) Prohibited acts. - It shall be unlawful for any person to obtain or use any statement filed under this Act for:\n(a) any purpose contrary to morals or public policy; or\n(b) any commercial purpose other than by news and communications media for dissemination to the general public."}},{"id":"PH-H5210-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Divestment. - A public official or employee shall avoid conflicts of interest at all times. When a conflict of interest arises, he shall resign from his position in any private business enterprise within thirty (30) days from his assumption of office and/or divest himself of his shareholdings or interest within sixty (60) days from such assumption.\nThe same rule shall apply where the public official or employee is a partner in a partnership.\nThe requirement of divestment shall not apply to those who serve the Government in an honorary capacity nor to laborers and casual or temporary workers."}},{"id":"PH-H5210-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Review and Compliance Procedure. - (a) The designated Committees of both Houses of the Congress shall establish procedures for the review of statements to determine whether said statements which have been submitted on time, are complete, and are in proper form. In the event a determination is made that a statement is not so filed, the appropriate Committee shall so inform the reporting individual and direct him to take the necessary corrective action.\n(b) In order to carry out their responsibilities under this Act, the designated Committees of both Houses of Congress shall have the power within their respective jurisdictions, to render any opinion interpreting this Act, in writing, to persons covered by this Act, subject in each instance to the approval by affirmative vote of the majority of the particular House concerned.\nThe individual to whom an opinion is rendered, and any other individual involved in a similar factual situation, and who, after issuance of the opinion acts in good faith in accordance with it shall not be subject to any sanction provided in this Act.\n(c) The heads of other offices shall perform the duties stated in subsections (a) and (b) hereof insofar as their respective offices are concerned, subject to the approval of the Secretary of Justice, in the case of the Executive Department and the Chief Justice of the Supreme Court, in the case of the Judicial Department."}},{"id":"PH-H5210-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Penalties. - (a) Any public official or employee, regardless of whether or not he holds office or employment in a casual, temporary, holdover, permanent or regular capacity, committing any violation of this Act shall be punished with a fine not exceeding the equivalent of six (6) months' salary or suspension not exceeding one (1) year, or removal depending on the gravity of the offense after due notice and hearing by the appropriate body or agency. If the violation is punishable by a heavier penalty under another law, he shall be prosecuted under the latter statute. Violations of Sections 7, 8 or 9 of this Act shall be punishable with imprisonment not exceeding five (5) years, or a fine not exceeding five thousand pesos (P5,000), or both, and, in the discretion of the court of competent jurisdiction, disqualification to hold public office.\n(b) Any violation hereof proven in a proper administrative proceeding shall be sufficient cause for removal or dismissal of a public official or employee, even if no criminal prosecution is instituted against him.\n(c) Private individuals who participate in conspiracy as co-principals, accomplices or accessories, with public officials or employees, in violation of this Act, shall be subject to the same penal liabilities as the public officials or employees and shall be tried jointly with them.\n(d) The official or employee concerned may bring an action against any person who obtains or uses a report for any purpose prohibited by Section 8 (D) of this Act. The Court in which such action is brought may assess against such person a penalty in any amount not to exceed twenty-five thousand pesos (P25,000). If another sanction hereunder or under any other law is heavier, the latter shall apply."}},{"id":"PH-H5210-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Promulgation of Rules and Regulations, Administration and Enforcement of this Act. - The Civil Service Commission shall have the primary responsibility for the administration and enforcement of this Act. It shall transmit all cases for prosecution arising from violations of this Act to the proper authorities for appropriate action: Provided, however, That it may institute such administrative actions and disciplinary measures as may be warranted in accordance with law. Nothing in this provision shall be construed as a deprivation of the right of each House of Congress to discipline its Members for disorderly behavior.\nThe Civil Service Commission is hereby authorized to promulgate rules and regulations necessary to carry out the provisions of this Act, including guidelines for individuals who render free voluntary service to the Government. The Ombudsman shall likewise take steps to protect citizens who denounce acts or omissions of public officials and employees which are in violation of this Act."}},{"id":"PH-H5210-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Provisions for More Stringent Standards. - Nothing in this Act shall be construed to derogate from any law, or any regulation prescribed by any body or agency, which provides for more stringent standards for its official and employees."}},{"id":"PH-H5210-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Appropriations. - The sum necessary for the effective implementation of this Act shall be taken from the appropriations of the Civil Service Commission. Thereafter, such sum as may be needed for its continued implementation shall be included in the annual General Appropriations Act."}},{"id":"PH-H5210-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause. - If any provision of this Act or the application of such provision to any person or circumstance is declared invalid, the remainder of the Act or the application of such provision to other persons or circumstances shall not be affected by such declaration."}},{"id":"PH-H5210-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealing Clause. - All laws, decrees and orders or parts thereof inconsistent herewith, are deemed repealed or modified accordingly, unless the same provide for a heavier penalty."}},{"id":"PH-H5210-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity. - This Act shall take effect after thirty (30) days following the completion of its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5211"] = {"id":"PH-H5211","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6714_1989.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Merging, Dividing, and/or Reviving the Different Barangays in Caloocan City and for other purposes","orig":"An Act Merging, Dividing, and/or Reviving the Different Barangays in Caloocan City and for other purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6714","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-20","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6714_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5211-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The seventy (70) barangays constituting the first congressional district of Caloocan City are hereby reduced to only thirty (30) barangays as follows:\na. Barangay Nos. 1, 2, 3 and 4 are hereby merged and shall be known as Barangay Sangandaan Norte with the following boundaries:\nNorth\nCaloocan-Malabon boundary South General San Miguel Street East Railroad tracks West Caloocan-Malabon boundary (See Illustrative Map. No. 1)\nb. Barangay Nos. 77, 78, 79, 80, and 81 are hereby merged and shall be known as Barangay Bonifacio with the following boundaries:\nNorth\nCaloocan-Malabon boundary South Samson Road and EDSA East Manila Central University Wall along Gen. Simeon Street West Railroad tracks (See Illustrative Map. No. 2)\nc. Barangay Nos. 82, 83, 84 and 85 are hereby merged and shall be known as Barangay Morning Breeze with the following boundaries:\nNorth\nReparo Road\nSouth\nEDSA\nEast\nGen. Tinio Street\nWest\nMCU Wall along Gen. Simeon Street (See Illustrative Map No. 3)\nd. Barangay Nos. 132 and 133 are hereby merged and shall be known as Barangay Zapote with the following boundaries:\nNorth\nReparo Road\nSouth\nZapote Road\nEast\nGen. Malvar Extension\nWest\nGe. Tinio Street (See Illustrative Map No. 4)\ne. Barangay Nos. 134, 135, 136, 137, 138 and 139 are hereby merged and shall be known as Barangay Unang Sigaw with the following boundaries:\nNorth\nZapote Road\nSouth\nEDSA\nEast\nCaloocan-Quezon City boundary West Gen. Tinio Street (See Illustrative Map No. 5)\nf. Barangay Nos. 142, 143, 144 and 145 are hereby merged and shall be known as Barangay Bagong Barrio Norte with the following boundaries:\nNorth\nReparo Road\nSouth\nMalolos Avenue\nEast\nG. de Jesus Street to Reparo Road to M. de Castro to Gen. Tirona West Mariano Ponce Street to M. de Castro to Gen. Malvar Extension (See Illustrative Map No. 6)\ng. Barangay Nos. 140, 141, 147, 151 and 154 are hereby merged and shall be known as Barangay Bagong Barrio Sur with the following boundaries:\nNorth\nMalolos Avenue\nSouth\nZapote Road\nEast\nCaloocan-Quezon City boundary West Malolos Avenue (See Illustrative Map No. 7)\nh. Barangay Nos. 146, 148, 148 and 150 are hereby merged and shall be known as Barangay Tandang Sora with the following boundaries:\nNorth\nReparo Road\nSouth\nMalolos Avenue\nEast\nMilagros Street\nWest\nG. de Jesus from Reparo Road then to Gen. Tirona Street (See Illustrative Map No. 8)\ni. Barangay Nos. 152, 153 and 155 are hereby merged and shall be known as Barangay 25 ng Pebrero with the following boundaries:\nNorth\nReparo Road\nSouth\nMalolos Avenue\nEast\nNorth Diversion Road from Reparo Road to Malolos Avenue\nWest\nMilagros Street (See Illustrative Map No. 9)\nj. Barangay Nos. 156, 157, 158 and 159 are hereby merged and shall be known as Barangay Baesa Sur with the following boundaries:\nNorth\nBarangay 162 South North Diversion Road East Caloocan-Quezon City boundary West Barangay 160 (See Illustrative Map No. 10)\nk. Barangay Nos. 160 and 161 are hereby merged and shall be known as Barangay Baesa Norte with the following boundaries:\nNorth\nCaloocan-Valenzuela boundary South Barangay 157-159 East Caloocan-Valenzuela boundary West Caloocan-Valenzuela boundary (See Illustrative Map No. 11)\nl. Barangay Nos. 162 and 163 are hereby merged and shall be known as Barangay Sta. Quiteria with the following boundaries:\nNorth\nCaloocan-Valenzuela boundary South Barangay 159 East Caloocan-Quezon City boundary West Caloocan-Valenzuela boundary (See Illustrative Map No. 12)\nm. Barangay No. 164 shall be known as Barangay Talipapa with the following boundaries:\nNorth\nCaloocan-Valenzuela boundary South Barangay 162 East Barangay 163 West Caloocan-Valenzuela boundary (See Illustrative Map No. 13)\nn. Barangay No. 165 shall be known as Barangay Bagbaguin with the following boundaries:\nNorth\nBarangay 167-165 South Caloocan-Valenzuela boundary East Barangay 166-165 West Caloocan-Valenzuela boundary (See Illustrative Map No. 14)\no. Barangay No. 166 shall be known as Barangay Caybiga with the following boundaries:\nNorth\nBarangay 169-166 South Barangay 166-165 East Valenzuela-Caloocan boundary West Barangay 166-165 (See Illustrative Map No. 15)\np. Barangay Nos. 167 and 169 are hereby merged and shall be known as Barangay Llano with the following boundaries:\nNorth\nBagumbong to Deparo Road\nSouth\nCaybiga\nEast\nCaloocan-Quezon City boundary West Valenzuela (See Illustrative Map No. 16)\nq. Barangay Nos. 168, 170 and 172 are hereby merged and shall be known as Barangay Deparo with the following boundaries:\nNorth\nCongressional Road to Camarin\nSouth\nDeparo Road\nEast\nOld Zabarte Road\nWest\nBarangay 171-168 (See Illustrative Map No. 17)\nr. Barangay Nos. 171 and 173 are hereby merged and shall be known as Barangay Bagumbong with the following boundaries:\nNorth\nBarangay 175-173 South Barangay 167 Southeast Camarin Road Southwest Congressional Road West Caloocan-Bulacan boundary (See Illustrative Map No. 18)\ns. Barangay No. 174 shall be known as Barangay Camarin Este with the following boundaries:\nNorth\nBarangay 187 boundary South Camarin Road East Barangay 178 West Old Zabarte Road (See Illustrative Map No. 19)\nt. Barangay 175 shall be known as Barangay Camarin Norte with the following boundaries:\nNorth\nBarangay 176 (Bagong Silang) South Barangay 171 East Barangay 173 West Caloocan-Bulacan boundary (See Illustrative Map No. 20)\nu. Barangay Nos. 177 and 178 are hereby merged and shall be known as Barangay Camarin Sur with the following boundaries:\nNorth\nCamarin Road to Creek\nSouth\nCaloocan-Quezon City boundary East Barangay 179 West Old Zabarte Road (See Illustrative Map No. 21)\nv. Phases I and II of Barangay 176 (Bagong Silang) shall become a separate barangay and shall be known as Barangay Timog Silangan Bagong Silang with the following boundaries:\nNorth\nPhase VIII\nSouth\nPhase III-B\nEast\nPhase V-A\nWest\nPhase IV (See Illustrative Map No. 22)\nw. Phase IV of Barangay 176 (Bagong Silang) shall become a separate barangay and shall be known as Barangay Kanluran Bagong Silang with the following boundaries:\nNorth\nPhase IX\nSouth\nPhase III-B\nEast\nPhase I\nWest\nBarangay 175 (See Illustrative Map No. 23)\nx. Phases III and V-A of Barangay 176 (Bagong Silang) shall become a separate barangay and shall be known as Barangay Timog Bagong Silang with the following boundaries:\nNorth\nPhase I to Phase II\nSouth\nBarangay Camarin\nEast\nTala Leprosarium\nWest\nCamarin Road (See Illustrative Map No. 24)\ny. Phase VII and VIII of Barangay 176 (Bagong Silang) shall become a separate barangay and shall be known as Barangay Hilaga-Silangan Bagong Silang with the following boundaries:\nNorth\nMarilao River\nSouth\nPhase II\nEast\nTala Leprosarium\nWest\nPhase IX (See Illustrative Map No. 25)\nz. Phases IX and X of Barangay 176 (Bagong Silang) shall become a separate barangay and shall be known as Barangay Bagong Silang Hilaga with the following boundaries:\nNorth\nBulacan boundary South Phase IV East Estate of Cipriano Francia West Bulacan boundary (See Illustrative Map No. 26) a.a. Barangay Nos. 179, 180 and 183 are hereby merged and shall be known as Barangay Amparo with the following boundaries:\nNorth\nBarangays 187 and 184 South Barangay 178, Caloocan-Quezon City boundary East Quirino Highway West Barangay 178 (See Illustrative Map No. 27) b.b. Barangay Nos. 181 and 182 are hereby merged and shall be known as Barangay Pangarap with the following boundaries:\nNorth\nSapang-alat River, Caloocan-Bulacan boundary South Quirino Highway, Caloocan-Quezon City boundary East Caloocan-Bulacan, Caloocan-San Mateo boundary West Quirino Highway (See Illustrative Map No. 28) c.c. Barangay Nos. 184, 185 and 186 are hereby merged and shall be known as Barangay Malaria with the following boundaries:\nNorth\nCaloocan-Bulacan boundary South Barangays 188, 183 and 180 East Quirino Highway West Bagong Silang and Tala Leprosarium (See Illustrative Map No. 29) d.d. Barangay Nos. 187 and 188 are hereby merged and shall be known as Barangay Tala with the following boundaries:\nNorth\nBarangay 186 South Barangays 180 and 178 East Barangays 185 and 186 West Barangays 176 and 175 (See Illustrative Map No. 30)"}},{"id":"PH-H5211-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The one hundred eighteen (118) barangays composing the second congressional district of Caloocan City are hereby reduced to thirty (30) barangays as follows:\na. Barangay Nos. 5, 6, 7 and 8 are hereby merged and shall be known as Barangay Sangandaan Sur with the following boundaries:\nNorth\nGen. San Miguel Street\nSouth\nVelasco Street to Gen. Geronimo\nEast\nRailroad tracks West Cut-off canal from Barangay 8 to Barangay 12 (See Illustrative Map No. 31)\nb. Barangay Nos. 9, 10, 11 and 12 are hereby merged and shall be known as Barangay Talisay with the following boundaries:\nNorth\nVelasco Street to Gen. Geronimo Street\nSouth\nLibis Talisay Street to Lakas ng Mahirap to Plaridel Street East Railroad tracks West Cut-off canal from Barangay 12 to Barangay 14 (See Illustrative Map No. 32)\nc. Barangay Nos. 13, 14 and 16 are hereby merged and shall be known as Barangay Oscar Baello with the following boundaries:\nNorth\nLibis Talisay Street to Lakas ng Mahirap to Plaridel Street South Balong Bato to A. Mabini to P. Burgos East Torres Bugallon Street to A. Mabini Street West Cut-off canal from Barangay 14 to Barangay 16 (See Illustrative Map No. 33)\nd. Barangay Nos. 15, 17 and 18 are hereby merged and shall be known as Barangay Emilio Sanchez with the following boundaries:\nNorth\nBalong Bato and P. Burgos Streets\nSouth\nLibis Nadurata from cut-off canal to Doña Consuelo to railroad tracks East Railroad tracks West Cut-off canal from Barangay 16 to Barangay 18 (See Illustrative Map No. 34)\ne. Barangay Nos. 19, 20 and 22 are hereby merged and shall be known as Barangay Col. Pacheco with the following boundaries:\nNorth\nLibis Nadurata Street to Doña Consuelo to railroad tracks South C-3 Highway East Railroad tracks West cut-off canal from Barangay 18 to Barangay 22 (See Illustrative Map No. 35)\nf. Barangay Nos. 21, 23 and 24 are hereby merged and shall be known as Barangay Cayong Asistio with the following boundaries:\nNorth\nC-3 Highway\nSouth\nMarcela Street, A. Mabini, Laong Laan to railroad tracks East\nA. Mabini Street to Laong Laan and railroad tracks West San Diego Street (See Illustrative Map No. 36)\ng. Barangay Nos. 26, 27 and 28 are hereby merged and shall be known as Barangay Lerma with the following boundaries:\nNorth\nMarcelo Street\nSouth\nBinangonan Street\nEast\nA. Mabini\nWest\nCut-off canal from Barangay 22 to Barangay 28 (See Illustrative Map No. 37)\nh. Barangay Nos. 25, 29, 32 and 33 are hereby merged and shall be known as Barangay Silangan Maypajo with the following boundaries:\nNorth\nLaong Laan Street\nSouth\nCaloocan-Manila boundary East Railroad tracks West\nA. Mabini (See Illustrative Map No. 38)\ni. Barangay Nos. 30, 31, 34 and 35 are hereby merged and shall be known as Barangay Maypajo Kanluran with the following boundaries:\nNorth\nBinangonan Street\nSouth\nCaloocan-Manila boundary East\nA. Mabini Street\nWest\nCut-off canal from Barangay 28 to Barangay 34 (See Illustrative Map No. 39)\nj. The area north of the Dagat-Dagatan Project of the NHA is hereby constituted as a separated barangay which shall be known as Barangay Hilaga Dagat-Dagatan with the following boundaries:\nNorth\nLetre Road to Dagat-Dagatan Avenue to Lapu-Lapu Street\nSouth\nC-3 Highway\nEast\nCut-off canal from Barangay 8 to Barangay 22 West Caloocan-Malabon boundary and Caloocan-Navotas boundary (See Illustrative Map No. 40)\nk. The area south of the Dagat-Dagatan Project of the NHA is hereby constituted as a separate barangay which shall be known as Barangay Timog Dagat-Dagatan with the following boundaries:\nNorth\nC-3 Highway\nSouth\nCaloocan-Manila boundary East Cut-off canal from Barangay 28 to Barangay 34 West Caloocan-Navotas boundary (See Illustrative Map No. 41)\nl. Barangay Nos. 36 and 37 are hereby merged and shall be known as Barangay Marulas with the following boundaries:\nNorth\nC. Name Street from railroad tracks South Manila-Caloocan boundary East\nC. Name Street to Caloocan-Manila boundary West Railroad tracks (See Illustrative Map No. 42)\nm. Barangay Nos. 38, 39, 40, 41 and 42 are hereby merged and shall be known as Barangay Venus with the following boundaries:\nNorth 2nd Avenue to Rizal Avenue Extension South Manila-Caloocan boundary, C. Name Street East Rizal Avenue Extension West\nC. Name Street to corner 2nd Avenue (See Illustrative Map No. 43)\nn. Barangay Nos. 43, 46, 49 and 50 are hereby merged and shall be known as Barangay Timog Daang Bakal with the following boundaries:\nNorth 6th Avenue to Baltazar Street to 5th Avenue South 2nd Avenue East\nD. Aquino Street from 2nd to 4th Avenue and P. Sevilla from 4th to 5th Avenue West Railroad tracks (See Illustrative Map No. 44)\no. Barangay Nos. 52, 53, 56 and 59 are hereby merged and shall be known as Barangay Daang Bakal Sentro with the following boundaries:\nNorth 9th Avenue to Baltazar Street to 7th Avenue South 6th Avenue to Baltazar Street to 5th Avenue East\nD. Aquino from 5th Avenue to 7th Avenue and Baltazar Street from 7th to 9th Avenue West Railroad tracks (See Illustrative Map No. 45)\np. Barangay Nos. 63, 64, 65 and 73 are hereby merged and shall be known as Barangay Daang Bakal Hilaga with the following boundaries:\nNorth\nSamson Road\nSouth 9th Avenue East Baltazar Street to Heroes del 96 to Masagana Street West Railroad tracks (See Illustrative Map No. 46)\nq. Barangay Nos. 44, 45, 47, 48, 51, 55 and 54 are hereby merged and shall be known as Barangay Don Toribio Teodoro with the following boundaries:\nNorth 7th Avenue South 2nd Avenue East Rizal Avenue Extension West\nD. Aquino from 2nd Avenue to 4th Avenue to P. Sevilla Street from 4th to 5th Avenue to D. Aquino from 4th to 7th Avenue (See Illustrative Map No. 47)\nr. Barangay Nos. 57, 58, 60, 61 and 62 are hereby merged and shall be known as Barangay Grace Park with the following boundaries:\nNorth 10th Avenue South 7th Avenue East Rizal Avenue Extension West Baltazar Street (See Illustrative Map No. 48)\ns. Barangay Nos. 66, 67, 68, 69 and 71 are hereby merged and shall be known as Barangay Grace Park Hilaga which shall have the following boundaries:\nNorth\nGonzales Street to Victory Liner Wall\nSouth 10th Avenue East Rizal Avenue Extension West Heroes del 96 up to Gonzales Street (See Illustrative Map No. 49)\nt. Barangay Nos. 70, 72, 74, 75 and 76 are hereby merged and shall be known as Barangay Calaanan and shall have the following boundaries:\nNorth\nSamson Road\nSouth\nGonzales Street up to Victory Liner Wall East Rizal Avenue Extension West Masagana Street (See Illustrative Map No. 50)\nu. Barangay Nos. 86, 87, 88, 89, 90 and 91 are hereby merged and shall be known as Barangay Our Lady of Grace and shall have the following boundaries:\nNorth\nEDSA\nSouth 10th Avenue East 6th Street to G. de Jesus Street West Rizal Avenue Extension (See Illustrative Map No. 51)\nv. Barangay Nos. 92, 93, 94, 96 and 97 are hereby merged and shall be known as Barangay Biglang Awa and shall have the following boundaries:\nNorth\nEDSA\nSouth 10th Avenue East Rosal and A. Cruz Streets to Biglang Awa West 6th Street to G. de Jesus Street (See Illustrative Map No. 52)\nw. Barangay Nos. 95, 98, 99 and 100 are hereby merged and shall be known as Barangay Balintawak with the following boundaries:\nNorth\nEDSA\nSouth 10th Avenue East Caloocan-Quezon City boundary West Rosal Street from 11th Avenue to Catleya Street to A. Cruz Street to Biglang Awa Street (See Illustrative Map No. 53)\nx. Barangay Nos. 101, 102 and 105 are hereby merged and shall be known as Barangay Galino with the following boundaries:\nNorth 10th Avenue and 11th Avenue South 7th Avenue East Caloocan-Quezon City boundary West 9th Street from 7th to 10th Avenue (See Illustrative Map No. 54)\ny. Barangay Nos. 103, 104, 106, 107, 108 and 109 are hereby merged and shall be known as Barangay Silangan Grace Park with the following boundaries:\nNorth 10th Avenue South 7th Avenue East 9th Street from 7th to 10th Avenue West Rizal Avenue Extension (See Illustrative Map No. 55)\nz. Barangay Nos. 110, 111, 112, 113, 114, 115, 116 and 123 are hereby merged and shall be known as Barangay Pio del Pilar and shall have the following boundaries:\nNorth 7th Avenue South 5th Avenue East 7th Street from 5th to 6th Avenue and 5th Street from 6th to 7th Avenue West Rizal Avenue Extension (See Illustrative Map. No. 56) a.a. Barangay Nos. 117, 118, 119 and 120 are hereby merged and shall be known as Barangay Maligaya with the following boundaries:\nNorth 5th Avenue South Caloocan-Manila boundary East La Loma Cemetery West Rizal Avenue Extension (See Illustrative Map No. 57) b.b. Barangay Nos. 121, 122, 124 and 125 are hereby merged and shall be known as Barangay Banal and shall have the following boundaries:\nNorth 7th Avenue South 5th Avenue East Caloocan-Quezon City West 7th Street from 5th to 6th Avenue and 5th Street from 6th to 7th Avenue (See Illustrative Map. No. 58) c.c. Barangay Nos. 126, 127 and 128 are hereby merged and shall be known as Barangay San Jose Hilaga and shall have the following boundaries:\nNorth\nBarangay Banal\nSouth\nBuagan Street\nEast\nCaloocan-Quezon city boundary West La Loma Cemetery (See Illustrative Map No. 59) d.d. Barangay Nos. 129, 130 and 131 are hereby merged and shall be known as Barangay San Jose Timog and shall have the following boundaries:\nNorth\nBuagan Street\nSouth\nCaloocan-Quezon City boundary East Caloocan-Quezon City boundary West La Loma Cemetery (See Illustrative Map No. 60)"}},{"id":"PH-H5211-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first officials of the barangays created under this Act shall be elected during the regular barangay elections scheduled as provided by law. Meanwhile, the existing barangays shall continue to function under their regularly elected or appointed barangay officials in accordance with law."}},{"id":"PH-H5211-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Upon assumption of office of the first set of barangay officials of the barangays created under this Act, the old barangays shall be out of existence and all their moneys, properties and obligations shall be assumed by the new succeeding barangay."}},{"id":"PH-H5211-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The merger, division and/or revival of the different barangays as herein provided shall take effect if a majority of the voters who cast their votes shall approve the same in a plebiscite that shall be called for that purpose in Caloocan City by the Commission on Elections within thirty (30) days from the approval of this Act by the President of the Philippines."}},{"id":"PH-H5211-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The expenses in holding the plebiscite provided in Section 5 hereof shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5211-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5212"] = {"id":"PH-H5212","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6715_1989.html","fetchedAt":"2026-10-06","articleCount":40,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Extend Protection to Labor, Strengthen the Constitutional Rights of Workers to Self-Organization, Collective Bargaining and Peaceful Concerted Activities, Foster Industrial Peace and Harmony, Promote the Preferential Use of Voluntary Modes of Settling Labor Disputes, and Reorganize the National Labor Relations Commission, Amending for These Purposes Certain Provisions of Presidential Decree No. 442, as Amended, Otherwise Known as the Labor Code of the Philippines, Appropriating Funds Therefore and for Other Purposes","orig":"An Act to Extend Protection to Labor, Strengthen the Constitutional Rights of Workers to Self-Organization, Collective Bargaining and Peaceful Concerted Activities, Foster Industrial Peace and Harmony, Promote the Preferential Use of Voluntary Modes of Settling Labor Disputes, and Reorganize the National Labor Relations Commission, Amending for These Purposes Certain Provisions of Presidential Decree No. 442, as Amended, Otherwise Known as the Labor Code of the Philippines, Appropriating Funds Therefore and for Other Purposes"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 6715","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-02","completenessNote":"全文，共 40 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6715_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5212-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article 110 of Presidential Decree No. 442 , amended, otherwise known as the Labor Code of the Philippines, is hereby further amended to read as follows:\n\"Article 110. Worker preference in case of bankruptcy. - In the event of bankruptcy or liquidation of an employer's business, his workers shall enjoy first preference as regards their unpaid wages and other monetary claims, any provision of law to the contrary notwithstanding. Such unpaid wages and monetary claims shall be paid in full before the claims of the Government and other creditors may be paid.\""}},{"id":"PH-H5212-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Article 129 of the Labor Code of the Philippines , as amended, is hereby further amended to read as follows:\n\"Article 129. Recovery of wages, simple money claims and other benefits. - Upon complaint of any interested party, the Regional Director of the Department of Labor and Employment or any of the duly authorized hearing officers of the Department is empowered, through summary proceeding and after due notice, to hear and decide any matter involving the recovery of wages and other monetary claims and benefits, including legal interest, owing to an employee or person employed in domestic or household service or househelper under this Code, arising from employer-employee relations: Provided, That such complaint does not include a claim for reinstatement: Provided, further, That the aggregate money claims of each employee or househelper do not exceed five thousand pesos (P5,000.00). The Regional Director or hearing officer shall decide or resolve the complaint within thirty (30) calendar days from the date of the filing of the same. Any sum thus recovered on behalf of any employee or househelper pursuant to this Article shall be held in a special deposit account, and shall be paid, on order of the Secretary of Labor and Employment or the Regional Director directly to the employee or househelper concerned. Any such sum not paid to the employee or househelper, because he cannot be located after diligent and reasonable effort to locate him within a period of three (3) years, shall be held as a special fund of the Department of Labor and Employment to be used exclusively for the amelioration and benefit of workers.\n\"Any decision or resolution of the Regional Director or hearing officer pursuant to this provision may be appealed on the same grounds provided in Article 223 of this Code, within five (5) calendar days from receipt of a copy of said decision or resolution, to the National Labor Relations Commission which shall resolve the appeal within ten (10) calendar days from the submission of the last pleading required or allowed under its rules.\n\"The Secretary of Labor and Employment or his duly authorized representative may supervise the payment of unpaid wages and other monetary claims and benefits, including legal interest, found owing to any employee or house helper under this Code.\""}},{"id":"PH-H5212-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Article 211 of the same Code , as amended by Executive Order No. 111, is hereby further amended to read as follows:\n\"Article 211. Declaration of policy. - A. It is the policy of the State:\n\"(a) To promote and emphasize the primacy of free collective bargaining and negotiations, including voluntary arbitration, mediation and conciliation, as modes of settling labor or industrial disputes;\n\"(b) To promote free trade unionism as an instrument for the enhancement of democracy and the promotion of social justice and development;\n\"(c) To foster the free and voluntary organization of a strong and united labor movement;\n\"(d) To promote the enlightenment of workers concerning their rights and obligations as union members and as employees;\n\"(e) To provide an adequate administrative machinery for the expeditious settlement of labor or industrial disputes;\n\"(f) To ensure a stable but dynamic and just industrial peace; and \"(g) To ensure the participation of workers in decision and policy-making processes affecting their rights, duties and welfare.\n\"B. To encourage a truly democratic method of regulating the relations between the employers and employees by means of agreements freely entered into through collective bargaining, no court or administrative agency or official shall have the power to set or fix wages, rates of pay, hours of work or other terms and conditions of employment, except as otherwise provided under this Code.\""}},{"id":"PH-H5212-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Article 212 of the Labor Code of the Philippines , as amended, is further amended to read as follows:\n\"Article 212. Definitions. - (a) \"Commission\" means the National Labor Relations Commission or any of its divisions, as the case may be, as provided under this Code.\n\"(b) \"Bureau\" means the Bureau of Labor Relations and/or the Labor Relations Divisions in the regional offices established under Presidential Decree No. 1, in the Department Labor.\n\"(c) \"Board\" means the National Conciliation and Mediation Board established under Executive Order No. 126.\n\"(d) \"Council\" means the Tripartite Voluntary Arbitration Advisory Council established under Executive Order No. 126, as amended.\n\"(e) \"Employer\" includes any person acting in the interest of an employer, directly or indirectly. The term shall not include any labor organization or any of its officers or agents except when acting as employer.\n\"(f) \"Employee\" includes any person in the employ of an employer. The term shall not be limited to the employees of a particular employer, unless this Code so explicitly states. It shall include any individual whose work has ceased as a result of or in connection with any current labor dispute or because of any unfair labor practice if he has not obtained any other substantially equivalent and regular employment.\n\"(g) \"Labor organization\" means any union or association of employees which exists in whole or in part for the purpose of collective bargaining or of dealing with employers concerning terms and conditions of employment.\n\"(h) \"Legitimate labor organization\" means any labor organization duly registered with the Department of Labor and Employment, and includes any branch or local thereof.\n\"(i) \"Company union\" means any labor organization whose information, function or administration has been assisted by any act defined as unfair labor practice by this Code.\n\"(j) \"Bargaining representative\" means a legitimate labor organization or any officer or agent of such organization whether or not employed by the employer.\n\"(k) \"Unfair labor practice\" means any unfair labor practice as expressly defined by this Code.\n\"(l) \"Labor dispute\" includes any controversy or matter concerning terms or conditions of employment or the association or representation of persons in negotiating, fixing, maintaining, changing or arranging the terms and conditions of employment, regardless of whether, the disputants stand in the proximate relation of employer and employee.\n\"(m) \"Managerial employee\" is one who is vested with powers or prerogatives to lay down and execute management policies and/or to hire, transfer, suspend, lay-off, recall, discharge, assign or discipline employees. Supervisory employees are those who, in the interest of the employer, effectively recommend such managerial actions if the exercise of such authority is not merely routinary or clerical in nature but requires the use of independent judgment. All employees not falling within any of the above definitions are considered rank-and-file employees for purposes of this Book.\n\"(n) \"Voluntary Arbitrator\" means any person accredited by the Board as such, or any person named or designated in the collective bargaining agreement by the parties to act as their voluntary arbitrator, or one chosen, with or without the assistance of the National Conciliation and Mediation Board, pursuant to a selection procedure agreed upon in the collective bargaining agreement, or any official that may be authorized by the Secretary of Labor and Employment to act as voluntary arbitrator upon the written request and agreement of the parties to a labor dispute.\n\"(o) \"Strike\" means any temporary stoppage of work by the concerted action of employees as a result of an industrial or labor dispute.\n\"(p) \"Lockout\" means the temporary refusal of an employer to furnish work as a result of an industrial or labor dispute.\n\"(q) \"Internal union dispute\" includes all disputes or grievances arising from any violation of or disagreement over any provision of the constitution and by-laws of a union, including, any violation of the rights and conditions of union membership provided for in this Code.\n\"(r) \"Strike-breaker\" means any person who obstructs, impedes, or interferes with by force, violence, coercion, threats or intimidation any peaceful picketing by employees during any labor controversy affecting wages, hours or conditions of work or in the exercise of the right of self-organization or collective bargaining.\n\"(s) \"Strike area\" means the establishment, warehouses, depots, plants or offices, including the sites or premises used as runaway shops, of the employer struck against, as well as the immediate vicinity actually used by picketing strikers in moving to and fro before all points of entrance to and exit from said establishment.\""}},{"id":"PH-H5212-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Article 213 of the Labor Code of the Philippines , as amended, is further amended to read as follows:\n\"Article 213. National Labor Relations Commission. - There shall be a National Labor Relations Commission which shall be attached to the Department of Labor and Employment for program and policy coordination only, composed of a Chairman and fourteen (14) members.\n\"Five (5) members each shall be chosen from among the nominees of the workers and employers organizations, respectively. The Chairman and the four (4) remaining members shall come from the public sector, with the latter to be chosen from among the recommendees of the Secretary of Labor and Employment.\n\"Upon assumption into office, the members nominated by the workers and employers organizations shall divest themselves of any affiliation with or interest in the federation or association to which they belong.\n\"The Commission may sit en banc or in five (5) divisions, each composed of three (3) members. The Commission shall sit en banc only for purposes of promulgating rules and regulations governing the hearing and disposition of cases before any of its divisions and regional branches and formulating policies affecting its administration and operations. The Commission shall exercise its adjudicatory and all other powers, functions, and duties through its divisions. Of the five (5) divisions, the first and second divisions shall handle cases coming from the National Capital Region and the third, fourth and fifth divisions, cases from other parts of Luzon, from the Visayas and Mindanao, respectively. The divisions of the Commission shall have exclusive appellate jurisdiction over cases within their respective territorial jurisdiction.\n\"The concurrence of two (2) Commissioners of a division shall be necessary for the pronouncement of a judgment or resolution. Whenever the required membership in a division is not complete and the concurrence of two (2) Commissioners to arrive at a judgment or resolution cannot be obtained, the Chairman shall designate such number of additional Commissioners from the other divisions as may be necessary.\n\"The conclusions of a division on any case submitted to it for decision shall be reached in consultation before the case is assigned to a member for the writing of the opinion. It shall be mandatory for the division to meet for the purposes of the consultation ordained herein. A certification to this effect signed by the Presiding Commissioner of the division shall be issued, and a copy thereof attached to the record of the case and served upon the parties.\n\"The Chairman shall be the Presiding Commissioner of the first division, and the four (4) other members from the public sector shall be the Presiding Commissioners of the second, third, fourth and fifth divisions, respectively. In case of the effective absence or incapacity of the Chairman, the Presiding Commissioner of the second division shall be the Acting Chairman.\n\"The Chairman, aided by the Executive Clerk of the Commission, shall have the administrative supervision over the Commission and its regional branches and all its personnel, including the Executive Labor Arbiters and Labor Arbiters.\n\"The Commission, when sitting en banc, shall be assisted by the same Executive Clerk, and, when acting thru its divisions, by said Executive Clerk for its first division and four (4) other Deputy Executive Clerks for the second, third, fourth and fifth divisions, respectively, in the performance of such similar or equivalent functions and duties as are discharged by the Clerk of Court and Deputy Clerks of Court of the Court of Appeals.\""}},{"id":"PH-H5212-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Article 214 of the same Code , as amended, is further amended to read as follows:\n\"Article 214. Headquarters, branches and provincial extension units. - The Commission and its first, second and third divisions shall have their main offices in Metropolitan Manila, and the fourth and fifth divisions in the cities of Cebu and Cagayan de Oro, respectively. The Commission shall establish as many regional branches as there are regional offices of the Department of Labor and Employment, sub-regional branches or provincial extension units. There shall be as many labor arbiters as may be necessary for the effective and efficient operation of the Commission. Each regional branch shall be headed by an Executive Labor Arbiter.\""}},{"id":"PH-H5212-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Article 215 of the same Code is amended to read as follows:\n\"Article 215. Appointment and qualification. - The Chairman and other Commissioners shall be members of the Philippine Bar and must have been engaged in the practice of law in the Philippines for at least fifteen (15) years, with at least five (5) years experience or exposure in the field of labor-management relations and shall preferably be residents of the region where they are to hold office. The Executive Labor Arbiters and Labor Arbiters shall likewise be members of the Philippine Bar and must have been engaged in the practice of law in the Philippines for at least seven (7) years, with at least three (3) years experience or exposure in the field of labor-management relations: Provided, however, That incumbent Executive Labor Arbiters and Labor Arbiters who have been engaged in the practice of law for at least five (5) years may be considered as already qualified for purposes of reappointment as such under this Act.\n\"The Chairman and the other Commissioners, the Executive Labor Arbiters and Labor Arbiters shall hold office during good behavior until they reach the age of sixty-five (65) years, unless sooner removed for cause as provided by law or become incapacitated to discharge the duties of their office.\n\"The Chairman, the Division Presiding Commissioners and other Commissioners shall all be appointed by the President, subject to confirmation by the Commission on Appointments. Appointment to any vacancy shall come from the nominees of the sector which nominated the predecessor. The Executive Labor Arbiters and Labor Arbiters shall also be appointed by the President, upon recommendation of the Secretary of Labor and Employment, and shall be subject to the Civil Service law, rules and regulations.\n\"The Secretary of Labor and Employment shall, in consultation with the Chairman of the Commission, appoint the staff and employees of the Commission and its regional branches as the needs of the service may require, subject to the Civil Service law, rules and regulations, and upgrade their current salaries, benefits and other emoluments in accordance with law.\""}},{"id":"PH-H5212-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Art. 216 of the same Code is amended to read as follows:\n\"Article 216. Salaries, benefits and other emoluments. - The Chairman and members of the Commission shall receive an annual salary at least equivalent to, and be entitled to the same allowances and benefits as, those of the Presiding Justice and Associate Justices of the Court of Appeals, respectively. The Executive Labor Arbiters shall receive an annual salary at least equivalent to that of an Assistant Regional Director of the Department of Labor and Employment and shall be entitled to the same allowances and benefits as that of a Regional Director of said department. The Labor Arbiters shall receive an annual salary at least equivalent to, and be entitled to the same allowances and benefits as, that of an Assistant Regional Director of the Department of Labor and Employment. In no case, however, shall the provision of this Article result in the diminution of existing salaries, allowances and benefits of the aforementioned officials.\""}},{"id":"PH-H5212-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Article 217 of the same code , as amended, is hereby further amended to read as follows:\n\"Article 217. Jurisdiction of Labor Arbiters and the Commission. - (a) Except as otherwise provided under this Code, the Labor Arbiters shall have the original and exclusive jurisdiction to hear and decide, within thirty (30) calendar days after the submission of the case by the parties for decision without extension, even in the absence of stenographic notes, the following cases involving all workers, whether agricultural or non-agricultural:\n\"(1) Unfair labor practice cases;\n\"(2) Termination disputes;\n\"(3) If accompanied with a claim for reinstatement, those cases that workers may file involving wages, rates of pay, hours of work and other terms and conditions of employment;\n\"(4) Claims for actual, moral, exemplary and other forms of damages arising from the employer-employee relations;\n\"(5) Cases arising from any violation of Article 264 of this Code, including questions involving the legality of strikes and lockouts; and \"(6) Except claims for employees compensation, social security, medicare and maternity benefits, all other claims arising from employer-employee relations, including those of persons in domestic or household service involving an amount exceeding five thousand pesos (P5,000), whether or not accompanied with a claim for reinstatement.\n\"(b) The Commission shall have exclusive appellate jurisdiction over all cases decided by Labor Arbiters.\n\"(c) Cases arising from the interpretation or implementation of collective bargaining agreements and those arising from the interpretation or enforcement of company personnel policies shall be disposed by the Labor Arbiter by referring the same to the grievance machinery and voluntary arbitration as may be provided in said agreements.\""}},{"id":"PH-H5212-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Article 218, paragraphs (a), (d) and (e) thereof are hereby amended to read as follows:\n\"(a) To promulgate rules and regulations governing the hearing and disposition of cases before it and its regional branches, as well as those pertaining to its internal functions and such rules and regulations as may be necessary to carry out the purposes of this Code;\n\"(d) To hold any person in contempt directly or indirectly and impose appropriate penalties therefor in accordance with law.\nA person guilty of misbehavior in the presence of or so near the Chairman or any member of the Commission or any Labor Arbiter as to obstruct or interrupt the proceedings before the same, including disrespect toward said officials, offensive personalities toward others, or refusal to be sworn or to answer as a witness, or to subscribe an affidavit or deposition when lawfully required to do so, may be summarily adjudged in direct contempt by said officials and punished by fine not exceeding five hundred pesos (P500) or imprisonment not exceeding five (5) days, or both if it be the Commission or a member thereof, or by a fine not exceeding one hundred pesos (P100) or imprisonment not exceeding one (1) day, or both if it be a Labor Arbiter.\nThe person adjudged in direct contempt by a Labor Arbiter may appeal to the Commission and the execution of the judgment shall be suspended pending the resolution of the appeal upon the filing of such person of a bond on a condition that he will abide by and perform the judgment of the Commission should the appeal be decided against him. Judgment of the Commission on direct contempt is immediately executory and unappealable. Indirect contempt shall be dealth with by the Commission or Labor Arbiter in the manner prescribed under Rule 71 of the Revised Rules of Court; and\n(e) To enjoin or restrain any actual or threatened commission of any or all prohibited or unlawful acts or to require the performance of a particular act in any labor dispute which, if not restrained or performed forthwith, may cause grave or irreparable damage to any party or render ineffectual any decision in favor of such party: Provided, That no temporary or permanent injunction in any case involving or growing out of a labor dispute as defined in this Code shall be issued except after hearing the testimony of witnesses, with opportunity for cross-examination, in support of the allegations of a complaint made under oath, and testimony in opposition thereto, if ordered, and only after a finding of fact by the Commission, to the effect:\n(1) That prohibited or unlawful acts have been threatened and will be committed unless restrained, or have been committed and will be continued unless restrained, but no injunction or temporary restraining order shall be issued on account of any threat, prohibited or unlawful act, except against the person or persons, association or organization making the threat or committing the prohibited or unlawful act or actually authorizing or ratifying the same after actual knowledge thereof;\n(2) That substantial and irreparable injury to complainant's property will follow;\n(3) That, as to each item of relief to be granted, greater injury will be inflicted upon defendants by the granting of relief;\n(4) That complainant has no adequate remedy at law; and\n(5) That the public officers charged with the duty to protect complainant's property are unable or unwilling to furnish adequate protection.\nSuch hearing shall be held after due and personal notice thereof has been served, in such manner as the Commission shall direct, to all known persons against whom relief is sought, and also to the Chief Executive and other public officials of the province or city within which the unlawful acts have been threatened or committed charged with the duty to protect complainant's property: Provided, however, That if a complainant shall also allege that, unless a temporary restraining order shall be issued without notices, a substantial and irreparable injury to complainant's property will be unavoidable, such a temporary restraining order may be issued upon testimony under oath, sufficient, if sustained, to justify the Commission in issuing a temporary injunction upon hearing after notice. Such a temporary restraining order shall be effective for no longer than twenty (20) days and shall become void at the expiration of said twenty (20) days. No such temporary restraining order or temporary injunction shall be issued except on condition that complainant shall first file an undertaking with adequate security in an amount to be fixed by the Commission sufficient to recompense those enjoined for any loss, expense or damage caused by the improvident or erroneous issuance of such order or injunction, including all reasonable costs, together with a reasonable attorney's fee, and expense of defense against the order or against the granting of any injunctive relief sought in the same proceeding and subsequently denied by the Commission.\nThe undertaking herein mentioned shall be understood to constitute an agreement entered into by the complainant and the surety upon which an order may be rendered in the same suit or proceeding against said complainant and surety, upon a hearing to assess damages, of which hearing complainant and surety shall have reasonable notice, the said complainant and surety submitting themselves to the jurisdiction of the Commission for that purpose. But nothing herein contained shall deprive any party having a claim or cause of action under or upon such undertaking from electing to pursue his ordinary remedy by suit at law or in equity: Provided, further, That the reception of evidence for the application of a writ of injunction may be delegated by the Commission to any of its Labor Arbiters who shall conduct such hearing in such places as he may determine to be accessible to the parties and their witnesses and shall submit thereafter his recommendation to the Commission.\""}},{"id":"PH-H5212-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Article 221 of the same Code is hereby amended to read as follows:\nArticle 221. Technical rules not binding and prior resort to amicable settlement. - In any proceeding before the Commission or any of the Labor Arbiters, the rules of evidence prevailing in courts of law and equity shall not be controlling, and it is the spirit and intention of this Code that the Commission and its members and the Labor Arbiters shall use every and all reasonable means to ascertain the facts in each case speedily and objectively, without regard to technicalities of law or procedure, all in the interest of due process. In any proceeding before the Commission or any Labor Arbiter, the parties may be represented by legal counsel but it shall be the duty of the Chairman, any Presiding Commissioner or Commissioner or any Labor Arbiter to exercise complete control of the proceedings at all stages.\nAny provision of law to the contrary notwithstanding, the Labor Arbiter shall exert all efforts towards the amicable settlement of a labor dispute within his jurisdiction on or before the first hearing. The same rule shall apply to the Commission in the exercise of its original jurisdiction."}},{"id":"PH-H5212-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Article 223 of the same Code is amended to read as follows:\n\"Article 223. Appeal. - Decisions, awards, or orders of the Labor Arbiter are final and executory unless appealed to the Commission by any or both parties within ten (10) calendar days from receipt of such decisions, awards, or orders. Such appeal may be entertained only on any of the following grounds:\n\"(a) If there is prima facie evidence of abuse of discretion on the part of the Labor Arbiter;\n\"(b) If the decision, order or award was secured through fraud or coercion, including graft and corruption;\n\"(c) If made purely on questions of law; and \"(d) If serious errors in the findings of facts are raised which would cause grave or irreparable damage or injury to the appellant.\nIn case of a judgment involving a monetary award, an appeal by the employer may be perfected only upon the posting of a cash or surety bond issued by a reputable bonding company duly accredited by the Commission in the amount equivalent to the monetary award in the judgment appealed from.\nIn any event, the decision of the Labor Arbiter reinstating a dismissed or separated employee, insofar as the reinstatement aspect is concerned, shall immediately be executory, even pending appeal. The employee shall either be admitted back to work under the same terms and conditions prevailing prior to his dismissal or separation or, at the option of the employer, merely reinstated in the payroll. The posting of a bond by the employer shall not stay the execution for reinstatement provided herein.\nTo discourage frivolous or dilatory appeals, the Commission or the Labor Arbiter shall impose reasonable penalty, including fines or censures, upon the erring parties.\nIn all cases, the appellant shall furnish a copy of the memorandum of appeal to the other party who shall file an answer not later than ten (10) calendar days from receipt thereof.\nThe Commission shall decide all cases within twenty (20) calendar days from receipt of the answer of the appellee.\n\"The decision of the Commission shall be final and executory after ten (10) calendar days from receipt thereof by the parties.\nAny law enforcement agency may be deputized by the Secretary of Labor and Employment or the Commission in the enforcement of decisions, awards, or orders.\""}},{"id":"PH-H5212-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Article 224 of the same Code is amended to read as follows:\nArticle 224. Execution of decisions, orders, or awards. - (a) The Secretary of Labor and Employment or any Regional Director, the Commission or any Labor Arbiter or Med-Arbiter, or the voluntary arbitrator or panel of voluntary arbitrators may, motu propio or on motion of any interested party, issue a writ of execution on a judgment within five (5) years from the date it becomes final and executory, requiring a sheriff or a duly deputized officer to execute or enforce final decisions, orders or awards of the Secretary of Labor and Employment or Regional Director, the Commission, or the Labor Arbiter or Med-Arbiter, or voluntary arbitrator or panel of voluntary arbitrators. In any case, it shall be the duty of the responsible officer to separately furnish immediately the counsels of record and the parties with copies of said decisions, orders and awards. Failure to comply with the duty prescribed herein shall subject such responsible officer to appropriate administrative sanctions.\n(b) The Secretary of Labor and Employment, and the Chairman of the Commission may designate special sheriffs and take any measure under existing laws to ensure compliance with their decisions, orders or awards and those of Labor Arbiters and voluntary arbitrators or panel of voluntary arbitrators, including the imposition of administrative fines which shall not be less than five hundred pesos (P500.00) nor more than ten thousand pesos (P10,000.00).\""}},{"id":"PH-H5212-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The second paragraph of Article 226 of the same Code is likewise hereby amended to read as follows:\n\"The Bureau shall have fifteen (15) calendar days to act on labor cases before it, subject to extension by agreement of the parties.\""}},{"id":"PH-H5212-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Articles 230, 231 and 232 of the same Code are amended to read as follows:\nArticle 230. Appointment of bureau personnel. - The Secretary of Labor and Employment may appoint, in addition to the present personnel of the Bureau and the Industrial Relations Divisions, such number of examiners and other assistants as may be necessary to carry out the purpose of this Code.\"\n\"Article 231. Registry of unions and file of collective agreements. - The Bureau shall keep a registry of legitimate labor organizations.\n\"The Bureau shall also maintain a file of all collective bargaining agreements and other related agreements and records of settlement of labor disputes, and copies of orders and decisions of voluntary arbitrators or panel of voluntary arbitrators. The file shall be open and accessible to interested parties under conditions prescribed by the Secretary of Labor and Employment, provided that no specific information submitted in confidence shall be disclosed unless authorized by the Secretary, or when it is at issue in any judicial litigation or when public interest or national security so requires.\nWithin thirty (30) days from the execution of a collective bargaining agreement, the parties shall submit copies of the same directly to the Bureau or the Regional Offices of the Department of Labor and Employment for registration accompanied with verified proofs of its posting in two conspicuous places in the place of work and ratification by the majority of all the workers in the bargaining unit. The Bureau or Regional Offices shall act upon the application for registration of such collective bargaining agreement within five (5) calendar days from receipt thereof. The Regional Offices shall furnish the Bureau with a copy of the collective bargaining agreement within five (5) days from its submission.\nThe Bureau or Regional Office shall assess the employer for every collective bargaining agreement a registration fee of not less than one thousand pesos (P1,000.00) or in any other amount as may be deemed appropriate and necessary by the Secretary of Labor and Employment for the effective and efficient administration of the voluntary arbitration program. Any amount collected under this provision shall accrue to the Special Voluntary Arbitration Fund.\nThe Bureau shall also maintain a file, and shall undertake or assist in the publication, of all final decisions, orders and awards of the Secretary of Labor and Employment, Regional Directors and the Commission.\"\nArticle 232. Prohibition on certification. - The Bureau shall not entertain any petition for certification election or any other action which may disturb the administration of duly registered existing collective bargaining agreements affecting the parties except under Articles 253, 253-A and 256 of this Code."}},{"id":"PH-H5212-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Paragraphs (c) and (j) of Article 241 of the same Code are amended to read as follows:\n(c) The members shall directly elect their officers in the local union, as well as their national officers in the national union or federation to which they or their local union is affiliated, by secret ballot at intervals of five (5) years. No qualification requirement for candidacy to any position shall be imposed other than membership in good standing in subject labor organization. The secretary or any other responsible union officer shall furnish the Secretary of Labor and Employment with a list of the newly-elected officers, together with the appointive officers or agents who are entrusted with the handling of funds within thirty (30) calendar days after the election of officers or from the occurrence of any change in the list of officers of the labor organization;\n\"(j) Every income or revenue of the organization shall be evidenced by a record showing its source, and every expenditure of its funds shall be evidenced by a receipt from the person to whom the payment is made, which shall state the date, place and purpose of such payment. Such record or receipt shall form part of the financial records of the organization.\n\"Any action involving the funds of the organization shall prescribe after three (3) years from the date of submission of the annual financial report to the Department of Labor and Employment or from the date the same should have been submitted as required by law, whichever comes earlier: Provided, That this provision shall apply only to a legitimate labor organization which has submitted the financial report requirements under this Code: Provided, further, That failure of any labor organization to comply with the periodic financial reports required by law and such rules and regulations promulgated thereunder six (6) months after the effectivity of this Act shall automatically result in the cancellation of union registration of such labor organization.'"}},{"id":"PH-H5212-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Article 242 of the same Code is amended to read as follows:\n\"Article 242. Rights of legitimate labor organizations. - A legitimate labor organization shall have the right:\n\"(a) To act as the representative of its members for the purpose of collective bargaining;\n\"(b) To be certified as the exclusive representative of all the employees in an appropriate collective bargaining unit for purposes of collective bargaining;\n\"(c) To be furnished by the employer, upon written request, with his annual audited financial statements, including the balance sheet and the profit and loss statement, within thirty (30) calendar days from the date of receipt of the request, after the union has been duly recognized by the employer or certified as the sole and exclusive bargaining representative of the employees in the bargaining unit, or within sixty (60) calendar days before, or during the collective bargaining negotiation.\n\"(d) To own property, real or personal, for the use and benefit of the labor organization and its members;\n\"(e) To sue and be sued in its registered name; and \"(f) To undertake all other activities designed to benefit the organization and its members, including cooperative, housing welfare and other projects not contrary to law.\n\"Notwithstanding any provision of a general or special law to the contrary, the income, and the properties of legitimate labor organizations, including grants, endowments, gifts, donations and contributions they may receive from fraternal and similar organizations, local or foreign, which are actually, directly and exclusively used for their lawful purposes, shall be free from taxes, duties and other assessments. The exemptions provided herein may be withdrawn only by a special law expressly repealing this provision.\""}},{"id":"PH-H5212-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Article 245 of the same Code , as amended, is hereby further amended to read as follows:\n\"Article 245. Ineligibility of managerial employees to join any labor organization; right of supervisory employees. - Managerial employees are not eligible to join, assist or form any labor organization. Supervisory employees shall not be eligible for membership in a labor organization of the rank-and-file employees but may join, assist or form separate labor organizations of their own.\""}},{"id":"PH-H5212-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The third paragraph of Article 247 of the same Code , as amended, is further amended to read as follows:\n\"Subject to the exercise by the President or by the Secretary of Labor and Employment of the powers vested in them by Articles 263 and 264 of this Code, the civil aspects of all cases involving unfair labor practices, which may include claims for actual, moral, exemplary and other forms of damages, attorney's fees and other affirmative relief, shall be under the jurisdiction of the Labor Arbiters. The Labor Arbiters shall give utmost priority to the hearing and resolution of all cases involving unfair labor practices. They shall resolve such cases within thirty (30) calendar days from the time they are submitted for decision.\""}},{"id":"PH-H5212-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Article 250 of the same Code is amended to read as follows:\n\"Article 250. Procedure in collective bargaining. - The following procedures shall be observed in collective bargaining:\n\"(a) When a party desires to negotiate an agreement it shall serve a written notice upon the other party with a statement of its proposals. The other party shall make a reply thereto not later than ten (10) calendar days from receipt of such notice;\n\"(b) Should differences arise on the basis of such notice and reply, either party may request for a conference which shall begin not later than ten (10) calendar days from the date of request;\n\"(c) If the dispute is not settled, the Board shall intervene upon request of either or both parties or at its own initiative and immediately call the parties to conciliation meetings. The Board shall have the power to issue subpoenas requiring the attendance of the parties to such meetings. It shall be the duty of the parties to participate fully and promptly in the conciliation meetings the Board may call;\n\"(d) During the conciliation proceedings in the Board, the parties are prohibited from doing any act which may disrupt or impede the early settlement of the disputes; and \"(e) The Board shall exert all efforts to settle disputes amicably and encourage the parties to submit their case to a voluntary arbitrator.\""}},{"id":"PH-H5212-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"There shall be incorporated after Article 253 of the same Code a new article which shall read as follows:\n\"Article 253-A. Terms of a collective bargaining agreement. - Any collective bargaining agreement that the parties may enter into shall, insofar as the representation aspect is concerned, be for a term of five (5) years. No petition questioning the majority status of the incumbent bargaining agent shall be entertained and no certification election shall be conducted by the Department of Labor and Employment outside of the sixty-day period immediately before the date of expiry of such five year term of the collective bargaining agreement. All other provisions of the collective bargaining agreement shall be renegotiated not later than three (3) years after its execution. Any agreement on such other provisions of the collective bargaining agreement entered into within six (6) months from the date of expiry of the term of such other provisions as fixed in the collective bargaining agreement, shall retroact to the day immediately following such date. If any such agreement is entered into beyond six months, the parties shall agree on the duration of retroactivity thereof. In case of a deadlock in the renegotiation of the collective bargaining agreement, the parties may exercise their rights under this Code.\""}},{"id":"PH-H5212-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Article 255 of the Labor Code , as amended, is hereby amended to read as follows:\n\"Article 255. Exclusive bargaining representation and workers' participation in policy and decision-making. - The labor organization designated or selected by the majority of the employees in an appropriate collective bargaining unit shall be the exclusive representative of the employees in such unit for the purpose of collective bargaining. However, an individual employee or group of employees shall have the right at any time to present grievances to their employer.\n\"Any provision of law to the contrary notwithstanding, workers shall have the right, subject to such rules and regulations as the Secretary of Labor and Employment may promulgate, to participate in policy and decision-making processes of the establishment where they are employed insofar as said processes will directly affect their rights, benefits and welfare. For this purpose, workers and employers may form labor-management councils: Provided, That the representatives of the workers in such labor-management councils shall be elected by at least the majority of all employees in said establishment.\""}},{"id":"PH-H5212-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Article 256 of the same Code , as amended, is further amended to read as follows:\n\"Article 256. Representation issue in organized establishments. - In organized establishments, when a verified petition questioning the majority status of the incumbent bargaining agent is filed before the Department of Labor and Employment within the sixty-day period before the expiration of a collective bargaining agreement, the Med-Arbiter shall automatically order an election by secret ballot when the verified petition is supported by the written consent of at least twenty-five percent (25%) of all the employees in the bargaining unit to ascertain the will of the employees in the appropriate bargaining unit. To have a valid election, at least a majority of all eligible voters in the unit must have cast their votes. The labor union receiving the majority of the valid votes cast shall be certified as the exclusive bargaining agent of all the workers in the unit. When an election which provides for three or more choices results in no choice receiving a majority of the valid votes cast, a run-off election shall be conducted between the labor unions receiving the two highest number of votes: Provided, That the total number of votes for all contending unions is at least fifty per cent (50%) of the number of votes cast.\nAt the expiration of the freedom period, the employer shall continue to recognize the majority status of the incumbent bargaining agent where no petition for certification election is filed.\""}},{"id":"PH-H5212-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Article 257 of the same Code is amended to read as follows:\nArticle 257. Petitions in unorganized establishment. - In any establishment where there is no certified bargaining agent, a certification election shall automatically be conducted by the Med-Arbiter upon the filing of a petition by a legitimate labor organization.\""}},{"id":"PH-H5212-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Article 259 of the same Code is also hereby amended to read as follows:\nArticle 259. Appeal from certification election orders. - Any party to an election may appeal the order or results of the election as determined by the Med-Arbiter directly to the Secretary of Labor and Employment on the ground that the rules and regulations or parts thereof established by the Secretary of Labor and Employment for the conduct of the election have been violated. Such appeal shall be decided within fifteen (15) calendar days."}},{"id":"PH-H5212-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"There shall be incorporated after Article 259 of the same Code a new chapter to read as follows:\nGrievance Machinery and Voluntary Arbitration \"Article 260. Grievance machinery and voluntary arbitration. - The parties to a collective bargaining agreement shall include therein provisions that will ensure the mutual observance of its terms and conditions. They shall establish a machinery for the adjustment and resolution of grievances arising from the interpretation or implementation of their collective bargaining agreement and those arising from the interpretation or enforcement of company personnel policies.\n\"All grievances submitted to the grievance machinery which are not settled within seven (7) calendar days from the date of its submission shall automatically be referred to voluntary arbitration prescribed in the collective bargaining agreement.\n\"For this purpose, parties to a collective bargaining agreement shall name and designate in advance a voluntary arbitrator or panel of voluntary arbitrators, or include in the agreement a procedure for the selection of such voluntary arbitrator or panel of voluntary arbitrators, preferably from the listing of qualified voluntary arbitrators duly accredited by the Board. In case the parties fail to select a voluntary arbitrator or panel of voluntary arbitrators, the Board shall designate the voluntary arbitrator or panel of voluntary arbitrators, as may be necessary, pursuant to the selection procedure agreed upon in the collective bargaining agreement, which shall act with the same force and effect as if the voluntary arbitrator or panel of voluntary arbitrators have been selected by the parties as described above.\"\n\"Article 261. Jurisdiction of voluntary arbitrator and panel of voluntary arbitrators. - The voluntary arbitrator or panel of arbitrators shall have original and exclusive jurisdiction to hear and decide all unresolved grievances arising from the interpretation or implementation of the collective bargaining agreement and those arising from the interpretation or enforcement of company personnel policies referred to in the immediately preceding Article. Accordingly, violations of a collective bargaining agreement, except those which are gross in character, shall no longer be treated as unfair labor practice and shall be resolved as grievances under the collective bargaining agreement. For purposes of this Article, gross violations of a collective bargaining agreement shall mean flagrant and/or malicious refusal to comply with the economic provisions of such agreement.\n\"The Commission, its Regional Offices and the Regional Directors of the Department of Labor and Employment shall not entertain disputes, grievances or matters under the exclusive and original jurisdiction of the voluntary arbitrator or panel of voluntary arbitrators and shall immediately dispose and refer the same to the grievance machinery or voluntary arbitration provided in the collective bargaining agreement.\"\n\"Article 262. Jurisdiction over other labor disputes. - The voluntary arbitrator or panel of voluntary arbitrators, upon agreement of the parties, shall also hear and decide all other labor disputes including unfair labor practices and bargaining deadlocks.\n\"Article 262-A. Procedures. - The voluntary arbitrator or panel of voluntary arbitrators shall have the power to hold hearings, receive evidences and take whatever action is necessary to resolve the issue or issues subject of the dispute, including efforts to effect a voluntary settlement between parties.\n\"All parties to the dispute shall be entitled to attend the arbitration proceedings. The attendance of any third party or the exclusion of any witness from the proceedings shall be determined by the voluntary arbitrator or panel of voluntary arbitrators. Hearings may be adjourned for cause or upon agreement by the parties.\n\"Unless the parties agree otherwise, it shall be mandatory for the voluntary arbitrator or panel of voluntary arbitrators to render an award or decision within twenty (20) calendar days from the date of submission of the dispute to voluntary arbitration. \"The award or decision of the voluntary arbitrator or panel of voluntary arbitrators shall contain the facts and the law on which it is based. It shall be final and executory after ten (10) calendar days from receipt of the copy of the award or decision by the parties.\n\"Upon motion of any interested party, the voluntary arbitrator or panel of voluntary arbitrators or the Labor Arbiter in the region where the movant resides, in case of the absence or incapacity of the voluntary arbitrator or panel of voluntary arbitrators for any reason, may issue a writ of execution requiring either the sheriff of the Commission or regular courts or any public official whom the parties may designate in the submission agreement to execute the final decision, order or award.\n\"Article 262-B. Cost of voluntary arbitration and voluntary arbitrator's fee. - The parties to a collective bargaining agreement shall provide therein a proportionate sharing scheme on the cost of voluntary arbitration including the voluntary arbitrator's fee. The fixing of fee of voluntary arbitrators, or panel of voluntary arbitrators, whether shouldered wholly by the parties or subsidized by the Special Voluntary Arbitration Fund, shall take into account the following factors:\n\"(a) Nature of the case;\n\"(b) Time consumed in hearing the case;\n\"(c) Professional standing of the voluntary arbitrator;\n\"(d) Capacity to pay of the parties; and \"(e) Fees provided for in the Revised Rules of Court.\""}},{"id":"PH-H5212-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Paragraphs (g) and (i) of Article 263 of the same code , as amended, are hereby further amended to read as follows:\n\"(g) When, in his opinion, there exists a labor dispute causing or likely to cause a strike or lockout in an industry, indispensable to the national interest, the Secretary of Labor and Employment may assume jurisdiction over the dispute and decide it or certify the same to the Commission for compulsory arbitration. Such assumption or certification shall have the effect of automatically enjoining the intended or impending strike or lockout as specified in the assumption or certification order. If one has already taken place at the time of assumption or certification, all striking or locked out employees shall immediately return to work and the employer shall immediately resume operations and readmit all workers under the same terms and conditions prevailing before the strike or lockout. The Secretary of Labor and Employment or the Commission may seek the assistance of law enforcement agencies to ensure compliance with this provision as well as with such orders as he may issue to enforce the same.\n\"In line with the national concern for and the highest aspect accorded to the right of patients to life and health, strikes and lockouts in hospitals, clinics and similar medical institutions shall, to every extent possible, be avoided, and all serious efforts, not only by labor and management but government as well, be exhausted to substantially minimize, if not prevent their adverse effects on such life and health, through the exercise, however legitimate, by labor of its right to strike and by management to lockout. In labor disputes adversely affecting the continued operation of such hospitals, clinics, or medical institutions, it shall be the duty of the striking union or locking-out employer to provide and maintain an effective skeletal work force of medical and other health personnel, whose movement and services shall be unhampered and unrestricted, as are necessary to ensure the proper and adequate protection of the life and health of its patients, most especially emergency cases, for the duration of the strike or lockout. In such cases, therefore, the Secretary of Labor and Employment may immediately assume, within twenty four (24) hours from knowledge of the occurrence of such a strike or lockout, jurisdiction over the same or certify it to the Commission for compulsory arbitration. For this purpose, the contending parties are strictly enjoined to comply with such orders, prohibitions and/or injunctions as are issued by the Secretary of Labor and Employment or the Commission, under pain of immediate disciplinary action, including dismissal or loss of employment status or payment by the locking-out employer of backwages, damages and other affirmative relief, even criminal prosecution against either or both of them.\n\"The foregoing notwithstanding, the President of the Philippines shall not be precluded from determining the industries that, in his opinion, are indispensable to the national interest, and from intervening at any time and assuming jurisdiction over any labor dispute in such industries in order to settle or terminate the same.\n\"(i) The Secretary of Labor and Employment, the Commission or the voluntary arbitrator or panel of voluntary arbitrators shall decide or resolve the dispute within thirty (30) calendar days from the date of the assumption of jurisdiction or the certification or submission of the dispute, as the case may be. The decision of the President, the Secretary of Labor and Employment, the Commission or the voluntary arbitrator or panel of voluntary arbitrators shall be final and executory ten (10) calendar days after receipt thereof by the parties.\""}},{"id":"PH-H5212-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"There is hereby incorporated in lieu of Article 265 of the same Code , which was repealed by Batas Pambansa Blg. 130, a new provision to read as follows:\n\"Article 265. Improved offer balloting. - In an effort to settle a strike, the Department of Labor and Management shall conduct a referendum by secret balloting on the improved offer of the employer on or before the 30th day of the strike. When at least a majority of the union members vote to accept the improved offer, the striking workers shall immediately return to work and the employer shall thereupon readmit them upon the signing of the agreement.\n\"In case of a lockout, the Department of Labor and Employment shall also conduct a referendum by secret balloting on the reduced offer of the union on or before the 30th day of the lockout. When at least a majority of the board of directors or trustees or the partners holding the controlling interest in the case of a partnership vote to accept the reduced offer, the workers shall immediately return to work and the employer shall thereupon readmit them upon the signing of the agreement.\""}},{"id":"PH-H5212-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Article 269 of the same Code is amended to read as follows:\n\"Article 269. Prohibition against aliens; Exceptions. - All aliens, natural or juridical, as well as all foreign organizations are strictly prohibited from engaging directly or indirectly in all forms of trade union activities without prejudice to normal contacts between Philippine labor unions and recognized international labor centers: Provided, however, That aliens working in the country with valid permits issued by the Department of Labor and Employment, may exercise the right to self-organization and join or assist labor organizations of their own choosing for purposes of collective bargaining: Provided, further, That said aliens are nationals of a country which grants the same or similar rights to Filipino workers.\""}},{"id":"PH-H5212-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Paragraph (a) of Article 272 of the same Code is hereby amended to read as follows:\n\"Article 272. Penalties. - (a) Any person violating any of the provisions of Article 264 of this Code shall be punished by a fine of not less than one thousand pesos (P1,000.00) nor more than ten thousand pesos (P10,000.00) and/or imprisonment for not less than three (3) months nor more than three (3) years, or both such fine and imprisonment, at the discretion of the court. Prosecution under this provision shall preclude prosecution for the same act under the Revised Penal Code, and vice-versa.\""}},{"id":"PH-H5212-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Article 274 of the same Code is amended to read as follows:\n\"Article 274. Visitorial power. - The Secretary of Labor and Employment or his duly authorized representative is hereby empowered to inquire into financial activities of legitimate labor organizations upon the filing of a complaint under oath and duly supported by the written consent of at least twenty percent (20%) of the total membership of the labor organization concerned and to examine their books of accounts and other records to determine compliance or non-compliance with the law and to prosecute any violations of the law and the union constitution and by-laws: Provided, That such inquiry or examination shall not be conducted during the sixty (60) days freedom period nor within thirty (30) days immediately preceding the date of election of union officials.\""}},{"id":"PH-H5212-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Article 275 of the same Code is hereby amended to read as follows:\n\"Article 275. Tripartism and tripartite conferences. - (a) Tripartism in labor relations is hereby declared a State policy. Towards this end, workers and employers shall, as far as practicable, be represented in decision and policy-making bodies of the government.\n\"(b) The Secretary of Labor and Employment or his duly authorized representatives may from time to time call a national, regional, or industrial tripartite conference of representatives of government, workers and employers for the consideration and adoption of voluntary codes of principles designed to promote industrial peace based on social justice or to align labor movement relations with established priorities in economic and social development. In calling such conference, the Secretary of Labor and Employment may consult with accredited representatives of workers and employers.\""}},{"id":"PH-H5212-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Paragraphs (a), (b), (c), (f), (h), and (i) of Article 277 of the same Code , as amended, is further amended to read as follows:\n\"(a) All unions are authorized to collect reasonable membership fees, union dues, assessments and fines and other contributions for labor education and research, mutual death and hospitalization benefits, welfare fund, strike fund and credit and cooperative undertakings.\n\"(b) Subject to the constitutional right of workers to security of tenure and their right to be protected against dismissal except for a just or authorized cause and without prejudice to the requirement of notice under Article 283 of this Code, the employer shall furnish the worker whose employment is sought to be terminated a written notice containing a statement of the causes for termination and shall afford the latter ample opportunity to be heard and to defend himself with the assistance of his representative if he so desires in accordance with company rules and regulations promulgated pursuant to guidelines set by the Department of Labor and Employment. Any decision taken by the employer shall be without prejudice to the right of the worker to contest the validity or legality of his dismissal by filing a complaint with the regional branch of the National Labor Relations Commission. The burden of proving that the termination was for a valid or authorized cause shall rest on the employer. The Secretary of Labor and Employment may suspend the effects of the termination pending resolution of the dispute in the event of a prima facie finding by the appropriate official of the Department of Labor and Employment before whom such dispute is pending that the termination may cause a serious labor dispute or is in implementation of a mass lay-off.\n\"(c) Any employee, whether employed for a definite period or not, shall, beginning on his first day of service, be considered an employee for purposes of membership in any labor union.\n\"(f) A Special Voluntary Arbitration Fund is hereby established in the Board to subsidize the cost of voluntary arbitration in cases involving the interpretation and implementation of the collective bargaining agreement, including the arbitrator's fees, and for such other related purposes to promote and develop voluntary arbitration. The Board shall administer the Special Voluntary Arbitration Fund in accordance with the guidelines it may adopt upon the recommendation of the Council, which guidelines shall be subject to the approval of the Secretary of Labor and Employment. Continuing funds needed for this purpose in the initial yearly amount of fifteen million pesos (P15,000,000.00) shall be provided in the 1989 and subsequent annual General Appropriations Acts.\n\"The amount of subsidy in appropriate cases shall be determined by the Board in accordance with established guidelines issued by it upon the recommendation of the Council.\n\"The fund shall also be utilized for the operation of the Council, the training and education of voluntary arbitrators, and the promotion and the development of a comprehensive voluntary arbitration program.\n\"(h) In establishments where no legitimate labor organization exists, labor-management committees may be formed voluntarily by workers and employers for the purpose of promoting industrial peace. The Department of Labor and Management shall endeavor to enlighten and educate the workers and employers on their rights and responsibilities through labor education with emphasis on the policy thrusts of this Code.\n\"(i) To ensure speedy labor justice, the periods provided in this Code within which decisions or resolutions of labor relations cases or matters should be rendered shall be mandatory. For this purpose, a case or matter shall be deemed submitted for decision or resolution upon the filing of the last pleading or memorandum required by the rules of the Commission or by the Commission itself, or the Labor Arbiter or the Director of the Bureau of Labor Relations or Med-Arbiter, or the Regional Director.\n\"Upon expiration of the corresponding period, a certification stating why a decision or resolution has not been rendered within the said period shall be issued forthwith by the Chairman of the Commission, the Executive Labor Arbiter, or the Director of the Bureau of Labor Relations or Med-Arbiter, or the Regional Director, as the case may be, and a copy thereof served upon the parties.\n\"Despite the expiration of the applicable mandatory period, the aforesaid officials shall, without prejudice to any liability which may have been incurred as a consequence thereof, see to it that the case or matter shall be decided or resolved without any further delay.\""}},{"id":"PH-H5212-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Article 279 of the Labor Code is hereby amended to read as follows:\n\"ARTICLE 279. Security of Tenure. - In cases of regular employment, the employer shall not terminate the services of an employee except for a just cause or when authorized by this Title. An Employee who is unjustly dismissed from work shall be entitled to reinstatement without loss of seniority rights and other privileges and to his full backwages, inclusive of allowances, and to his other benefits or their monetary equivalent computed from the time his compensation was withheld from him up to the time of his actual reinstatement.\""}},{"id":"PH-H5212-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Equity of the Incumbent. - Incumbent career officials and rank-and-file employees of the National Labor Relations Commission not otherwise affected by this Act shall continue to hold office without need of reappointment. However, consistent with the need to professionalize the higher level of its officialdom invested with adjudicatory powers and salaries or emoluments, all positions of the Commissioners, Executive Labor Arbiters and Labor Arbiters of the present National Labor Relations Commissions are hereby declared vacant. However, subject officials shall continue to temporarily discharge their duties and functions until their successors shall have been duly appointed and qualified."}},{"id":"PH-H5212-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Rule-Making Authority. - The Secretary of Labor and Employment is hereby authorized to promulgate such rules and regulations as may be necessary to implement the provisions of this Act."}},{"id":"PH-H5212-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Funding. - Funds needed to carry out the provisions of this Act shall be taken from the available funds in the Department of Labor and Employment and shall thereafter be included in subsequent annual General Appropriations Acts."}},{"id":"PH-H5212-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Repealing Cause. - All laws, decrees, executive orders, letters of implementations, rules and regulations or part or parts thereof inconsistent with any provision of this Act are hereby repealed, modified, superseded or amended accordingly."}},{"id":"PH-H5212-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Separability Clause. - If any provision of this Act or the application of such provision to any person or circumstance is held invalid for any reason, the remainder of this Act or the application of such provision to other persons or circumstances shall not be affected thereby."}},{"id":"PH-H5212-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"TITLE VIII -A"},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier."}}],"pack":"ph-p74"};
  FT["PH-H5213"] = {"id":"PH-H5213","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6716_1989.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Construction of Water Wells, Rainwater Collectors, Development of Springs and Rehabilitation of Existing Water Wells in All Barangays in the Philippines","orig":"An Act Providing for the Construction of Water Wells, Rainwater Collectors, Development of Springs and Rehabilitation of Existing Water Wells in All Barangays in the Philippines"},"level":"law","status":"active","topics":["company","administrative"],"docNumber":"Republic Act No. 6716","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-17","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6716_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5213-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy . — It is hereby declared to be the national policy to promote the quality of lift of every Filipino through the provision of adequate social services including, but not limited to, the provision of adequate potable water supply made conveniently available to every barangay in the country."}},{"id":"PH-H5213-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Water Wells, Rainwater Collectors and Spring Development . — The Department of Public Works and Highways (DPWH) shall, within thirty (30) days after the approval of this Act, undertake construction of water wells, rainwater collectors, development of springs and rehabilitation of existing water wells in oil barangays in the Philippines in such number as may be needed and feasible, taking into consideration the population, hydrologic conditions, costs of project development and operations, financial and economic factors and institutional arrangements: Provided, however, That the DPWH shall deduct not more than five percent (5%) for supervision, engineering, technical and other overhead expanses or fees: Provided, further, That each barangay in the country shall have at least one additional potable water source."}},{"id":"PH-H5213-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Operation and Maintenance . — In order to ensure the proper use of the water facilities herein provided, a Barangay Waterworks and Sanitation Association, herein referred to as BWSA, shall be formed and organized for the purpose of maintaining the water facilities: Provided, That pending the organization of the BWSA, the water facilities shall be operated and maintained by the barangay council.\nThe BWSA shall be composed of the member consumers who shall administer, operate and maintain the completed water facility and shall be registered with the corresponding municipal or city council.\nThe BWSA may impost such minimal charges as may be necessary for the maintenance and normal repairs of said facility. Nothing herein shall prevent any resident of the locality from using the water facility under the same terms and conditions as the member-consumers of the BWSA.\nOrganizing and training the recipient communities in the operation and maintenance of water systems shall be conducted by the DPWH prior to the turnover of such facilities to the BWSA subject to the guidelines to be formulated by the Department."}},{"id":"PH-H5213-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Submission of Report . — The Department of Public Works and Highways shall, within ninety (90) day after the approval of this Act and every one hundred eighty (180) days thereafter, submit periodic reports to the respective Committees on Public Works and Highways of both Houses of the Congress of the Philippines for evaluation and consideration."}},{"id":"PH-H5213-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Funding . — The sum needed for the implementation of the construction, rehabilitation and repair program shall be taken from any available appropriations for the Department of Public Works and Highways in the General Appropriations Act for 1989: Provided, That funds for this purpose shall also be included in the General Appropriations Act for 1990 and 1991: Provided, further, That the total program shall be completed not later than June 30, 1991, and: Provided, finally, That there shall be equitable and proportionate appropriations of funds annually for this purpose for all provinces, cities and municipalities. In addition, a portion of financial grants and concessional loans extended to the Philippines by foreign governments and multilateral agencies every year, the amount to be determined by the President, shall be allocated by the Department of Budget and Management to augment the appropriations of the Department of Public. Works and Highway until one hundred thousand (100,000) water wells, rainwater collectors, and permits are completed as envisioned in this Act."}},{"id":"PH-H5213-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity . — This Act shall take effect upon publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5214"] = {"id":"PH-H5214","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6717_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Maytubig Elementary School in the Municipality of Isabela, Province of Negros Occidental, to Francisco Esteban Sr. Memorial Elementary School","orig":"An Act Changing the Name of the Maytubig Elementary School in the Municipality of Isabela, Province of Negros Occidental, to Francisco Esteban Sr. Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6717","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6717_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5214-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Maytubig Elementary School in the Municipality of Isabela, Province of Negros Occidental, is hereby changed to Francisco Esteban Sr. Memorial Elementary School."}},{"id":"PH-H5214-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5215"] = {"id":"PH-H5215","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6718_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Tigato Elementary School in Buhangin District, Davao City, to Pilar Rodriguez Elementary School","orig":"An Act Changing the Name of the Tigato Elementary School in Buhangin District, Davao City, to Pilar Rodriguez Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6718","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6718_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5215-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tigato Elementary School in Buhangin District, Davao City, shall now be known as the Pilar Rodriguez Elementary School in honor of its donor, the late Pilar P. Rodriguez."}},{"id":"PH-H5215-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5216"] = {"id":"PH-H5216","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6719_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the San Andres Elementary School in Barangay San Andres, Municipality of Malvar, Province of Batangas, to Miguel Aranda Memorial Elementary School","orig":"An Act Changing the Name of the San Andres Elementary School in Barangay San Andres, Municipality of Malvar, Province of Batangas, to Miguel Aranda Memorial Elementary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 6719","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6719_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5216-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of San Andres Elementary School in Barangay San Andres, Municipality of Malvar, Province of Batangas, is hereby changed to Miguel Aranda Memorial Elementary School."}},{"id":"PH-H5216-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5217"] = {"id":"PH-H5217","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6720_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring September 28 of Every Year a Special Non-Working Holiday in the Province of Camarines Norte to Commemorate the Birth Anniversary of Wenceslao Q. Vinzons, Sr., Patriot and Martyr","orig":"An Act Declaring September 28 of Every Year a Special Non-Working Holiday in the Province of Camarines Norte to Commemorate the Birth Anniversary of Wenceslao Q. Vinzons, Sr., Patriot and Martyr"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6720","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6720_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5217-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to celebrate the birth anniversary of Wenceslao Q. Vinzons, Sr., September 28 of each year is hereby declared a special non-working holiday in the Province of Camarines Norte."}},{"id":"PH-H5217-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5218"] = {"id":"PH-H5218","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6721_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring November Thirteen of Each Year a Special Public Holiday in the Province of Pangasinan","orig":"An Act Declaring November Thirteen of Each Year a Special Public Holiday in the Province of Pangasinan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6721","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6721_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5218-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to commemorate the birth anniversary of the late Speaker Eugenio Perez, November Thirteen of each year is hereby declared a special non-working holiday in the Province of Pangasinan."}},{"id":"PH-H5218-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5219"] = {"id":"PH-H5219","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6722_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring April Twenty-Five a Special Non-Working Holiday in the Province of Aklan","orig":"An Act Declaring April Twenty-Five a Special Non-Working Holiday in the Province of Aklan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6722","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6722_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5219-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"April Twenty-five of every year is hereby declared a special non-working holiday in the Province of Aklan to commemorate the creation of said province."}},{"id":"PH-H5219-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5220"] = {"id":"PH-H5220","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6723_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring February One of Every Year a Special Working Holiday in the Province of Camarines Norte to Commemorate the Birth Anniversary of its Hero, Dr. Jose Maria Panganiban","orig":"An Act Declaring February One of Every Year a Special Working Holiday in the Province of Camarines Norte to Commemorate the Birth Anniversary of its Hero, Dr. Jose Maria Panganiban"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6723","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-03-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6723_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5220-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared that February One of every year is a special working holiday in the Province of Camarines Norte to commemorate the birth anniversary of its hero, Dr. Jose Maria Panganiban."}},{"id":"PH-H5220-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5221"] = {"id":"PH-H5221","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6724_1989.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Organizing a Joint Legislative-Executive Foreign Debt Council, Defining Its Objectives, Powers and Functions, Appropriating Funds Therefor, and for other purposes","orig":"An Act Organizing a Joint Legislative-Executive Foreign Debt Council, Defining Its Objectives, Powers and Functions, Appropriating Funds Therefor, and for other purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6724","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-04-17","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6724_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5221-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Principles. - The task of solving the problem of foreign debt shall be guided by the following basic principles:\n(1) The foreign debt service burden should be subordinate to the national development goals of alleviation of poverty, generation of more and productive employment, enhancement of social justice and equity, and promotion of sustainable economic growth. Growth, equity and social justice should have prior claims over and above foreign debt service;\n(2) The Government shall take firm, innovative, responsible and pragmatic initiatives in dealing with the external debt problem;\n(3) Foreign loan and debt restructuring agreements should not impair our country's sovereignty; and\n(4) The people should be adequately informed and consulted, and their support mobilized at all levels of the policy formulation process through dialogues, public hearings and media."}},{"id":"PH-H5221-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Organization of Joint Legislative-Executive Foreign Debt Council. - Within thirty (30) days after the effectivity of this Act, there shall be organized an advisory body to be known as the Joint Legislative-Executive Foreign Debt Council, hereinafter called Council."}},{"id":"PH-H5221-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Purposes and Objectives. - The Council shall have the following purposes and objectives:\n(a) To recommend an independent and assertive policy on the country's external debt, foreign debt management and foreign debt service, which upholds the country's sovereignty and which promotes a sustained economic growth and a self-reliant economy;\n(b) To undertake in-depth and detailed studies on all the policy options indicated herein and other options which the Council deems feasible or realistic;\n(c) To enhance and facilitate cooperation and coordination between the legislative and executive branches of government in formulating and implementing the Government's foreign debt management policy and strategy;\n(d) To undertake a comprehensive study of the foreign debt burden particularly the external debt and other borrowings of the public and private sectors including all policies related thereto;\n(e) To recommend measures that will ensure continuous and effective monitoring of the external debt of both the public and private sectors including the debt incurred by the Central Bank;\n(f) To study and evaluate the impact of the foreign debt and external debt policies on the national development goals, the economic programs, and the lives of the people;\n(g) To recommend measures for the effective collection of accounts from actual debtors whose obligations are assumed by the Government or any of its instrumentalities;\n(h) To facilitate nationwide consultations and public hearings on the foreign debt;\n(i) To conduct continuing studies and researches on policy options, strategies, and approaches to the foreign debt problem including the experiences of other debtor countries and to recommend such remedial and legislative measures as may be required."}},{"id":"PH-H5221-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Policy Options. - In the discharge of its responsibilities, the Council may consider and develop the following options:\n(1) Debt-to-Equity Program. - To expand the volume and coverage of the Central Bank Debt-to-Equity Swap Program by converting $5 billion, more or less, in the Philippine foreign debt instruments into equity investments in Philippine agriculture and industry under a 5-year program of $1 billion, more or less, per year with emphasis on new foreign exchange-earning and labor-intensive productive projects in various parts of the country, including factories operating below rated capacity or which have been closed down for lack of capital, under terms that will not unduly trigger inflation;\n(2) Debt-for-Bonds Swap. - To retire $1.5 billion to $2 billion, more or less, of foreign debt by Philippine issuance of $1 billion, more or less, of Philippine dollar bonds collateralized by 20-year Zero Coupon U.S. Treasury Bonds or other suitable U.S. Government Bonds. The amount of $1 billion in Zero Coupon U.S. Treasury Bonds with twenty (20) years maturity can be purchased by using $200 million, more or less, from Philippine international reserves or anticipated inflows from foreign aid;\n(3) Partial Use of U.S. Facilities Compensation. - To utilize a portion of the possible U.S. Facilities Compensation Package to acquire more U.S. Treasury Bonds or accept part-payment for the U.S. Facilities in U.S. Treasury Bonds for further exchange with Philippine debt instruments as indicated in Item (2) above;\n(4) Japanese Bonds and other Foreign Currency Denominated Bonds. - To utilize a portion of Japanese and other foreign economic development assistance funds to acquire Japanese and other foreign currency denominated bonds to collateralize issuance of Philippine currency denominated bonds similar to the U.S. Bonds formula, as explained in Items (2) and (3) above;\n(5) Use of Official Aid. - To use a portion of official aid from other sources to fund Philippine purchases of U.S. Treasury Bonds or Japanese Bonds to further enlarge the Debt-for-Bonds Swap Program;\n(6) Co-Guarantors. - To request the World Bank or other official multilateral financial institution to co-guarantee the coupon rate or interest rate of Philippine dollar bonds in support of the Debt-for-Bonds Swap Program. Foreign buyers are then assured of payments not only on the principal but also on the interest;\n(7) Interest Cap. - To reduce interest rate payments to four percent (4%) to five percent (5%) of principal, more or less, per year on the loans granted by the foreign commercial banks to the Philippines;\n(8) Capitalization of Interest Balance. - Under the Interest Rate Reduction Scheme in Item (7), the unpaid interest portion in this proposal, shall be added to the principal amount to be repaid when the loan matures. Further, the Philippines may issue to international creditors a new dollar-denominated instrument corresponding to the unpaid interest balance with incentive features;\n(9) Interest Waivers. - In lieu of or complementary to Items (7) and (8), to negotiate with the foreign commercial banks for interest waivers of two percent (2%) to four percent (4%), which the World Bank is considering to endorse;\n(10) Condonation of a Portion of Commercial Loan. - To request the foreign commercial banks to condone at least fifteen percent (15%) of their loans to the Philippines since some of these institutions have already announced loan-loss provisions of twenty percent (20%) to thirty-five percent (35%);\n(11) Restructuring Terms of the Paris Club Debt. - To lengthen the payment period of the Paris Club debt from ten (10) years to twenty (20) years, considering that the foreign commercial banks have already agreed to restructure their loans to the Philippines to seventeen (17) years;\n(12) Converting a Portion of the Paris Club Debt to Grants. - To convert a portion of the Paris Club debt to grants, considering as an example that a significant segment of the Philippine official debt to Japan was caused by Japanese yen revaluation;\n(13) Conversion of Foreign Military Sales to Grants. - To convert Foreign Military Sales (FMS) credits to the Philippines under bilateral agreements, principally with the United States, into grants;\n(14) Debt-for-Nature Swap Program. - To convert limited amounts of Philippine foreign debt into grants for nature, environment and wildlife conservation projects in the Philippines to be undertaken by international conservation groups;\n(15) International Institute of Debt and Development. - To support the establishment of an International Institute of Debt and Development or any international finance organization that will acquire the debt instruments of the Philippines and other Third World countries at substantial discount, which benefits shall be shared by the debtor countries;\n(16) Selective Debt Repudiation. - To consider the option of selective debt repudiation on foreign loans attended by fraud, bribery, and corruption between foreign lenders and Philippine borrowers;\n(17) Moratorium. - To consider the option declaring a moratorium for a temporary and limited period of payment of principal and interest; Provided, That foreign exchange savings shall be utilized exclusively for productive, labor-intensive and dollar-earning export industries. Fifty percent (50%) of export earnings created by this forced savings shall be escrowed in interest-earning deposits to be earmarked for foreign debt service upon expiry of the moratorium thus increasing further the nation's debt service capability and helping project an image of a good debtor. Such options shall include selective moratorium on debts or obligations which are under litigation;\n(18) Merchandise Export Receipts. - To negotiate that the debt service per annum shall not exceed fifteen percent (15%) of merchandise export receipts of the previous year;\n(19) Repeal of Automatic Appropriations. - Repeal of automatic appropriations for foreign debt service except for new loans or other credit accommodations;\n(20) Debt-for-Commodities Program. - For the Philippines to consider paying part of its foreign debt with Philippine products at levels from $250 million to $500 million, more or less, per year;\n(21) Mixed Credits. - Negotiate for \"mixed credits\" that will include a long-term cash portion, long-term export credits, low interest and grants equivalent to five percent (5%), more or less, of project cost. Maturity should be between twenty-five (25) to thirty (30) years. New money facilities should only be used for purposes of economic growth and development, unless otherwise specified;\n(22) Petroleum Credits. - Negotiate a program of petroleum credits with petroleum-exporting states with twenty-five (25) to thirty (30) years maturity, more or less, linked to the United States bases support for oil tanker traffic in the Persian Gulf. The proceeds of this petroleum credits shall be exclusively used for southern Philippines, including the establishment of an oil refinery there. In addition, the Philippines should also target $100 million per year of oil-exporting states' investment in the Philippines including their support for the proposed Philippine Islamic Bank.\nUndertake bilateral agreements for skilled Philippine manpower programs with friendly oil-exporting states to generate labor-related foreign exchange earnings of US$ 1 billion to US$ 1.5 billion, more or less, per year;\n(23) Investments Policy and the Philippine Assistance Program. - Without prejudicing Filipino entrepreneurs in certain industrial sectors, establish a liberal foreign investments program aimed at attracting to the Philippines the four (4) newly industrializing economies of South Korea, Taiwan, Singapore and Hongkong.\nFurther, support simultaneously multilateral programs of the United States, Japan, Canada, Australia, European Economic Community (EEC), Association of Southeast Asian Nations (ASEAN) and other countries for Philippine economic reconstruction under the proposed Philippine Assistance Program (PAP) involving a mixture of equity investments, debt-to-equity conversions, long-term loans, aid, and grants;\n(24) Countertrade. - Organize a countertrade program of up to US$1 billion a year, more or less, with the Union of Soviet Socialist Republics, People's Republic of China, the Socialist States of Eastern Europe, and any other country with centrally-planned economies to balance and diversify Philippine foreign trade and move non-traditional products with a view to ensuring incremental exports and reducing the Philippine need for trade credits;\n(25) International Debt Conferences. - Actively join and participate in Latin America, African, Socialist and other international conferences dealing with foreign debt;\n(26) Diplomatic and Information Campaign. - Launch a diplomatic and information campaign outlining the Government's economic program for the international and financial community to illustrate Philippine will to face up to its debt problems;\n(27) Other Options. - The foregoing shall not preclude the formulation and consideration of other options and principles in dealing with the Philippine external debt, consistent with the national interest."}},{"id":"PH-H5221-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Powers and Functions. - To carry out the aforementioned purposes and objectives, the Council is authorized:\n(1) To submit to the President of the Philippines its recommendees for members of the Government panel in the negotiations and/or renegotiations of the Philippine external debt; Provided, That it shall recommend at least five (5) members with expertise in each of the following: (a) diplomacy, (b) economics, (c) investment banking, (d) law, and (e) accountancy;\n(2) To secure from any department, bureau, office, agency, or instrumentality of the Government such assistance as may be needed, such as technical information, the preparation and production of reports, and the submission of recommendations or plans, as it may require;\n(3) Generally, to exercise all the powers necessary to attain the purposes and objectives for which it is organized."}},{"id":"PH-H5221-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Composition, Appointment, and Designation. - The Council shall be composed of seventeen (17) members as follows:\n(1) Nine (9) members to be appointed by the President of the Philippines. Any or all of these nine (9) members may or may not be officials of the Government and they may include professionals from the academe and the private sector;\n(2) Four (4) Senators to be designated by the Senate President in consultation with the Majority Floor Leader and the Minority Floor Leader of the Senate; and\n(3) Four (4) Congressmen to be designated by the Speaker of the House of Representatives in consultation with the Majority Floor Leader and the Minority Floor Leader of the House.\nThe President shall appoint the Chairman and Vice-Chairman of the Council from among its members."}},{"id":"PH-H5221-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Geographical Representation, Quorum. - The geographic representation from Mindanao, Visayas and Luzon shall be observed in the composition of the Council. A majority of all the members of the Council shall constitute a quorum for the conduct of business."}},{"id":"PH-H5221-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Compensation. - Members of the Council who are government officials shall not receive additional compensation for the service rendered thereto. Members of the Council who are not government officials shall receive per diems of One thousand pesos (P1,000) for every Council meeting: Provided, That the per diems collected per month do not exceed the equivalent of four (4) meetings."}},{"id":"PH-H5221-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Staff Support. - The Presidential Management Staff shall provide staff support to the Council. The Council may call on any department, bureau, office and instrumentality of the Government for appropriate assistance."}},{"id":"PH-H5221-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Submission of Reports. - The Council shall submit to the President of the Philippines, the Senate President, and the Speaker of the House of Representatives a quarterly report of its activities, assessments of, and recommendations on the country's debt situation within thirty (30) working days from the end of each quarter during the year."}},{"id":"PH-H5221-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Funds. - Funds necessary for the implementation of the provisions of this Act are hereby authorized to be taken from the Contingent Fund or any appropriate lump sum appropriations under the General Appropriations Act of 1989. Funding for the succeeding years is hereby authorized to be incorporated in the annual General Appropriations Act."}},{"id":"PH-H5221-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Specific Policy. - Nothing herein shall preclude Congress from adopting a specific foreign debt policy."}},{"id":"PH-H5221-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. - In the event that any part of this Act is declared unconstitutional, the other parts not so declared shall remain valid and effective."}},{"id":"PH-H5221-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause. - Any provisions of law, decree, executive order, rule or regulation as are in conflict or inconsistent with the provisions and/or purposes of this Act are accordingly repealed, amended or modified."}},{"id":"PH-H5221-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5222"] = {"id":"PH-H5222","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6725_1989.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Strengthening the Prohibition on Discrimination against Women With Respect to Terms and Conditions of Employment, Amending for the Purpose Article One Hundred Thirty-Five of the Labor Code, as amended","orig":"An Act Strengthening the Prohibition on Discrimination against Women With Respect to Terms and Conditions of Employment, Amending for the Purpose Article One Hundred Thirty-Five of the Labor Code, as amended"},"level":"law","status":"active","topics":["labor","civil"],"docNumber":"Republic Act No. 6725","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-05-12","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6725_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5222-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article One hundred thirty-five of the Labor Code, as amended, is hereby further amended to read as follows:\n\"Art. 135. Discrimination Prohibited. — It shall be unlawful for any employer to discriminate against any woman employee with respect to terms and conditions of employment solely on account of her sex.\n\"The following are acts of discrimination:\n\"(a) Payment of a lesser compensation, including wage, salary or other form of remuneration and fringe benefits, to a female employee as against a male employee, for work of equal value; and \"(b) Favoring a male employee over a female employee with respect to promotion, training opportunities, study and scholarship grants solely on account of their sexes.\n\"Criminal liability for the willful commission of any unlawful act as provided in this article or any violation of the rules and regulations issued pursuant to Section 2 hereof shall be penalized as provided in Articles 288 and 289 of this Code: Provided, That the institution of any criminal action under this provision shall not bar the aggrieved employee from filing an entirely separate and distinct action for money claims, which may include claims for damages and other affirmative reliefs. The actions hereby authorized shall proceed independently of each other.\""}},{"id":"PH-H5222-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Labor and Employment is hereby authorized to promulgate the necessary guidelines to implement this Article in accordance with the generally accepted practices and standards here and abroad."}},{"id":"PH-H5222-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5223"] = {"id":"PH-H5223","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6726_1989.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Allowing Qualified Voters of the City of Oroquieta to Vote in Provincial Elections of the Province of Misamis Occidental, amending for the purpose Republic Act Numbered Fifty-Five Hundred and Eighteen","orig":"An Act Allowing Qualified Voters of the City of Oroquieta to Vote in Provincial Elections of the Province of Misamis Occidental, amending for the purpose Republic Act Numbered Fifty-Five Hundred and Eighteen"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6726","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-05-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6726_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5223-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section One hundred five of Republic Act Numbered Fifty-five hundred and eighteen, entitled \" An Act Creating the City of Oroquieta ,\" is hereby amended to read as follows:\n\"Sec. 105. Participation in election of provincial officials. - The voters of the City of Oroquieta shall be qualified and entitled to vote in the election of provincial governor, provincial vice-governor, and members of the provincial board of the Province of Misamis Occidental, and any of such qualified voters can be a candidate for any provincial office.\""}},{"id":"PH-H5223-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All existing laws or parts thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5223-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5224"] = {"id":"PH-H5224","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6727_1989.html","fetchedAt":"2026-10-06","articleCount":59,"structureMode":"ARTICLE","title":{"zh":null,"en":"Wage Rationalization Act","orig":"Wage Rationalization Act An Act to Rationalize Wage Policy Determination by Establishing the Mechanism and Proper Standards Therefor, Amending for the Purpose Article 99 of, and Incorporating Articles 120, 121, 122, 123, 124, 126 and 127 Into, Presidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines, Fixing New Wage Rates, Providing Wage Incentives for Industrial Dispersal to the Countryside, and for other purposes"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 6727","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-06-09","completenessNote":"全文，共 59 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6727_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1、2、3、4、5、6、7、8 条 等 15 处）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5224-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"This Act shall be known as the \" Wage Rationalization Act .\""}},{"id":"PH-H5224-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"It is hereby declared the policy of the State to rationalize the fixing of minimum wages and to promote productivity-improvement and gain-sharing measures to ensure a decent standard of living for the workers and their families; to guarantee the rights of labor to its just share in the fruits of production; to enhance employment generation in the countryside through industry dispersal; and to allow business and industry reasonable returns on investment, expansion and growth.\nThe State shall promote collective bargaining as the primary mode of settling wages and other terms and conditions of employment; and whenever necessary, the minimum wage rates shall be adjusted in a fair and equitable manner, considering existing regional disparities in the cost of living and other socio-economic factors and the national economic and social development plans."}},{"id":"PH-H5224-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"In line with the declared policy under this Act, Article 99 of Presidential Decree No. 442, as amended, is hereby amended and Articles 120, 121, 122, 123, 124, 126 and 127 are hereby incorporated into Presidential Decree No. 442, as amended, to read as follows:\n\"Art. 99. Regional Minimum Wages. — The minimum wage rates for agricultural and non-agricultural employees and workers in each and every region of the country shall be those prescribed by the Regional Tripartite Wages and Productivity Boards.\"\n\"Art. 120. Creation of the National Wages and Productivity Commission. — There is hereby created a National Wages and Productivity Commission, hereinafter referred to as the Commission, which shall be attached to the Department of Labor and Employment (DOLE) for policy and program coordination.\"\n\"Art. 121. Powers and Functions of the Commission. — The Commission shall have the following powers and functions:\n\"(a) To act as the national consultative and advisory body to the President of the Philippines and Congress on matters relating to wages, incomes and productivity;\n\"(b) To formulate policies and guidelines on wages, incomes and productivity improvement at the enterprise, industry and national levels;\n\"(c) To prescribe rules and guidelines for the determination of appropriate minimum wage and productivity measures at the regional, provincial or industry levels;\n\"(d) To review regional wage levels set by the Regional Tripartite Wages and Productivity Boards to determine if these are in accordance with prescribed guidelines and national development plans;\n\"(e) To undertake studies, researches and surveys necessary for the attainment of its functions and objectives, and to collect and compile data and periodically disseminate information on wages and productivity and other related information, including, but not limited to, employment, cost-of-living, labor costs, investments and returns;\n\"(f) To review plans and programs of the Regional Tripartite Wages and Productivity Boards to determine whether these are consistent with national development plans;\n\"(g) To exercise technical and administrative supervision over the Regional Tripartite Wages and Productivity Boards;\n\"(h) To call, from time to time, a national tripartite conference of representatives of government, workers and employers for the consideration of measures to promote wage rationalization and productivity; and \"(i) To exercise such powers and functions as may be necessary to implement this Act.\n\"The Commission shall be composed of the Secretary of Labor and Employment as ex-officio chairman, the Director-General of the National Economic and Development Authority (NEDA) as ex-officio vice-chairman, and two (2) members each from workers and employers sectors who shall be appointed by the President of the Philippines upon recommendation of the Secretary of Labor and Employment to be made on the basis of the list of nominees submitted by the workers and employers sectors, respectively, and who shall serve for a term of five (5) years. The Executive Director of the Commission shall also be a member of the Commission.\n\"The Commission shall be assisted by a Secretariat to be headed by an Executive Director and two (2) Deputy Directors, who shall be appointed by the President of the Philippines, upon the recommendation of the Secretary of Labor and Employment.\n\"The Executive Director shall have the same rank, salary, benefits and other emoluments as that of a Department Assistant Secretary, while the Deputy Directors shall have the same rank, salary, benefits and other emoluments as that of a Bureau Director. The members of the Commission representing labor and management shall have the same rank, emoluments, allowances and other benefits as those prescribed by law for labor and management representatives in the Employees' Compensation Commission.\n\"Art. 122. Creation of Regional Tripartite Wages and Productivity Boards. — There is hereby created Regional Tripartite Wages and Productivity Boards, hereinafter referred to as Regional Boards, in all regions, including autonomous regions as may be established by law. The Commission shall determine the offices/headquarters of the respective Regional Boards.\n\"The Regional Boards shall have the following powers and functions in their respective territorial jurisdiction:\n\"(a) To develop plans, programs and projects relative to wages, incomes and productivity improvement for their respective regions;\n\"(b) To determine and fix minimum wage rates applicable in their region, provinces or industries therein and to issue the corresponding wage orders, subject to guidelines issued by the Commission;\n\"(c) To undertake studies, researches and surveys necessary for the attainment of their functions, objectives and programs, and to collect and compile data on wages, incomes, productivity and other related information and periodically disseminate the same;\n\"(d) To coordinate with the other Regional Boards as may be necessary to attain the policy and intention of this Code;\n\"(e) To receive, process and act on applications for exemption from prescribed wage rates as may be provided by law or any Wage Order; and \"(f) To exercise such other powers and functions as may be necessary to carry out their mandate under this Code.\nImplementation of the plans, programs and projects of the Regional Boards referred to in the second paragraph, letter (a) of this Article, shall be through the respective regional offices of the Department of Labor and Employment within their territorial jurisdiction; Provided, however, That the Regional Boards shall have technical supervision over the regional office of the Department of Labor and Employment with respect to the implementation of said plans, programs and projects.\n\"Each Regional Board shall be composed of the Regional Director of the Department of Labor and Employment as chairman, the Regional Directors of the National Economic and Development Authority and the Department of Trade and Industry as vice-chairmen and two (2) members each from workers and employers sectors who shall be appointed by the President of the Philippines, upon the recommendation of the Secretary of Labor and Employment, to be made on the basis of the list of nominees submitted by the workers and employers sectors, respectively, and who shall serve for a term of five (5) years.\n\"Each Regional Board to be headed by its chairman shall be assisted by a Secretariat.\n\"Art. 123. Wage Order. — Whenever conditions in the region so warrant, the Regional Board shall investigate and study all pertinent facts; and based on the standards and criteria herein prescribed, shall proceed to determine whether a Wage Order should be issued. Any such Wage Order shall take effect after fifteen (15) days from its complete publication in at least one (1) newspaper of general circulation in the region.\n\"In the performance of its wage determining functions, the Regional Board shall conduct public hearings/consultations, giving notices to employees' and employers' groups, provincial, city and municipal officials and other interested parties.\n\"Any party aggrieved by the Wage Order issued by the Regional Board may appeal such order to the Commission within ten (10) calendar days from the publication of such order. It shall be mandatory for the Commission to decide such appeal within sixty (60) calendar days from the filing thereof.\n\"The filing of the appeal does not stay the order unless the person appealing such order shall file with the Commission an undertaking with a surety or sureties satisfactory to the Commission for the payment to the employees affected by the order of the corresponding increase, in the event such order is affirmed.\"\n\"Art. 124. Standards/Criteria for Minimum Wage Fixing. — The regional minimum wages to be established by the Regional Board shall be as nearly adequate as is economically feasible to maintain the minimum standards of living necessary for the health, efficiency and general well-being of the employees within the framework of the national economic and social development program. In the determination of such regional minimum wages, the Regional Board shall, among other relevant factors, consider the following:\n\"(a) The demand for living wages;\n\"(b) Wage adjustment vis-a-vis the consumer price index;\n\"(c) The cost of living and changes or increases therein;\n\"(d) The needs of workers and their families;\n\"(e) The need to induce industries to invest in the countryside;\n\"(f) Improvements in standards of living;\n\"(g) The prevailing wage levels;\n\"(h) Fair return of the capital invested and capacity to pay of employers;\n\"(i) Effects on employment generation and family income; and \"(j) The equitable distribution of income and wealth along the imperatives of economic and social development.\n\"The wages prescribed in accordance with the provisions of this Title shall be the standard prevailing minimum wages in every region. These wages shall include wages varying within industries, provinces or localities if in the judgment of the Regional Board conditions make such local differentiation proper and necessary to effectuate the purpose of this Title.\n\"Any person, company, corporation, partnership or any other entity engaged in business shall file and register annually with the appropriate Regional Board, Commission and the National Statistics Office an itemized listing of their labor component, specifying the names of their workers and employees below the managerial level, including learners, apprentices and disabled/handicapped workers who were hired under the terms prescribed in the employment contracts, and their corresponding salaries and wages.\n\"Where the application of any prescribed wage increase by virtue of law or Wage order issued by any Regional Board results in distortions of the wage structure within an establishment, the employer and the union shall negotiate to correct the distortions. Any dispute arising from wage distortions shall be resolved through the grievance procedure under their collective bargaining agreement and, if it remains unresolved, through voluntary arbitration. Unless otherwise agreed by the parties in writing, such dispute shall be decided by the voluntary arbitrator or panel of voluntary arbitrators within ten (10) calendar days from the time said dispute was referred to voluntary arbitration.\n\"In cases where there are no collective agreements or recognized labor unions, the employers and workers shall endeavor to correct such distortions. Any dispute arising therefrom shall be settled through the National Conciliation and Mediation Board and, if it remains unresolved after ten (10) calendar days of conciliation, shall be referred to the appropriate branch of the National Labor Relations Commission (NLRC). It shall be mandatory for the NLRC to conduct continuous hearings and decide the dispute within twenty (20) calendar days from the time said dispute is submitted for compulsory arbitration.\n\"The pendency of a dispute arising from a wage distortion shall not in any way delay the applicability of any increase in prescribed wage rates pursuant to the provisions of law or Wage Order.\n\"As used herein, a wage distortion shall mean a situation where an increase in prescribed wage rates results in the elimination or severe contraction of intentional quantitative differences in wage or salary rates between and among employee groups in an establishment as to effectively obliterate the distinctions embodied in such wage structure based on skills, length of service, or other logical bases of differentiation.\n\"All workers paid by result, including those who are paid on piecework, takay, pakyaw or task basis, shall receive not less than the prescribed wage rates per eight (8) hours work a day, or a proportion thereof for working less than eight (8) hours.\n\"All recognized learnership and apprenticeship agreements shall be considered automatically modified insofar as their wage clauses are concerned to reflect the prescribed wage rates.\"\n\"Art. 126. Prohibition Against Injunction. — No preliminary or permanent injunction or temporary restraining order may be issued by any court, tribunal or other entity against any proceedings before the Commission or the Regional Boards.\"\n\"Art. 127. Non-diminution of Benefits. — No Wage Order issued by any Regional Board shall provide for wage rates lower than the statutory minimum wage rates prescribed by Congress.\""}},{"id":"PH-H5224-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"(a) Upon the effectivity of this Act, the statutory minimum wage rates of all workers and employees in the private sector, whether agricultural or non-agricultural, shall be increased by twenty-five pesos (P25.00) per day, except that workers and employees in plantation agricultural enterprises outside of the National Capital Region (NCR) with an annual gross sales of less than five million pesos (P5,000,000.00) in the preceding year shall be paid an increase of twenty pesos (P20.00), and except further that workers and employees of cottage/handicraft industries, non-plantation agricultural enterprises, retail/service establishments regularly employing not more than ten (10) workers, and business enterprises with a capitalization of not more than five hundred thousand pesos (P500,000.00) and employing not more than twenty (20) employees, which are located or operating outside the NCR, shall be paid only an increase of fifteen pesos (P15.00): Provided, That those already receiving above the minimum wage rates up to one hundred pesos (P100.00) shall also receive an increase of twenty-five pesos (P25.00) per day, except that the workers and employees mentioned in the first exception clause of this Section shall also be paid only an increase of twenty pesos (P20.00), and except further that those employees enumerated in the second exception clause of this Section shall also be paid an increase of fifteen pesos (P15.00): Provided, further, That the appropriate Regional Board is hereby authorized to grant additional increases to the workers and employees mentioned in the exception clauses of this Section if, on the basis of its determination pursuant to Article 124 of the Labor Code such increases are necessary.\n(b) The increase of twenty-five pesos (P25.00) prescribed under this Section shall apply to all workers and employees entitled to the same in private educational institutions as soon as they have increased or are granted authority to increase their tuition fees during school year 1989-1990. Otherwise, such increase shall be so applicable not later than the opening of the next school year beginning 1990.\n(c) Exempted from the provisions of this Act are household or domestic helpers and persons employed in the personal service of another, including family drivers.\nRetail/service establishments regularly employing not more than ten (10) workers may be exempted from the applicability of this Act upon application with and as determined by the appropriate Regional Board in accordance with the applicable rules and regulations issued by the Commission. Whenever an application for exemption has been duly filed with the appropriate Regional Board, action on any complaint for alleged non-compliance with this Act shall be deferred pending resolution of the application for exemption by the appropriate Regional Board.\nIn the event that applications for exemptions are not granted, employees shall receive the appropriate compensation due them as provided for by this Act plus interest of one per cent (1%) per month retroactive to the effectivity of this Act.\n(d) If expressly provided for and agreed upon in the collective bargaining agreements, all increases in the daily basic wage rates granted by the employers three (3) months before the effectivity of this Act shall be credited as compliance with the increases in the wage rates prescribed herein, provided that, where such increases are less than the prescribed increases in the wage rates under this Act, the employer shall pay the difference. Such increases shall not include anniversary wage increases, merit wage increases and those resulting from the regularization or promotion of employees.\nWhere the application of the increases in the wage rates under this Section results in distortions as defined under existing laws in the wage structure within an establishment and gives rise to a dispute therein, such dispute shall first be settled voluntarily between the parties and in the event of a deadlock, the same shall be finally resolved through compulsory arbitration by the regional branches of the National Labor Relations Commission (NLRC) having jurisdiction over the workplace.\nIt shall be mandatory for the NLRC to conduct continuous hearings and decide any dispute arising under this Section within twenty (20) calendar days from the time said dispute is formally submitted to it for arbitration. The pendency of a dispute arising from a wage distortion shall not in any way delay the applicability of the increase in the wage rates prescribed under this Section."}},{"id":"PH-H5224-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Within a period of four (4) years from the effectivity of this Act and without prejudice to collective bargaining negotiations or agreements or other employment contracts between employers and workers, new business enterprises that may be established outside the NCR and export processing zones whose operation or investments need initial assistance as may be determined by the Department of Labor and Employment in consultation with the Department of Trade and Industry or the Department of Agriculture, as the case may be, shall be exempt from the applicability of this Act for not more than three (3) years from the start of their operations: Provided, That such new business enterprises established in Region III (Central Luzon) and Region IV (Southern Tagalog) shall be exempt from such increases only for two (2) years from the start of their operations, except those established in the Provinces of Palawan, Oriental Mindoro, Occidental Mindoro, Marinduque, Romblon, Quezon and Aurora, which shall enjoy such exemption for not more than three (3) years from the start of their operations."}},{"id":"PH-H5224-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER III"},"text":{"en":"In the case of contracts for construction projects and for security, janitorial and similar services, the prescribed increases in the wage rates of the workers shall be borne by the principals or clients of the construction/service contractors and the contract shall be deemed amended accordingly. In the event, however, that the principal or client fails to pay the prescribed wage rates, the construction/service contractor shall be jointly and severally liable with his principal or client."}},{"id":"PH-H5224-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Upon written permission of the majority of the employees or workers concerned, all private establishments, companies, businesses, and other entities with twenty five (25) or more employees and located within one (1) kilometer radius to a commercial, savings or rural bank shall pay the wages and other benefits of their employees through any of said banks and within the period of payment of wages fixed by Presidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines."}},{"id":"PH-H5224-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Whenever applicable and upon request of a concerned worker or union, the bank shall issue a certification of the record of payment of wages of a particular worker or workers for a particular payroll period."}},{"id":"PH-H5224-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER III"},"text":{"en":"The Department of Labor and Employment shall conduct inspections as often as possible within its manpower constraint of the payroll and other financial records kept by the company or business to determine whether the workers are paid the prescribed minimum wage rates and other benefits granted by law or any Wage Order. In unionized companies, the Department of Labor and Employment inspectors shall always be accompanied by the president or any responsible officer of the recognized bargaining unit or of any interested union in the conduct of the inspection. In non-unionized companies, establishments or businesses, the inspection should be carried out in the presence of a worker representing the workers in the said company. The workers' representative shall have the right to submit his own findings to the Department of Labor and Employment and to testify on the same if he cannot concur with the findings of the labor inspector."}},{"id":"PH-H5224-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER III"},"text":{"en":"The funds necessary to carry out the provisions of this Act shall be taken from the Compensation and Organizational Adjustment Fund, the Contingent Fund, and other savings under the Republic Act No. 6688, otherwise known as the General Appropriations Act of 1989, or from any unappropriated funds of the National Treasury: Provided, That the funding requirements necessary to implement this Act shall be included in the annual General Appropriations Act for the succeeding years."}},{"id":"PH-H5224-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER III"},"text":{"en":"The National Wages Council created under Executive Order No. 614 and the National Productivity Commission created under Executive Order No. 615 are hereby abolished. All properties, records, equipment, buildings, facilities, and other assets, liabilities and appropriations of and belonging to the abovementioned offices, as well as other matters pending therein, shall be transferred to the Commission. All personnel of the above abolished offices shall continue to function in a holdover capacity and shall be preferentially considered for appointments to or placement in the Commission.\nAny official or employee separated from the service as a result of the abolition of office pursuant to this Act shall be entitled to appropriate separation pay and retirement and other benefits accruing to them under existing laws. In lieu, thereof, at the option of the employee, he shall be preferentially considered for employment in the government or in any of its subdivisions, instrumentalities, or agencies, including government-owned or controlled corporations and their subsidiaries."}},{"id":"PH-H5224-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Any person, corporation, trust, firm, partnership, association or entity which refuses or fails to pay any of the prescribed increases or adjustments in the wage rates made in accordance with this Act shall be punished by a fine not exceeding twenty five thousand pesos (P25,000.00) and/or imprisonment of not less than one (1) year nor more than two (2) years: Provided, That any person convicted under this Act shall not be entitled to the benefits provided for under the Probations Law.\nIf the violation is committed by a corporation, trust or firm, partnership, association or any other entity, the penalty of imprisonment shall be imposed on the entity's responsible officers, including, but not limited to, the president, vice-president, chief executive officer, general manager, managing director or partner."}},{"id":"PH-H5224-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER I"},"text":{"en":"The Secretary of Labor and Employment shall promulgate the necessary rules and regulations to implement the provisions of this Act."}},{"id":"PH-H5224-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Al laws, orders, issuances, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly. If any provision or part of this Act, or the application thereof to any person or circumstance, is held invalid or unconstitutional, the remainder of this Act or the application of such provision or part thereof to other persons or circumstances shall not be affected thereby.\nNothing in this Act shall be construed to reduce any existing wage rates, allowances and benefits of any form under existing laws, decrees, issuances, executive orders, and/or under any contract or agreement between the workers and the employers."}},{"id":"PH-H5224-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER I"},"text":{"en":"This Act take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier.\nApproved: June 9, 1989 RULES IMPLEMENTING REPUBLIC ACT NO. 6727 Pursuant to the authority granted to the Secretary of Labor and Employment under Section 13 of Republic Act No. 6727, otherwise known as the Wage Rationalization Act, the following rules are hereby issued for guidance and compliance by all concerned:\nDefinition of Terms. As used in this Rules —\na) \"Act\" means Republic Act No. 6727;\nb) \"Commission\" means the National Wages and Productivity Commission;\nc) \"Board\" means the Regional Tripartite Wages and Productivity Board;\nd) \"Agriculture\" refers to farming in all its branches and among others, includes the cultivation and tillage of the soil, production, cultivation, growing and harvesting of any agricultural or horticultural commodities, dairying, raising of livestock or poultry, the culture of fish and other aquatic products in farms or ponds, and any activities performed by a farmer or on a farm as an incident to or in conjunction with such farming operations, but does not include the manufacturing and/or processing of sugar, coconut, abaca, tobacco, pineapple, aquatic or other farm products;\ne) \"Plantation Agricultural Enterprise\" is one engaged in agriculture with an area of more than 24 hectares in a locality or which employs at least 20 workers. Any other agricultural enterprise shall be considered as \"Non-Plantation Agricultural Enterprise\";\nf) \"Retail Establishment\" is one principally engaged in the sale of goods to end-users for personal or household use;\ng) \"Service Establishment\" is one principally engaged in the sale of service to individuals for their own or household use and is generally recognized as such;\nh) \"Cottage/Handicraft Establishment\" is one engaged in an economic endeavor in which the products are primarily done in the home or such other places for profit which requires manual dexterity and craftmanship and whose capitalization does not exceed P500,000, regardless of previous registration with the defunct NACIDA;\n(i) \"National Capital Region\" covers the cities of Kalookan, Manila, Pasay and Quezon and the municipalities of Las Piñas, Makati, Malabon, Mandaluyong, Marikina, Muntinlupa, Navotas, Parañaque, Pasig, Pateros, San Juan, Taguig and Valenzuela;\nj) \"Region III\" covers the provinces of Bataan, Bulacan, Nueva Ecija, Pampanga, Tarlac, and Zambales and the cities of Angeles, Cabanatuan, Olongapo, Palayan and San Jose;\nk) \"Region IV\" covers the provinces of Aurora, Batangas, Cavite, Laguna, Marinduque, Occidental Mindoro, Oriental Mindoro, Palawan, Quezon, Rizal and Romblon and the cities of Batangas, Cavite, Lipa, Lucena, Puerto Princesa, San Pablo, Tagaytay and Trece Martires;\nl) \"Department\" refers to the Department of Labor and Employment;\nm) \"Secretary\" means the Secretary of Labor and Employment;\nn) \"Basic Wage\" means all remuneration or earnings paid by an employer to a worker for services rendered on normal working days and hours but does not include cost-of-living allowances, profit sharing payments, premium payments, 13th month pay or other monetary benefits which are not considered as part of or integrated into the regular salary of the workers on the date the Act became effective;\no) \"Statutory Minimum Wage\" is the lowest wage rate fixed by law that an employer can pay his workers;\np) \"Wage Distortion\" means a situation where an increase in prescribed wage rates results in the elimination or severe contraction of intentional quantitative differences in wage or salary rates between and among employee groups in an establishment as to effectively obliterate the distinctions embodied in such wage structure based on skills, length of service, or other logical bases of differentiation;\nq) \"Capitalization\" means paid-up capital, in the case of a corporation, and total invested capital, in the case of a partnership or single proprietorship.\nWage Increase"}},{"id":"PH-H5224-A1_2","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Coverage. — The wage increase prescribed under the Act shall apply to all workers and employees in the private sector regardless of their position, designation or status, and irrespective of the method by which their wages are paid, except;\na) Household or domestic helpers, including family drivers and workers in the personal service of another;\nb) Workers and employees in retail/service establishments regularly employing not more than 10 workers, when exempted from compliance with the Act, for a period fixed by the Commission/Boards in accordance with Section 4 (c) of the Act and Section 15, Chapter 1 of this Rules;\nc) Workers and employees in new business enterprises outside the National Capital Region and export processing zones for a period of not more than two or three years, as the case may be, from the start of operations when exempted in accordance with Section 5 of the Act and Section 15, Chapter 1 of this Rules;\nd) Workers and employees receiving a basic wage of more than P100.00 per day."}},{"id":"PH-H5224-A2_2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Effectivity. — The Act takes effect on July 1, 1989, 15 days following its complete publication in two newspapers of general circulation on June 15, 1989 pursuant to Section 15 thereof."}},{"id":"PH-H5224-A3_2","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Amount of Minimum Wage Increase. — Effective July 1, 1989, the daily statutory minimum wage rates of covered workers and employees shall be increased as follows:\na) P25.00 for those in the National Capital Region;\nb) P25.00 for those outside the National Capital Region, except for the following:\n— P20.00 for those in plantation agricultural enterprises with an annual gross sales of less than P5 million in the fiscal year immediately preceding the effectivity of the Act;\n— P15.00 for those in the following enterprises:\n1. Non-plantation agriculture\n2. Cottage/handicraft\n3. Retail/Service regularly employing not more than 10 workers.\n4. Business enterprises with a capitalization of not more than P500,000 and employing not more than 20 workers."}},{"id":"PH-H5224-A4_2","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER I"},"text":{"en":"When Wage Increase Due Other Workers . —\na) All workers and employees who, prior to July 1, 1989, were already receiving a basic wage above the statutory minimum wage rates provided under Republic Act 6640 but not over P100.00 per day shall receive a wage increase equivalent to that provided in the preceding Section.\nb) Those receiving not more than the following monthly wage rates prior to July 1, 1989 shall be deemed covered by the preceding subsection:\n(i) P3,257.50 — where the workers and employees work everyday, including premium payments for Sundays or rest days, special days and regular holidays.\n(ii) P3,041.67 — where the workers and employees do not work but considered paid on rest days, special days and regular holidays.\n(iii) P2,616.67 — where the workers and employees do not work and are not considered paid on Sundays or rest days.\n(iv) P2,183.33 — where the workers and employees do not work and are not considered paid on Saturdays and Sundays or rest days.\nc) Workers and employees who, prior to July 1, 1989, were receiving a basic wage of more than P100.00 per day or its monthly equivalent, are not by law entitled to the wage increase provided under the Act. They may, however, receive wage increases through the correction of wage distortions in accordance with Section 16, Chapter 1 of this Rules."}},{"id":"PH-H5224-A5_2","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Daily Statutory Minimum Wage Rates. — The daily statutory minimum wage rates of workers and employees shall be as follows:\nUnder RA 6640 Under RA 6727 Sector/Industry (Effective (Effective Dec. 14, 1987) July 1, 1989 )\nA. NATIONAL CAPITAL REGION\nNon-Agriculture P64.00 P89.00\nAgriculture\nPlantation 54.00 79.00 Non-Plantation 43.50 68.50 Cottage/Handicraft Employing more than 30 workers 52.00 77.00 Employing not more than 30 workers 50.00 75.00 Private hospitals With bed capacity of more than 100 64.00 89.00 With bed capacity or 100 or less 60.00 85.00 Retail/Service Employing more than 15 workers 64.00 89.00 Employing 11 to 15 workers 60.00 85.00 Employing not more than 10 workers 43.00 68.00\nB. OUTSIDE NATIONAL CAPITAL REGION\nNon-agriculture 64.00 89.00 Agriculture Plantation with annual gross sales of P5M or more 54.00 79.00 Plantation with annual gross sales less than P5M 54.00 74.00 Non-Plantation 43.50 58.50 Cottage/Handicraft Employing more than 30 workers 52.00 67.00 Employing not more than 30 workers 50.00 65.00 Private Hospitals 60.00 85.00 Retail/Service Cities w/ population of more than 150,000 Employing more than 15 workers 64.00 89.00 Employing 11 to 15 workers 60.00 85.00 Employing not more than 10 workers 43.00 58.00 Municipalities and Cities with population not more than 150,000 Employing more than 10 workers 60.00 85.00 Employing not more than 10 workers 43.00 58.00 Sugar Mills 66.00 91.00 Agriculture Plantation with annual gross sales of P5M or more 48.50 73.50 Plantation with annual gross sales of less than P5M 48.50 68.50 Non-plantation 43.50 58.50 Business Enterprises with Capitalization of not more than P500,000 and employing not more than 20 workers Non-Agriculture 64.00 79.00 Agriculture Plantation Products Other than Sugar 54.00 69.00 Sugar 48.50 63.50 Private Hospitals 60.00 75.00 Retail/Service Cities w/ population of more than P150,000 Employing more than 15 workers 64.00 79.00 Employing 11 to 15 workers 60.00 75.00 Municipalities and Cities w/ population of not more than 150,000 Employing more than 10 workers 60.00 75.00"}},{"id":"PH-H5224-A6_2","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Suggested Formula in Determining the Equivalent Monthly Statutory Minimum Wage Rates. — Without prejudice to existing company practices, agreements or policies, the following formula may be used as guides in determining the equivalent monthly statutory minimum wage rates:\na) For those who are required to work everyday including Sundays or rest days, special days and regular holidays:\nEquivalent Applicable daily wage rate Monthly = (ADR) x 390.90 days ————————— Rate (EMR) 12 Where 390.90 days = 302 days — Ordinary working days 20 days — 10 regular holidays x 200%\n66.30 days — 51 rest days x 130%\n2.60 days — 2 special days x 130%\n390.90 days — Total equivalent number of days.\nNote: For workers whose rest days fall on Sundays, the number of rest days in a year is reduced from 52 to 51 days, the last Sunday of August being a regular holiday under Executive Order No. 203. For purposes of computation, said holiday, although still a rest day for them, is included in the ten regular holidays. For workers whose rest days do not fall on Sundays, the number of rest days is 52 days, as there are 52 weeks in a year.\nNothing herein shall be construed as authorizing the reduction of benefits granted under existing agreements or employer practices/policies."}},{"id":"PH-H5224-A7_2","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Basis of Minimum Wage Rates. — The statutory minimum wage rates prescribed under the Act shall be for the normal working hours, which shall not exceed eight hours of work a day."}},{"id":"PH-H5224-A8_2","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Credible Wage Increase. —\na) No wage increase shall be credited as compliance with the increases prescribed under the Act unless expressly provided under collective bargaining agreements, and, such wage increase was granted not earlier than April 1, 1989 but not later than July 1, 1989. Where the wage increase granted is less than the prescribed increase under the Act, the employer shall pay the difference.\nb) Anniversary wage increase provided in collective agreements, merit wage increase, and those resulting from the regularization or promotion of employees shall not be credited as compliance thereto."}},{"id":"PH-H5224-A9_2","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Workers Paid by Results. —\na) All workers paid by results, including those who are paid on piecework, takay, pakyaw, or task basis, shall receive not less than the applicable statutory minimum wage rates prescribed under the Act for the normal working hours which shall not exceed eight hours work a day, or a proportion thereof for work of less than the normal working hours.\nThe adjusted minimum wage rates for workers paid by results shall be computed in accordance with the following steps:\n1) Amount of increase in AMW* — Previous AMW x 100 = % increase;\n2) Existing rate/piece x % increase = increase in rate/piece;\n3) Existing rate/piece + increase in rate/piece = Adjusted rate/piece.\n*Where AMW is the applicable minimum wage rate.\nb) The wage rates of workers who are paid by results shall continue to be established in accordance with Article 101 of the Labor Code, as amended and its implementing regulations."}},{"id":"PH-H5224-A10_2","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Wages of Special Groups of Workers. — Wages of apprentices, learners and handicapped workers shall in no case be less than 75 percent of the applicable statutory minimum wage rates.\nAll recognized learnership and apprenticeship agreements entered into before July 1, 1989 shall be considered as automatically modified insofar as their wage clauses are concerned to reflect the increases prescribed under the Act."}},{"id":"PH-H5224-A11_2","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Application to Contractors. — In the case of contracts for construction projects and for security, janitorial and similar services, the prescribed wage increases shall be borne by the principals or clients of the construction/service contractors and the contract shall be deemed amended accordingly. In the event, however, that the principal or client fails to pay the prescribed wage rates, the construction/service contractor shall be jointly and severally liable with his principal or client."}},{"id":"PH-H5224-A12_2","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Application to Private Educational Institutions. — Private educational institutions which increased tuition fees beginning school year 1989-1990 shall comply with the P250.00 per day wage increase prescribed under the Act effective as follows:\na) In cases where the tuition fee increase was effected before the effectivity of the Act, the wage increase shall take effect on July 1, 1989.\nb) In cases where the tuition fee increase was effected on or after the effectivity of the Act, the wage increase shall take effect not later than the date the school actually increased tuition fees but in the latter case, such wage increase may not be made retroactive to July 1, 1989.\nBeginning school year 1990-1991, all schools shall implement the wage increase regardless of whether or not they have actually increased tuition fees."}},{"id":"PH-H5224-A13_2","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Mobile and Branch Workers. — The statutory minimum wage rates of workers, who by the nature of their work have to travel, shall be those applicable in the domicile or head office of the employer.\nThe minimum wage rates of workers working in branches or agencies of establishments in or outside the National Capital Region shall be those applicable in the place where they are stationed."}},{"id":"PH-H5224-A14_2","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Transfer of Personnel. — The transfer of personnel to areas outside the National Capital Region shall not be a valid ground for the reduction workers transferred to the National Capital Region shall be entitled to the minimum wage rate applicable therein."}},{"id":"PH-H5224-A15_2","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Exemptions. —\na) The following establishments may be exempted from compliance with the wage increase prescribed under the Act:\n1) Retail/Service establishments regularly employing not more than 10 workers upon application with and as determined by the appropriate Board in accordance with applicable guidelines to be issued by the Commission.\n2) New business enterprises that may be established outside the National Capital Region and export processing zones from July 1, 1989 to June 30, 1993, whose operation or investments need initial assistance may be exempted for not more than three years from the start of operations, subject to guidelines to be issued by the Secretary in consultation with the Department of Trade and Industry and the Department of Agriculture.\nNew business enterprises in Region III (Central Luzon) and Region IV (Southern Tagalog) may be exempted for two years only from start of operations, except those that may be established in the provinces of Palawan, Oriental Mindoro, Occidental Mindoro, Marinduque, Romblon, Quezon and Aurora, which may also be exempted for not more than three years from the start of operations.\nb) Whenever an application for exemption has been duly filed with the appropriate office in the Department/Board, action by the Regional Office of the Department on any complaint for alleged non-compliance with the Act shall be deferred pending resolution of the application for exemption.\nc) In the event that the application for exemption is not granted, the workers and employees shall receive the appropriate compensation due them as provided for under the Act plus interest of one percent per month retroactive to July 1, 1989 or the start of operations whichever is applicable."}},{"id":"PH-H5224-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Effects on Existing Wage Structure. — Where the application of the wage increase prescribed herein results in distortions in the wage structure within an establishment which gives rise to a dispute therein, such dispute shall first be settled voluntarily between the parties. In the event of a deadlock, such dispute shall be finally resolved through compulsory arbitration by the regional arbitration branch of the National Labor Relations Commission (NLRC) having jurisdiction over the workplace.\nThe NLRC shall conduct continuous hearings and decide any dispute arising from wage distortions within twenty calendar days from the time said dispute is formally submitted to it for arbitration.\nThe pendency of a dispute arising from a wage distortion shall not in any way delay the applicability of the increases in the wage rates prescribed under the Act.\nAny issue involving wage distortion shall not be a ground for a strike/lockout."}},{"id":"PH-H5224-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Complaints for Non-Compliance. — Complaints for non-compliance with the wage increases prescribed under the Act shall be filed with the Regional Offices of the Department having jurisdiction over the workplace and shall be the subject of enforcement proceedings under Articles 128 and 129 of the Labor Code, as amended."}},{"id":"PH-H5224-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Conduct of Inspection by the Department. — The Department shall conduct inspections of establishments, as often as necessary, to determine whether the workers are paid the prescribed wage rates and other benefits granted by law or any Wage Order. In the conduct of inspection in unionized companies, Department inspectors shall always be accompanied by the president or other responsible officer of the recognized bargaining unit or of any interested union. In the case of non-unionized establishments, a worker representing the workers in the said company shall accompany the inspector.\nThe workers' representative shall have the right to submit his own findings to the Department and to testify on the same if he does not concur with the findings of the labor inspector."}},{"id":"PH-H5224-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Payment of Wages. — Upon written petition of the majority of the workers and employees concerned, all private establishments, companies, businesses and other entities with at least twenty-five workers and located within one kilometer radius to a commercial, savings or rural bank, shall pay the wages and other benefits of their workers through any of said banks within the period and in the manner and form prescribed under the Labor Code as amended."}},{"id":"PH-H5224-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Duty of Bank. — Whenever applicable and upon request of a concerned worker or union, the bank through which wages and other benefits are paid shall issue a certification of the record of payment of said wages and benefits of a particular worker or workers for a particular payroll period.\nThe National Wages and Productivity Commission and Regional Tripartite Wages and Productivity Boards"}},{"id":"PH-H5224-A1_3","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Commission. — The National Wages and Productivity Commission created under the Act shall hold office in the National Capital Region. The Commission shall be attached to the Department for policy and program coordination."}},{"id":"PH-H5224-A2_3","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Powers and Functions of the Commission. — The Commission shall have the following powers and functions:\na) To act as the national consultative and advisory body to the President of the Philippines and Congress on matters relating to wages, incomes and productivity;\nb) To formulate policies and guidelines on wages, incomes and productivity improvement at the enterprise, industry and national levels;\nc) To prescribe rules and guidelines for the determination of appropriate minimum wage and productivity measures at the regional, provincial or industry levels;\nd) To review regional wage levels set by the Regional Tripartite Wages and Productivity Boards to determine if these are in accordance with prescribed guidelines and national development plans;\ne) To undertake studies, researches and surveys necessary for the attainment of its functions and objectives, and to collect and complete data and periodically disseminate information on wages and productivity and other related information, including, but not limited to, employment, cost-of-living, labor costs, investments and returns;\nf) To review plans and programs of the Regional Tripartite Wages and Productivity Boards to determine whether these are consistent with national development plans;\ng) To exercise technical and administrative supervision over the Regional Tripartite Wages and Productivity Boards;\nh) To call, from time to time, a national tripartite conference of representatives of government, workers and employers for the consideration of measures to promote wage rationalization and productivity; and\n(i) To exercise such powers and functions as may be necessary to implement this Act."}},{"id":"PH-H5224-A3_3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Composition of the Commission. — The Commission shall be composed of the Secretary as ex-officio Chairman, the Director General of the National Economic and Development Authority (NEDA) as ex-officio Vice-Chairman and two members each from workers and employers sectors who shall be appointed by the President for a term of five years upon recommendation of the Secretary. The recommendees shall be selected from the list of nominees submitted by the workers and employers sectors. The Executive Director of the Commission Secretariat shall also be a member of the Commission.\nThe members of the Commission representing labor and management shall have the same rank, emoluments, allowances and other benefits as those prescribed by law for labor and management representatives in the Employees Compensation Commission."}},{"id":"PH-H5224-A4_3","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Commission Secretariat. — The Commission shall be assisted by a Secretariat to be headed by an Executive Director and two Deputy Directors, who shall be appointed by the President upon recommendation of the Secretary.\nThe Executive Director shall have the rank of a Department Assistant Secretary, while the Deputy Directors that of a Bureau Director shall receive the corresponding salary, benefits and other emoluments of the positions."}},{"id":"PH-H5224-A5_3","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Regional Tripartite Wages and Productivity Boards. — The Regional Wages and Productivity Boards created under the Act in all regions, including autonomous regions as may be established by law, shall hold offices in areas where the Regional Offices of the Department are located."}},{"id":"PH-H5224-A6_3","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Powers and Functions of the Boards. — The Boards shall have the following powers and functions:\na) To develop plans, programs and projects relative to wages, incomes and productivity improvements for their respective regions;\nb) To determine and fix minimum wage rates applicable in their region, provinces or industries therein and to issue the corresponding wage orders, subject to guidelines issued by the Commission;\nc) To undertake studies, researches, and surveys necessary for the attainment of their functions, objectives and programs, and to collect and compile data on wages, incomes, productivity and other related information and periodically disseminate the same;\nd) To coordinate with the other Boards as may be necessary to attain the policy and intention of the Labor Code;\ne) To receive, process and act on applications for exemption from prescribed wage rates as may be provided by law or any Wage Order; and\nf) To exercise such other powers and functions as may be necessary to carry out their mandate under the Labor Code.\nImplementation of the plans, programs and projects of the Boards shall be through the respective Regional Offices of the Department, provided, however, that the Boards shall have technical supervision over the Regional Office of the Department with respect to the implementation of these plans, programs and projects."}},{"id":"PH-H5224-A7_3","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Composition of the Boards. — Each Board shall be composed of the Regional Director of the Department as Chairman, the Regional Directors of the National Economic and Development Authority (NEDA) and Department of Trade and Industry (DTI) as Vice-Chairmen and two members each of workers and employers sectors who shall be appointed by the President for a term of five years upon the recommendation of the Secretary. The recommendees shall be selected from the lists of nominees submitted by the workers and employers sectors.\nEach Board shall be assisted by a Secretariat."}},{"id":"PH-H5224-A8_3","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Authority to Organize and Appoint Personnel. — The Chairman of the Commission shall organize such units and appoint the necessary personnel of the Commission and Board Secretariats, subject to pertinent laws, rules and regulations.\nMinimum Wage Determination"}},{"id":"PH-H5224-A1_4","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Regional Minimum Wages. — The minimum wage rates for agricultural and non-agricultural workers and employees in every region shall be those prescribed by the Boards which shall in no case be lower than the statutory minimum wage rates. These wage rates may include wages by industry, province or locality as may be deemed necessary by the Boards."}},{"id":"PH-H5224-A2_4","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Standards/Criteria for Minimum Wage Fixing. — The regional minimum wages to be established by the Boards shall be as nearly adequate as is economically feasible to maintain the minimum standards of living necessary for the health, efficiency and general well-being of the workers within the framework of the national, economic, and social development programs. In the determination of regional minimum wages, the Boards, shall, among other relevant factors, consider the following:\na) The demand for living wages;\nb) Wage adjustment vis-a-vis the consumer price index;\nc) The cost of living and changes or increases therein;\nd) The needs of workers and their families;\ne) The need to induce industries to invest in the countryside;\nf) Improvements in standards of living;\ng) The prevailing wage levels;\nh) Fair return of the capital invested and capacity to pay of employers;\n(i) Effects on employment generation and family income; and\nj) The equitable distribution of income and wealth along the imperatives of economic and social development."}},{"id":"PH-H5224-A3_4","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Wage Order. — Whenever conditions in the region so warrant, the Board shall investigate and study all pertinent facts; and, based on standards and criteria prescribed herein, shall determine whether a Wage Order should be issued.\nIn the performance of its wage determining functions, the Board shall conduct public hearings and consultations giving notices to employees' and employers' groups, provincial, city and municipal officials and other interested parties."}},{"id":"PH-H5224-A4_4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Effectivity of Wage Order. — Any Wage Order issued by the Boards shall take effect 15 days after its complete publication in at least one newspaper of general circulation in the region."}},{"id":"PH-H5224-A5_4","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Appeal to the Commission. — Any party aggrieved by the Wage Order issued by the Board may file an appeal with the Commission within ten calendar days from the publication of the Order. The Commission shall decide the appeal within sixty calendar days from the date of filing."}},{"id":"PH-H5224-A6_4","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Effect of Appeal. — The filing of the appeal shall not suspend the effectivity of the Wage Order unless the person appealing such order files with the Commission an undertaking with a surety or sureties in such amount as may be fixed by the Commission."}},{"id":"PH-H5224-A7_4","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Wage Distortions. — Where the application of any wage increase resulting from a Wage Order issued by any Board results in distortions in the wage structure within an establishment, the employer and the union shall negotiate to correct the distortions using the grievance procedure under the collective bargaining agreement. If it remains unresolved, it shall be decided through voluntary arbitration within ten calendar days from the time the dispute was referred for voluntary arbitration, unless otherwise agreed by the parties in writing.\nWhere there are no collective agreements or recognized labor unions, the employer and workers shall endeavor to correct the wage distortion. Any dispute arising therefrom shall be settled through the National Conciliation and Mediation Board and if it remains unresolved after ten calendar days of conciliation, it shall be referred to the appropriate branch of the National Labor Relations Commission (NLRC). The NLRC shall conduct continuous hearings and decide the dispute within twenty calendar days from the time said dispute is submitted for compulsory arbitration.\nThe pendency of a dispute arising from a wage distortion shall not in any way delay the applicability of any wage increase prescribed pursuant to the provisions of law or Wage Order."}},{"id":"PH-H5224-A8_4","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Non-Diminution of Benefits. — Nothing in the Act and in this Rules shall be construed to reduce any existing wage rates, allowances and benefits of any form under existing laws, decrees, issuances, executive orders and/or under any contract or agreement between the workers and employers."}},{"id":"PH-H5224-A9_3","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Prohibition Against Injunction. — No preliminary or permanent injunction or temporary restraining order may be issued by any court, tribunal or other entity against any proceedings before the Commission or Boards."}},{"id":"PH-H5224-A10_3","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Penal Provisions. — Any person, corporation, trust, firm, partnership, association or entity which refuses or fails to pay any of the prescribed increases or adjustments in the wage rates, made in accordance with the Act shall be punished by a fine not exceeding P25,000 and/or imprisonment of not less than one year nor more than two years: Provided, that any person convicted under the Act shall not be entitled to the benefits provided for under the Probation Law.\nIf the violation is committed by a corporation, trust or firm, partnership, association or any other entity, the penalty of imprisonment shall be imposed upon the entity's responsible officers, including, but not limited to, the president, vice-president, chief executive officer, general manager, managing director or partner."}},{"id":"PH-H5224-A11_3","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Registration/Reporting Requirement. — Any person, company, corporation, partnership or any other entity engaged in business shall submit annually a verified itemized listing of their labor component to the appropriate Board and the National Statistics Office not later than January 31 of each year, starting on January 31, 1990 in accordance with the form to be prescribed by the Commission. The listing shall specify the names, salaries and wages of their workers and employees below the managerial level including learners, apprentices and disabled/handicapped workers.\nTransitory Provisions"}},{"id":"PH-H5224-A1_5","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Abolition of the National Wages Council and the National Productivity Commission. — The National Wages Council created under Executive Order No. 614 and the National Productivity Commission created under Executive Order No. 615 are abolished. All properties, records, equipment, buildings, facilities, and other assets, liabilities and appropriations of and belonging to the abovementioned offices, as well as other matters pending therein, shall be transferred to the Commission. All personnel of the above-abolished offices shall continue to function in a hold-over capacity and shall be preferentially considered for appointments to or placements in the Commission/ Boards.\nAny official or employee separated from the service as a result of the abolition of offices pursuant to the Act shall be entitled to appropriate separation pay of one month salary for every year of service and/or retirement and other benefits accruing to them under existing laws. In lieu thereof, at the option of the employee, he shall be preferentially considered for employment in the government or in any of its subdivisions, instrumentalities, or agencies, including government-owned or controlled corporations and their subsidiaries."}},{"id":"PH-H5224-A2_5","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Interim Processing of Applications for Exemption and Submission of Reports. — Pending the operationalization of the Commission and Boards, the National Wages Council shall, in the interim, receive and process applications for exemption subject to guidelines to be issued by the Secretary in accordance with Section 11 of the Act.\nReports of establishments on their labor component, including wages and salaries of their workers prescribed under the Act, shall be submitted to the National Wages Council through the Regional Offices of the Department."}},{"id":"PH-H5224-A3_5","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Funding Requirement. — The funds necessary to carry out the provisions of the Act shall be taken from the Compensation and Organizational Adjustment Fund, the Contingent Fund, and other savings under Republic Act No. 6688, otherwise known as the General Appropriations Act of 1989, or from any unappropriated funds of the National Treasury; Provided that the funding requirements necessary to implement the Act shall be included in the Annual General Appropriations Act for the succeeding years."}},{"id":"PH-H5224-A4_5","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Repealing Clause. — All laws, orders, issuances, rules and regulations or parts thereof inconsistent with the provisions of the Act and this Rules are hereby repealed, amended or modified accordingly. If any provision or part of the Act and this Rules, or the application thereof to any person or circumstance shall not be affected thereby."}},{"id":"PH-H5224-A5_5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Effectivity. — This Rules shall take effect on July 1, 1989.\nDone in the City of Manila, Republic of the Philippines this 7th day of July 1989."}}],"pack":"ph-p74"};
  FT["PH-H5225"] = {"id":"PH-H5225","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6728_1989.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":null,"en":"Government Assistance to Students and Teachers in Private Education Act.","orig":"Government Assistance to Students and Teachers in Private Education Act. An Act Providing Government Assistance to Students and Teachers in Private Education, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6728","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-06-10","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6728_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5225-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known as the \" Government Assistance To Students and Teachers In Private Education Act .\""}},{"id":"PH-H5225-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. - It is declared policy of the State in conformity with the mandate of the Constitution, to promote and make quality education accessible to all Filipino citizens. The State also hereby recognizes the complementary roles of public and private educational institutions in the educational system and the invaluable contribution that the private schools have made and will make to education. For these purposes, the State shall provide the mechanisms to improve quality in private education by maximizing the use of existing resources of private education, recognizing in the process the government responsibility to provide basic elementary and secondary education as having priority over its function to provide for higher education."}},{"id":"PH-H5225-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Criteria for Assistance. - The programs for assistance shall be based on a set of criteria which shall include, among others, tuition fees charged by the schools, the socio-economic needs of each region, overall performance of the schools, the academic qualifications and the financial needs of the students, as well as the geographic spread and size of student population.\nIn addition to the foregoing criteria, within such reasonable time as the State Assistance Council may determine, student grantees under the Private Education Student Financial Assistance Program shall be enrolled in schools which have accredited programs or are applying for accreditation as determined by the Federation of Accrediting Agencies of the Philippines, namely: The Philippine Association of Accredited Schools, Colleges and Universities, the Association of Christian Schools and Colleges Accrediting Agency, and the Philippine Association of Colleges and Universities Commission on Accreditation.\nPreference shall be given to students whose family income is not more than thirty six thousand pesos (P36,000) or such amount as may be determined by the Council, as defined hereinafter.\nFor purposes of this Act, programs of assistance to students of private post-secondary education shall likewise be extended to students of community colleges and students in non-degree programs including vocational and technical courses. Implementation of the program shall encourage students to undergo tertiary education in the same region where their families reside.\nThe programs of assistance under this Act shall be extended only to students who are citizens of the Philippines."}},{"id":"PH-H5225-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Forms of Assistance. - Assistance to private education shall consist of:\n(1) Tuition fee supplements for students in private high schools, including students in vocational and technical courses;\n(2) High School Textbook Assistance Fund: Provided, That students in public schools shall be provided a comprehensive textbook program under the Secondary Education Development Program (SEDP);\n(3) Expansion of the existing Educational Service Contracting (ESC) Scheme;\n(4) The voucher system of the Private Education Student Financial Assistance Program (PESFA);\n(5) Scholarship grants to students graduating as valedictorians and salutatorians from secondary schools;\n(6) Tuition fee supplements to students in private colleges and universities;\n(7) Education Loan Fund; and\n(8) College Faculty Development Fund."}},{"id":"PH-H5225-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Tuition Fee Supplement for Students in Private High School. - (1) Financial assistance for tuition for students in private high schools shall be provided by the government through a voucher system in the following manner:\n(a) For students enrolled in schools charging less than one thousand five hundred pesos (P1,500) per year in tuition and other fees during school year 1988-1989 or such amount in subsequent years as may be determined from time to time by the State Assistance Council: The Government shall provide them with a voucher equal to two hundred ninety pesos (P290.00): Provided, That the student pays in the 1989-1990 school year, tuition and other fees equal to the tuition and other fees paid during the preceding academic year: Provided, further, That the Government shall reimburse the vouchers from the schools concerned within sixty (60) days from the close of the registration period: Provided, furthermore, That the student's family resides in the same city or province in which the high school is located unless the student has been enrolled in that school during the previous academic year.\n(b) For students enrolled in schools charging above one thousand five hundred pesos (P1,500) per year in tuition and other fees during the school year 1988-1989 or such amount in subsequent years as may be determined from time to time by the State Assistance Council, no assistance for tuition fees shall be granted by the Government: Provided, however, That the schools concerned may raise their tuition fees subject to Section 10 hereof.\n(2) Assistance under paragraph (1), subparagraphs (a) and (b) shall be granted and tuition fees under subparagraph (c) may be increased, on the condition that seventy percent (70%) of the amount subsidized allotted for tuition fee or of the tuition fee increases shall go to the payment of salaries, wages, allowances and other benefits of teaching and non-teaching personnel except administrators who are principal stockholders of the school, and may be used to cover increases as provided for in the collective bargaining agreements existing or in force at the time when this Act is approved and made effective: Provided, That government subsidies are not used directly for salaries of teachers of non-secular subjects. At least twenty percent (20%) shall go to the improvement or modernization of buildings, equipment, libraries, laboratories, gymnasia and similar facilities and to the payment of other costs of operation. For this purpose, school shall maintain a separate record of accounts for all assistance received from the government, any tuition fee increase, and the detailed disposition and use thereof, which record shall be made available for periodic inspection as may be determined by the State Assistance Council, during business hours, by the faculty, the non-teaching personnel, students of the school concerned, the Department of Education, Culture and Sports and other concerned government agencies."}},{"id":"PH-H5225-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"High School Textbook Assistance Fund. - There shall be established in the Department of Education, Culture and Sports (DECS) a High School Textbook Assistance Fund, so that an assistance on a per student basis shall be given to private schools charging less than one thousand five hundred pesos (P1,500.00) for 1988-1989 per year, or such amount in subsequent years as may be determined from time to time by the State Assistance Council, exclusively for the purchase of high school textbooks, in support of the implementation of the Secondary Education Development Program: Provided, That such fund shall not be used for the purchase of books that will advance or inhibit sectarian interest: Provided, further, That such textbooks are included in the list approved by the Department of Education, Culture and Sports."}},{"id":"PH-H5225-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Expansion of the Existing Educational Service Contracting (ESC) Scheme. - (a) The Department of Education, Culture and Sports (DECS) shall continue to enter into contracts with private schools whereby the Government shall shoulder the tuition and other fees of excess students in public high schools who shall enroll under this program. It shall settle all outstanding obligations before contracting new obligations.\n(b) The Department shall also enter into contract with private schools in communities where there are no public high schools, in which case the Department shall shoulder the tuition and other fees of students who shall enroll in said private schools. The number of such schools assisted by the program will be increased every year such that all schools in this category will be assisted within four (4) years from the promulgation of this Act.\n(c) The amount of assistance to be given by the Government under this Section shall not exceed that determined as the per student cost in public high schools.\n(d) The Department shall fully pay the subsidized amount to participating schools not later than the end of the schoolyear, unless the delay incurred is attributable to the participating schools.\n(e) The amount of assistance shall be allocated and distributed among the fourteen (14) regions in proportion to the total population as well as the high school age population for the first school year: Provided, That starting school year 1990, an equalization scheme shall be implemented by the State Assistance Council."}},{"id":"PH-H5225-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Assistance to College Freshmen. - (a) The Voucher System of Private Education Student Financial Assistance (PESFA) Program. The existing Private Education Student Financial Assistance (PESFA) Program which covers degree and vocational/technical courses shall be expanded so that a minimum of ten percent (10%) for the school year 1989, fifteen percent (15%) for the school year 1990, twenty percent (20%) for the school year 1991, twenty-five percent (25%) for the school year 1992 and thereafter, of all enrolling first year students can benefit from a full or partial scholarship, plus an allowance. Such financial assistance shall be granted to deserving underprivileged students, who shall be selected on the basis of family income, geographic spread and results of competitive examinations to be given by the Department of Education, Culture and Sports to students in all secondary schools. The program shall be equitably allocated to provinces and cities in accordance with regional and national plans to priority courses as determined by the Department of Education, Culture and Sports in coordination with the National Economic Development Authority (NEDA). The priority courses shall be submitted to Congress at the start of this program and any changes thereon periodically.\nFor purposes of this Act, an underprivileged student shall refer to a student whose annual gross income, if any, and that of the combined annual gross income of his parents do not exceed thirty-six thousand pesos (P36,000).\n(b) Tuition Waiver. - Private colleges and universities shall provide for full or half tuition waivers for five percent (5%) of the entering freshmen, which shall include among others, valedictorians and salutatorians of both public high schools and private high schools charging less than one thousand five hundred pesos (P1,500) per student per year as of school year 1988-1989, or such amount in subsequent years as may be determined by the State Assistance Council: Provided, That those valedictorians and salutatorians meet admission tests and retention requirements of the schools concerned. For this purpose, the tuition rates for entering freshmen in all private schools and colleges may be determined by the school itself, after appropriate consultations with parents, students and the alumni of the school. For this purpose, audited financial statements shall be made available to authorized representatives of these sectors.\n(c) Allowance of Valedictorians. - Subject to rules and regulations as may be promulgated by the State Assistance Council, valedictorians referred to under subparagraph (b) above, may, in addition to tuition waivers granted by the school concerned, be entitled to such allowances from the government as are provided to PESFA grantees, provided they shall enroll in priority courses.\n(d) Allowance for other Honorees. - In case the graduating class is composed of more than two hundred and fifty students, all salutatorians and first honorable mention graduates thereof may also be entitled to the allowance granted to valedictorians under the preceding paragraph."}},{"id":"PH-H5225-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Further Assistance To Students in Private Colleges and Universities. - Tuition fee supplements for non-freshmen students of private colleges and universities in priority course programs determined by the Department of Education, Culture and Sports shall be provided by the government through a voucher system in the following manner:\n(a) For re-enrolling students in priority programs in schools, charging an effective per-unit tuition rate of eighty pesos (P80) or less per unit or such amount in subsequent years as may be determined by the State Assistance Council: The Government shall provide the student with a voucher with a value equivalent to the tuition fee increase: Provided, That all schools in this category shall not be allowed to raise their fees by more than twelve pesos (P12.00) per unit, for both priority and non-priority courses; and Provided, That such assistance shall be given only to students who have completed one academic year by June 1989 in priority programs and shall not apply to future college students and to current college students who transfer outside of their region.\n(b) For students in schools charging an effective per unit tuition rate of more than eighty pesos (P80) per unit or such amount in subsequent years as may be determined from time to time by the Senate Assistance Council: The Government shall provide no assistance, and the schools can determine their own tuition rates, subject to Section 10 hereof: Provided, That they grant full or half-tuition waivers to five percent (5%) of all their students.\n(c) Schools with accredited programs charging a tuition rate of less than eighty pesos (P80.00) per unit or such amount in subsequent years as may be determined from time to time by the State Assistance Council, may continue to determine tuition rates, subject to Section 10 hereof, and non-freshmen students in their accredited priority courses will be entitled to a voucher equivalent to the tuition increase as in paragraph (a) hereof.\n(d) Government assistance and tuition increases as described in this Section shall be governed by the same conditions as provided under Section 5 (2)."}},{"id":"PH-H5225-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Consultation. - In any proposed increase in the rate of tuition fee, there shall be appropriate consultations conducted by the school administration with the duly organized parents and teachers associations and faculty associations with respect to secondary schools, and with students governments or councils, alumni and faculty associations with respect to colleges. For this purpose, audited financial statements shall be made available to authorized representatives of these sectors. Every effort shall be exerted to reconcile possible differences. In case of disagreement, the alumni association of the school or any other impartial body of their choosing shall act as arbitrator."}},{"id":"PH-H5225-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Education Loan Fund. - (a) \"Study Now, Pay Later Plan\". There is hereby created a special fund to be known as the Students' Loan Fund to be administered by the Department of Education, Culture and Sports, or upon delegation by the Department, by the Student Loan Fund Authority created under Republic Act No. 6014 which is hereby reinstituted pursuant to the terms of the same Republic Act which shall be used to finance educational loans to cover matriculation and other school fees and educational expenses for book, subsistence and board and lodging.\n(b) Amounts covering payments for tuition, matriculation and other school fees shall be paid directly to the school concerned.\n(c) Any loan granted under this Section shall be paid by the student-debtor after he has finished the course or profession for which the proceeds of the loan was expended, but only after a period of two (2) years from the time he has acquired an employment: Provided, however, That interest at the rate of not more than twelve percent per annum shall accrue on the balance thereof.\n(d) Social Security Fund. The Social Security System Fund shall make available low interest educational loans to its members and to private educational institutions for school buildings and/or improvement of their plants and facilities."}},{"id":"PH-H5225-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Limitation. - The right of any student to avail himself of the benefits under this Act shall not apply:\n(a) If he fails for one (1) schoolyear in the majority of the academic subjects in which he has enrolled during the course of his study unless such failure is due to some valid cause beyond his control; and\n(b) If he enrolls for the first time, or transfers, outside of the region where he is domiciled unless the course he wants to pursue is a priority course as determined by the Department of Education, Culture and Sports and is not offered in any private school in his region."}},{"id":"PH-H5225-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"College Faculty Development Fund. - For the purpose of improving the quality of teaching in higher education, there is hereby established in Department of Education, Culture and Sports a College Faculty Development Fund to provide for scholarships for graduate degrees and non-degree workshops or seminars for faculty members in private colleges and universities: Provided, That faculty member recipients of such scholarships shall serve three (3) years return service for every year of scholarship availed of. The scholarship shall be in priority courses as determined by the Department of Education, Culture and Sports in coordination with the National Economic Development Authority (NEDA) and cannot be awarded to promote or inhibit sectarian purposes."}},{"id":"PH-H5225-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Program Administration/Rules and Regulations. - The State Assistance Council shall be responsible for policy guidance and direction, monitoring and evaluation of new and existing programs, and the promulgation of rules and regulations, while the Department of Education, Culture and Sports shall be responsible for the day to day administration and program implementation. Likewise, it may engage the services and support of any qualified government or private entity for its implementation.\nThe State Assistance Council (SAC), hereinafter known as the Council, shall be headed by the Secretary of Education, Culture and Sports as chairman, with representatives from NEDA, DBM, DOST, and representatives from duly organized nationwide associations of teachers, students and school administrators as members. The last three (3) members shall be appointed by the President upon the recommendation of their respective sectors for a term of four (4) years.\nThe Council shall meet, from time to time, as the need arises, to assess the effectivity of the programs and to ensure that schools, colleges and universities where student recipients are enrolled continue to provide quality education. For this purpose, the Council shall establish criteria, including accreditation status, to determine which schools, colleges and universities may continue to enroll students who are recipients of government assistance under this Act."}},{"id":"PH-H5225-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Appropriations. - (a) The appropriations of the Department of Education, Culture and Sports authorized in General Appropriations Act for Fiscal Year 1989, Republic Act No. 6688, for A.7.d Implementation of programs for secondary education, A.7.e Implementation of programs for higher education, A.7.g Implementation of free secondary education shall be reduced as far as practicable on a proportionate basis by region to provide funds for the requirements of this Act in Fiscal Year 1989: Provided, That savings from any other item of appropriation of the Department of Education, Culture and Sports may be utilized for the implementation of this Act in Fiscal Year 1989: Provided, further, That any deficiency shall be taken from any or all of the following sources:\n(1) Portions of the coconut levies authorized under Republic Act No. 620 and Presidential Decree No. 1468 and other laws earmarked to finance scholarships for the benefit of deserving children of the coconut farmers, and the income thereof: Provided, That such funds shall be used exclusively for the program of assistance for said children including their books, board and lodging and other allowances in case these are not provided in a particular program of assistance;\n(2) Twenty percent (20%) of the travel tax and airport departure tax collections;\n(3) Ten percent (10%) of any funds collected by the Sugar Regulatory Administration or the Philippine Coconut Authority for students in provinces where they are collected;\n(4) Ten percent (10%) of the net income of the Development Bank of the Philippines;\n(5) Portions of the Overseas Welfare Fund to benefit the dependents or children of overseas workers; and\n(6) Any other lump sum appropriations or collections under the supervision and control of the Office of the President.\nProvided, finally, That the total amount made available to carry out the purposes of this Act shall not exceed five hundred million pesos (P500M) for Fiscal Year 1989.\nThereafter, such amount as may be necessary for its continued implementation shall be included in the annual General Appropriations Act.\n(b) The amount of assistance on a per student basis as determined under Section 5(a) and (b) and Section 9(a) of this Act shall remain the same for the subsequent years unless Congress provides otherwise."}},{"id":"PH-H5225-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Penalties. - In case of any violation of the provisions of this Act or the rules and regulations promulgated pursuant thereto by an institution, the Department of Education, Culture and Sports, upon the recommendation of the Council, may bar the institution from participating in or benefiting from the programs of this Act, and from other programs of the Department, without prejudice to administrative and criminal charges as may be filed against the school and/or its responsible officers under existing laws.\nAny school who shall refuse, as required under paragraph (1) (c) of Section 5, Section 8 (b) and Section 9 (b), to furnish copies of their audited financial statements to concerned sectors with whom they are having consultations prior to tuition fee increases, shall forfeit the right to increase their tuition fees, in addition to other penalties or sanctions as may be imposed under the preceding paragraph or by existing laws."}},{"id":"PH-H5225-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealing Clause. - All laws and decrees particularly Presidential Decree Nos. 932 and 1371 and such letters of instruction, rules and regulations or parts thereof which are inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5225-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. - If any provision of this Act is declared unconstitutional, the same shall not affect the validity and effectivity of the other provisions not affected thereby."}},{"id":"PH-H5225-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity Clause. - This Act shall take effect immediately upon its publication in English in an English newspaper and in Filipino in a Filipino newspaper, both of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5226"] = {"id":"PH-H5226","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6729_1989.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Aurora National Science High School By Separating the Aurora Science High School From the Aurora Provincial High School, and Providing Funds Therefor","orig":"An Act Creating the Aurora National Science High School By Separating the Aurora Science High School From the Aurora Provincial High School, and Providing Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6729","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-06-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6729_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5226-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Aurora Science High School located in the Poblacion of Baler, which is a branch of the Aurora Provincial High School located in Barangay Reserva, Baler, Aurora, is hereby separated from the said provincial high school and thereafter created as an independent educational institution to be known as the Aurora National Science High School."}},{"id":"PH-H5226-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All properties and assets presently pertaining or belonging to the Aurora Science High School are hereby transferred to the newly created Aurora National Science High School."}},{"id":"PH-H5226-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The funding requirement for the operation of the Aurora National Science High School shall be charged to the appropriations for the current fiscal year of the Aurora Science High School. Thereafter, such amount as may be necessary for the implementation of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H5226-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education, Culture and Sports shall make the necessary directive to effect the separation of the Aurora Science High School from the Aurora Provincial High School, as well as to bring about the smooth operation of the Aurora National Science High School under this Act."}},{"id":"PH-H5226-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5227"] = {"id":"PH-H5227","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6730_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Manila-Cavite Coastal Road as the Aguinaldo Boulevard","orig":"An Act Naming the Manila-Cavite Coastal Road as the Aguinaldo Boulevard"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6730","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6730_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5227-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Manila-Cavite coastal road starting from the corner of Roxas Boulevard and MIA road to Cavite shall hereafter be known as the Aguinaldo Boulevard."}},{"id":"PH-H5227-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5228"] = {"id":"PH-H5228","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6731_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Vito Cruz Street in the Districts of Malate and Singalong, City of Manila, and in the Municipality of Makati, Metro Manila, to Pablo de Leon Ocampo Street in Honor of Pablo de Leon Ocampo, Lawyer, Editor, Parliamentarian, Statesman and Nationalist","orig":"An Act Changing the Name of the Vito Cruz Street in the Districts of Malate and Singalong, City of Manila, and in the Municipality of Makati, Metro Manila, to Pablo de Leon Ocampo Street in Honor of Pablo de Leon Ocampo, Lawyer, Editor, Parliamentarian, Statesman and Nationalist"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6731","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6731_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5228-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Vito Cruz Street in the districts of Malate and Singalong, City of Manila, traversing the Municipality of Makati, Metro Manila, is hereby changed to Pablo de Leon Ocampo Street in honor of Pablo de Leon Ocampo, lawyer, editor, parliamentarian, statesman and nationalist."}},{"id":"PH-H5228-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5229"] = {"id":"PH-H5229","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6732_1989.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Allowing Administrative Reconstitution of Original Copies of Certificates of Titles Lost or Destroyed Due to Fire, Flood and Other Force Majeure, Amending for the Purpose Section One Hundred Ten of Presidential Decree Numbered Fifteen Twenty-Nine and Section Five of Republic Act Numbered Twenty-Six","orig":"An Act Allowing Administrative Reconstitution of Original Copies of Certificates of Titles Lost or Destroyed Due to Fire, Flood and Other Force Majeure, Amending for the Purpose Section One Hundred Ten of Presidential Decree Numbered Fifteen Twenty-Nine and Section Five of Republic Act Numbered Twenty-Six"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6732","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-07-17","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6732_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 15 条，缺 10）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5229-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 110 of Presidential Decree No. 1529 is hereby amended to read as follows:\n\"Sec. 110. Reconstitution of Lost or Destroyed Original of Torrens Title. - Original copies of certificates of titles lost or destroyed in the offices of Register of Deeds as well as liens and encumbrances affecting the lands covered by such titles shall be reconstituted judicially in accordance with the procedure prescribed in Republic Act No. 26 insofar as not inconsistent with this Decree. The procedure relative to administrative reconstitution of lost or destroyed certificate prescribed in said Act may be availed of only in case of substantial loss or destruction of land titles due to fire, flood or other force majeure as determined by the Administrator of the Land Registration Authority: Provided, That the number of certificates of titles lost or damaged should be at least ten percent (10%) of the total number in the possession of the Office of the Register of Deeds: Provided, further, That in no case shall the number of certificates of titles lost or damaged be less than five hundred (500).\n\"Notice of all hearings of the petition for judicial reconstitution shall be furnished the Register of Deeds of the place where the land is situated and to the Administrator of the Land Registration Authority. No order or judgment ordering the reconstitution of a certificate of title shall become final until the lapse of fifteen (15) days from receipt by the Register of Deeds and by the Administrator of the Land Registration Authority of a notice of such order or judgment without any appeal having been filed by any such officials.\""}},{"id":"PH-H5229-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For the purpose of the preceding section, Section 5 of Republic Act No. 26 is hereby revived and amended to read as follows:\n\"Sec. 5. Petitions for reconstitution from sources enumerated in Sections 2(a), 2(b), 3(a,) and 3(b) of this Act may be filed with the Register of Deeds concerned by the registered owner, his assigns, or other person, both natural and juridical, having an interest in the property. The petition shall be accompanied with the necessary sources for reconstitution and with an affidavit of the registered owner stating, among other things:\n\"(1) That no deed or other instrument affecting the property had been presented for registration, or, if there be any, the nature thereof, the date of its presentation, as well as the names of the parties, and whether the registration of such deed or instrument is still pending accomplishment;\n\"(2) That the owner's duplicate certificate or co-owner's duplicate is in due form without any apparent intentional alterations or erasures;\n\"(3) That the certificate of title is not the subject of litigation or investigation, administrative or judicial, regarding its genuineness or due execution or issuance;\n\"(4) That the certificate of title was in full force and effect at the time it was lost or destroyed;\n\"(5) That the certificate of title is covered by a tax declaration regularly issued by the Assessor's Office; and \"(6) That real estate taxes have been fully paid up to at least two (2) years prior to the filing of the petition for reconstitution.\n\"If the reconstitution is to be made from any of the sources enumerated in Section 2(b) or 3(b), the affidavit should further state that the owner's duplicate has been lost or destroyed and the circumstances under which it was lost or destroyed. Thereupon, the Register of Deeds shall, no valid reason to the contrary existing, reconstitute the certificate of title as provided in this Act.\""}},{"id":"PH-H5229-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Immediately after the loss or destruction of titles mentioned in Section 2 hereof, a true, complete and faithful inventory of all books, titles, documents, cash and property in the Registry of Deeds concerned shall be prepared by the Land Registration Authority through the newly designated reconstituting officer or Register of Deeds. Said inventory, duly signed and certified under oath by the Administrator of the Land Registration Authority, shall be published in a newspaper of general circulation in the province or city where the loss or destruction of titles occurred."}},{"id":"PH-H5229-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All reconstituted titles shall be reproduced by the Land Registration Authority in at least three image copies or in whatever means by which the original can be reproduced, one copy to be kept by the Land Registration Authority, the second copy to be kept by the National Library Archives Division, and the third copy to be secured in a government fire-proof vault, preferably in the Security Printing Plant of the Central Bank. Such image copy of the original copy of the reconstituted title shall be considered after due authentication by the Land Registration Authority, through the Register of Deeds in the province or city where the land is located, as a duplicate original, and as an authorized source or basis for reconstitution together with the sources enumerated in Section 2 and 3 of Republic Act No. 26."}},{"id":"PH-H5229-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"After reconstitution, said owner's duplicate or co-owner's duplicate exhibited as basis for the reconstitution shall be surrendered to the Register of Deeds and a new certificate of title issued in lieu thereof, the original of which shall be kept by the Register of Deeds and the owners duplicate delivered to the registered owner."}},{"id":"PH-H5229-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 6 of Republic Act No. 26 is hereby declared inoperative."}},{"id":"PH-H5229-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 19 of Republic Act No. 26 is hereby amended to read as follows:\n\"Sec. 19. If the certificate of title considered lost or destroyed, and subsequently found or recovered, is not in the name of the same person in whose favor the reconstituted certificate of title has been issued, the Register of Deeds or the party concerned should bring the matter to the attention of the proper regional trial court, which, after due notice and hearing, shall order the cancellation of the reconstituted certificate of title and render, with respect to the memoranda of new liens and encumbrances, if any, made in the reconstituted certificate of title, after its reconstitution, such judgment as justice and equity may require: Provided, however, That if the reconstituted certificate of title has been cancelled by virtue of any deed or instrument, whether voluntary or involuntary, or by an order of the court, and a new certificate of title has been issued, the procedure prescribed above, with respect to the memorandum of new liens and encumbrances made on the reconstituted certificate of title, after its reconstitution, shall be followed with respect to the new certificate of title, and to such new liens and encumbrances, if any, as may have been on the latter, after the issuance thereof.\""}},{"id":"PH-H5229-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Administrator of the Land Registration Authority, with the approval of the Secretary of Justice, shall issue rules, regulations, and circulars as may be necessary and appropriate to implement this Act, including but not limited to the following:\n(1) The temporary designation of a reconstituting officer or another Register of Deeds;\n(2) The submission of monthly periodic status reports on reconstitution proceedings and reconstituted titles to the Secretary of Justice and the governor or city mayor concerned; and\n(3) The immediate reporting by the reconstituting officer or Register of Deeds to the Secretary of Justice and the governor or city mayor concerned on any verified complaint presented to him."}},{"id":"PH-H5229-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Land Registration Authority Administrator may review, revise, reverse, modify or affirm any decision of the reconstituting officer or Register of Deeds. Any appeal shall be filed within fifteen days from the receipt of the judgment or order by the aggrieved party.\nSECTION 10. Any interested party who by fraud, accident, mistake or excusable negligence has been unjustly deprived or prevented from taking part in the proceedings may file a petition in the proper court to set aside the decision and to reopen the proceedings. The petition shall be verified and must be filed within sixty days after the petitioner learns of the decision but not more than six months from the promulgation thereof."}},{"id":"PH-H5229-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A reconstituted title obtained by means of fraud, deceit or other machination is void ab initio as against the party obtaining the same and all persons having knowledge thereof."}},{"id":"PH-H5229-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Any person who by means of fraud, deceit or other machination obtains or attempts to obtain a reconstituted title shall be subject to criminal prosecution and, upon conviction, shall be liable for imprisonment for a period of not less than two years but not exceeding five years or the payment of a fine of not less than Twenty thousand pesos but not exceeding Two hundred thousand pesos or both at the discretion of the court.\nAny public officer or employee who knowingly approves or assists in securing a decision allowing reconstitution in favor of any person not entitled thereto shall be subject to criminal prosecution and, upon conviction, shall be liable for imprisonment of not less than five years but not exceeding ten years or payment of a fine of not less than Fifty thousand pesos but not exceeding One hundred thousand pesos or both at the discretion of the court and perpetual disqualification from holding public office."}},{"id":"PH-H5229-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All acts, laws, decrees, executive orders, or parts thereof which are inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5229-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall likewise cover administrative reconstitution of copies of original certificates of titles destroyed by fire, flood or other force majeure within a period of fifteen years before the effectivity of this Act."}},{"id":"PH-H5229-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its publication in three newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5230"] = {"id":"PH-H5230","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6733_1989.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"对第 21 条的修改","en":"An Act to Amend Section 21, Title I, Book I of the Revised Administrative Code of 1987, Granting Members of Both Houses of the Congress of the Philippines the General Authority to Administer Oaths, and for Other Purposes","orig":"An Act to Amend Section 21, Title I, Book I of the Revised Administrative Code of 1987, Granting Members of Both Houses of the Congress of the Philippines the General Authority to Administer Oaths, and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6733","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-07-25","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6733_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5230-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 21 of the Revised Administrative Code is hereby amended to read as follows:\n\"SECTION 21. Officials authorized to administer oath. - The following officers have general authority to administer oaths, to wit:\n\"President; Vice-President; Members and Secretaries of both Houses of the Congress; Members of the Judiciary; Secretaries of Departments; provincial governors and lieutenant-governors; city mayors; municipal mayors; bureau directors; regional directors; clerks of courts; registrars of deeds; and other civilian officers in the Philippine public service whose appointments are vested in the President of the Philippines and are subject to confirmation by the Commission of Appointments; all other constitutional officers; and notaries public. A person who by authority of law shall serve in the capacity of the officers mentioned above shall possess the same power.\""}},{"id":"PH-H5230-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 41 of the Administrative Code of 1987 is hereby amended to read as follows:\n\"Sec. 41. Officers Authorized to Administer Oath. - The following officers have general authority to administer oaths: President; Vice-President; Members and Secretaries of both Houses of the Congress; Members of the Judiciary; Secretaries of Departments; provincial governors and lieutenant-governors; city mayors; municipal mayors; bureau directors; regional directors; clerks of courts; registrars of deeds; other civilian officers in the public service of the government of the Philippines whose appointments are vested in the President and are subject to confirmation by the Commission on Appointments; all other constitutional officers; and notaries public.\""}},{"id":"PH-H5230-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Nothing in this Act shall be construed as to disauthorize any person now authorized to administer oaths under existing laws."}},{"id":"PH-H5230-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Members and Secretaries of both Houses of Congress may delegate the authority to committee secretaries or any staffer thereof in the conduct of a pending inquiry or investigation."}},{"id":"PH-H5230-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Those authorized to administer oaths under this Act shall not be required to keep a register of the oaths they administer nor keep or submit copies of the same, except in the case of notaries public, or as otherwise required by existing laws."}},{"id":"PH-H5230-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its publication in at least one (1) national newspaper of general circulation, and as to the amendments of Section 41 of the Administrative Code of 1987, upon the effectivity of said Code."}}],"pack":"ph-p74"};
  FT["PH-H5231"] = {"id":"PH-H5231","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6734_1989.html","fetchedAt":"2026-10-06","articleCount":190,"structureMode":"ARTICLE","title":{"zh":"棉兰老穆斯林自治区组织法","en":"An Act Providing for An Organic Act for the Autonomous Region in Muslim Mindanao","orig":"An Act Providing for An Organic Act for the Autonomous Region in Muslim Mindanao"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6734","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-01","completenessNote":"全文，共 190 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6734_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1、2、3、4、5、6、7、8 条 等 25 处）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5231-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"The name of the Autonomous Region shall be the Autonomous Region in Muslim Mindanao unless provided otherwise by Congress upon the recommendation of the Regional Legislative Assembly."}},{"id":"PH-H5231-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"It is the purpose of this Organic Act to establish the Autonomous Region in Muslim Mindanao, to provide its basic structure of government within the framework of the Constitution and national sovereignty and the territorial integrity of the Republic of the Philippines, and to ensure the peace and equality before the law of all people in the Autonomous Region.\nThe Autonomous Region\nAREA AND SEAT OF GOVERNMENT"}},{"id":"PH-H5231-A1_2","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE II"},"text":{"en":"(1) There is hereby created the Autonomous Region in Muslim Mindanao, to be composed of provinces and cities voting favorably in the plebiscite called for the purpose, in accordance with Section 18, Article X of the Constitution.\n(2) The plebiscite shall be conducted in the provinces of Basilan, Cotabato, Davao del Sur, Lanao del Norte, Lanao del Sur, Maguindanao, Palawan, South Cotabato, Sultan Kudarat, Sulu, Tawi-Tawi, Zamboanga del Norte, and Zamboanga del Sur, and the cities of Cotabato, Dapitan, Dipolog, General Santos, Iligan, Marawi, Pagadian, Puerto Princesa, and Zamboanga."}},{"id":"PH-H5231-A2_2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Regional Legislative Assembly, hereinafter referred to as the Regional Assembly, shall fix by law the permanent seat of government for the Autonomous Region in Muslim Mindanao, taking into consideration accessibility and efficiency in carrying out its mandate under this Act: Provided, That the provisional seat of the Regional Government shall be in Cotabato City.\nGuiding Principles And Policies"}},{"id":"PH-H5231-A1_3","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The area of the Autonomous Region in Muslim Mindanao shall remain an integral and inseparable part of the national territory of the Republic of the Philippines as defined by the Constitution and existing laws.\nThe people of the Autonomous Region shall uphold the Constitution as the fundamental law of the land and unequivocally owe allegiance and fidelity to the Republic of the Philippines.\nThe Autonomous Region shall be governed and administered in accordance with this Organic Act."}},{"id":"PH-H5231-A2_3","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall adopt the policy of settlement of conflicts by peaceful means, and renounce any form of lawless violence as an instrument of redress."}},{"id":"PH-H5231-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall adopt a policy on local autonomy whereby regional powers shall be devolved to local government units where appropriate: Provided, however, That until a regional law implementing this provision is enacted, the local Government Code shall be applicable."}},{"id":"PH-H5231-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Highly urbanized cities within the Autonomous Region shall continue to be governed by their charters. Nothing in this Act shall be construed as to diminish the powers and functions already enjoyed by these cities."}},{"id":"PH-H5231-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall adopt measures to ensure mutual respect for and protection of the distinct beliefs, customs, and traditions among its inhabitants in the spirit of unity in diversity and peaceful co-existence: Provided, That no person in the Autonomous Region shall, on the basis of creed, religion, ethnic origin, parentage or sex, be subjected to any form of discrimination."}},{"id":"PH-H5231-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall adopt educational policies that are responsive to and reflective of the special needs of the people, with due respect to the beliefs, customs and traditions of the inhabitants of the Region."}},{"id":"PH-H5231-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall endeavor to improve the well-being of all its constituents, particularly the marginalized, deprived, disadvantaged, underprivileged and disabled."}},{"id":"PH-H5231-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Subject to the provisions of the Constitution and this Organic Act, and national development policies and programs, the Regional Government shall have authority, power and right in the exploration, development and utilization of its natural resources: Provided, That the indigenous cultural communities shall have priority rights in the areas designated parts of the ancestral domain."}},{"id":"PH-H5231-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Autonomous Region shall provide manpower training programs, create livelihood and job opportunities, allocate equitable preferential rights to its inhabitants, and adopt laws that will safeguard the rights of workers."}},{"id":"PH-H5231-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall uphold and protect the fundamental rights of women and children. In no case shall women and children be exploited, abused or discriminated against."}},{"id":"PH-H5231-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall provide, maintain, and ensure the delivery of basic health education and services."}},{"id":"PH-H5231-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Regional Government shall provide incentives for prompt payment of taxes."}},{"id":"PH-H5231-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The National Government shall provide financial assistance to the Autonomous Region by appropriating such sums as may be necessary to accelerate the development of the Region.\nDevolution of Powers"}},{"id":"PH-H5231-A1_4","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"The fundamental rights and duties of the people in the Autonomous Region are those established in the Constitution and this Organic Act."}},{"id":"PH-H5231-A2_4","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"The powers devolved to the Autonomous Region shall be exercised through the Regional Assembly, the Regional Governor, and the special courts as provided in this Act.\nPowers of Government"}},{"id":"PH-H5231-A1_5","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The Regional Government shall exercise powers and functions necessary for the proper governance and development of all the constituent units within the Autonomous Region consistent with the constitutional policy on regional and local autonomy and decentralization: Provided, That nothing herein shall authorize the diminution of the powers and functions already enjoyed by local government units."}},{"id":"PH-H5231-A2_5","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The Autonomous Region is a corporate entity with jurisdiction in all matters devolved to it by the Constitution and this Organic Act as herein enumerated:\n(1) Administrative organization;\n(2) Creation of sources of revenues;\n(3) Ancestral domain and natural resources;\n(4) Personal, family and property relations;\n(5) Regional, urban and rural planning development;\n(6) Economic, social, and tourism development;\n(7) Educational policies;\n(8) Preservation and development of the cultural heritage;\n(9) Powers, functions and responsibilities now being exercised by the departments of the National Government except:\n(a) Foreign affairs;\n(b) National defense and security;\n(c) Postal service;\n(d) Coinage, and fiscal and monetary policies;\n(e) Administration of justice;\n(f) Quarantine;\n(g) Customs and tariff;\n(h) Citizenship;\n(i) Naturalization, immigration and deportation;\n(j) General auditing, civil service and elections;\n(k) Foreign trade;\n(l) Maritime, land and air transportation and communications that affect areas outside the Autonomous Region; and\n(m) Patents, trademarks, trade names, and copyrights; and\n(10) Such other matters as may be authorized by law for the promotion of the general welfare of the people of the Region."}},{"id":"PH-H5231-A3_2","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The Regional Government may exercise the power of eminent domain.\nInter-Governmental Relations"}},{"id":"PH-H5231-A1_6","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"The President of the Philippines shall exercise general supervision over the Regional Government, including the local government units therein, directly or through the Regional Governor, to ensure that national and regional laws are faithfully executed."}},{"id":"PH-H5231-A2_6","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"The Regional Government shall maintain close coordination with the National Government for the orderly management of the special courts within the Autonomous Region.\nThe Legislative Department"}},{"id":"PH-H5231-A1_7","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The legislative power shall be vested in the Regional Assembly, except to the extent reserved to the people by provisions on initiative and referendum as provided by law."}},{"id":"PH-H5231-A2_7","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Regional Assembly may create, divide, merge, abolish or substantially alter boundaries of any municipality or barangay in accordance with the criteria laid down by existing law subject to approval by a majority of the votes cast in a plebiscite in the political units directly affected. It may also change the names of such local government units, public places and institutions."}},{"id":"PH-H5231-A3_3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Regional Assembly shall approve the budget of the Autonomous Region."}},{"id":"PH-H5231-A4_2","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Regional Assembly shall be composed of Members elected by popular vote, with three (3) members elected from each of the congressional districts."}},{"id":"PH-H5231-A5_2","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Members of the Regional Assembly shall have a term of three (3) years which shall begin, unless otherwise provided by law, at noon on the 31st day of March next following their election.\nNo Member of the Regional Assembly shall serve for more than three (3) consecutive terms. Voluntary renunciation of or removal from office for any length of time shall not be considered as an interruption in the continuity of his service for the full term for which he was elected."}},{"id":"PH-H5231-A6_2","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"In case of vacancy in the Regional Assembly occurring at least one year before the expiration of the term of office, a special election shall be called to fill the vacancy in the manner prescribed by regional law: Provided, That the Member elected shall serve only for the unexpired term."}},{"id":"PH-H5231-A7_2","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"No person shall be a Member of the Regional Assembly unless he is:\n(1) A natural-born citizen of the Philippines;\n(2) At least twenty-one (21) years of age on the day of the election;\n(3) Able to read and write;\n(4) A registered voter of the district in which he shall be elected on the day he files his certificate of candidacy; and\n(5) A resident thereof for a period of not less than five (5) years immediately preceding the day of the election."}},{"id":"PH-H5231-A8_2","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Every Member of the Regional Assembly shall take an oath or affirmation of allegiance to the Republic of the Philippines before taking his seat."}},{"id":"PH-H5231-A9_2","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Unless otherwise provided by Congress, a Member of the Regional Assembly shall receive an annual salary of One hundred twenty thousand pesos (P120,000.00) except the Speaker of the Regional Assembly who shall receive an annual salary of One Hundred forty-four thousand pesos (P144,000.00). They shall not receive during their tenure any other emoluments from the Government."}},{"id":"PH-H5231-A10_2","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Any Member of the Regional Assembly who accepts an appointment and qualifies for any position in the Government, including government-owned or controlled corporations or their subsidiaries, shall automatically forfeit his seat in the Regional Assembly."}},{"id":"PH-H5231-A11_2","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"All Members of the Regional Assembly shall, upon their assumption of office, make a full disclosure of their financial and business interests, including those of their spouses and unmarried children under eighteen (18) years of age living in their households. They shall notify the Assembly of any potential conflict of interest that may arise from the filing of measures of which they are authors.\nAny Member found guilty of non-disclosure as required under This section may be expelled by a two-thirds (2/3) vote of all the Members of the Regional Assembly, without prejudice to his other liabilities under pertinent legislation."}},{"id":"PH-H5231-A12_2","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"No Member of the Regional Assembly may personally appear as counsel before courts of justice or quasi-judicial and other administrative bodies. Neither shall he, directly or indirectly, be interested financially in any contract with, or in any franchise or special privilege granted by the Government, or any subdivision, agency or instrumentality thereof, including any government-owned or controlled corporation or its subsidiary, during his term of office. He shall not intervene in any matter before any office of the Government for his pecuniary benefit or where he may be called upon to act on account of his office."}},{"id":"PH-H5231-A13_2","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"No Member shall be questioned or be held liable in any other place for any speech or debate in the Assembly or in any committee thereof."}},{"id":"PH-H5231-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Regional Assembly shall adopt its own rules of procedure by a majority vote of all its Members including the selection of members of its standing committees and the suspension or expulsion of its Members.\nThe Regional Assembly shall elect from among its Members a Speaker and such other officers as the rules may provide.\nA majority of all the Members of Assembly shall constitute a quorum to do business, but a smaller number may adjourn from day to day and may compel the attendance of absent Members in such manner, and under such penalties, as the Assembly may provide.\nThe Regional Assembly or any of its committees may conduct inquiries or public consultations in aid of legislation in accordance with its rules. The rights of persons appearing in or affected by such inquiries shall be respected.\nThe Regional Assembly shall keep a Journal of its proceedings and a record of its caucuses and meetings. The records and books of accounts of the Assembly shall be preserved and be open to public scrutiny. The Commission on Audit shall publish an annual report of the itemized list of expenditures incurred by the Members of the Assembly within sixty (60) days from the end of every regular session."}},{"id":"PH-H5231-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Regional Assembly may request the presence of the Regional Governor, Regional Vice-Governor, Cabinet members or their deputies, as the rules shall provide, for questioning on matters falling within the scope of their responsibilities.\nSubject to the rules of the Regional Assembly, the legislative power to inquire on matters relating to the exercise of administrative functions by an agency of government within the Autonomous Region shall be in the form of written questions."}},{"id":"PH-H5231-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Except as provided by its rules, the Regional Assembly shall meet in open session. Regular session shall commence on the 4th Monday of April and shall continue to be in session for such number of days as may be determined by the Assembly until thirty (30) days before the opening of its next regular session, exclusive of Saturdays, Sundays and legal holidays.\nThe Regional Assembly may meet in special sessions at the request of one-third (1/3) of all its Members or by call of the Regional Governor. Such special session must be convened with a special agenda."}},{"id":"PH-H5231-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"No bill shall become a law of regional application unless it has passed three (3) readings on separate days, and printed copies thereof in its final form have been distributed to its Members three (3) days before its passage, except when the Regional Governor certifies to the necessity of its immediate enactment to meet a public calamity or emergency."}},{"id":"PH-H5231-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Every bill passed by the Regional Assembly, shall, before it becomes a law, be presented to the Regional Governor. If he approves the same, he shall sign it; otherwise, if the bill contain ultra vires provisions, or if he finds it objectionable on policy grounds, or both, he shall veto it and return it with his objections to the Regional Assembly, which shall enter the objections at large in its Journal and proceed to reconsider it. If, after such reconsideration, two-thirds (2/3) of all Members of the Regional Assembly shall agree to pass the bill, it shall become a law. In all such cases, the vote shall be determined by yeas or nays, and the names of the Members voting for or against shall be entered in the Journal. The Regional Governor shall communicate his veto of any bill to the Regional Assembly within thirty (30) days after the date of receipt thereof; otherwise, it shall become a law as if he had signed it."}},{"id":"PH-H5231-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Speaker of the Regional Assembly shall, within ten (10) working days from approval thereof, submit to the President and to both Houses of Congress a certified true copy of all laws and resolutions approved by the Regional Assembly.\nThe Executive Department"}},{"id":"PH-H5231-A1_8","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The executive power shall be vested in a Regional Governor who shall be elected at large by direct vote of the people of the Autonomous Region."}},{"id":"PH-H5231-A2_8","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall be assisted by a Cabinet of nine (9) members, at least four of whom shall preferably come from indigenous cultural communities: Provided, That the members shall, as far as practicable, come from various provinces and cities within the Autonomous Region.\nThe members of the Cabinet must be registered voters and residents of the Region for at least five (5) years immediately preceding their appointment.\nThe Regional Governor shall appoint the members of the Cabinet subject to confirmation by the Regional Assembly."}},{"id":"PH-H5231-A3_4","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"No person may be elected Governor of the Autonomous Region unless he is a natural-born citizen of the Philippines, a registered voter of the Autonomous Region, able to read and write, at least thirty-five (35) years of age on the day of the election, and a resident of the Autonomous Region for at least five (5) years immediately preceding the election."}},{"id":"PH-H5231-A4_3","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"There shall be a Vice-Governor of the Autonomous Region who shall have the same qualifications and term of office and be elected with and in the same manner as the Regional Governor. He may be removed from office in the same manner as the Regional Governor. The Vice-Governor may be appointed as a member of the Regional Cabinet without need of confirmation by the Regional Assembly."}},{"id":"PH-H5231-A5_3","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Vice-Governor shall likewise be elected by direct vote of the people of the Autonomous Region."}},{"id":"PH-H5231-A6_3","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"(1) The term of office of the Governor and Vice-Governor shall be for a period of three (3) years which shall begin at noon on the 31st day of March next following the day of the election and shall end at noon of the same date three years thereafter.\n(2) No Governor or Vice-Governor shall serve for more than two (2) consecutive terms. Voluntary renunciation of or removal from office for any length of time shall not be considered an interruption in the continuity of the service for the full term for which he was elected."}},{"id":"PH-H5231-A7_3","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Before they enter on the execution of their office, the Regional Governor and the Vice-Governor shall take the following oath or affirmation: \"I do solemnly swear (or affirm) that I will faithfully and conscientiously fulfill my duties as Governor (or Vice-Governor) of the Regional Autonomous Government, preserve and defend the Constitution of the Republic, the Organic Act for the Autonomous Region, and the national and regional laws, do justice to every man, and consecrate myself to the service of the Autonomous Region and the nation. So help me God.\" (In case of Affirmation, last sentence will be omitted.)"}},{"id":"PH-H5231-A8_3","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Unless otherwise provided by Congress, the annual compensation of the Regional Governor and Vice-Governor shall be One hundred eighty thousand pesos (P180,000.00) and One hundred forty-four thousand pesos (P144,000.00), respectively. They shall not receive during their tenure any other emoluments from the Government."}},{"id":"PH-H5231-A9_3","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall be provided with a reasonable housing allowance by the Regional Assembly."}},{"id":"PH-H5231-A10_3","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"In case of death, permanent disability, removal from office, or resignation of the Governor, the Vice-Governor shall become the Governor to serve the unexpired term. In case of death, permanent disability, removal from office, or the resignation of both the Governor and the Vice-Governor, the Speaker of the Regional Assembly shall act as Governor until the Governor and Vice-Governor are elected and qualified in a special election called for the purpose; Provided, That upon assumption as Acting Governor, the Speaker of the Regional Assembly shall temporarily vacate his position as such and an interim Speaker shall be elected: Provided, further, That upon the election and assumption of office of the new Regional Governor, the Speaker shall reassume his office.\nNo special election shall be called to fill a vacancy occurring within one year immediately preceding the next regular election."}},{"id":"PH-H5231-A11_3","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"In case of temporary incapacity of the Regional Governor to perform his duties on account of physical or legal causes, or when he is on official leave of absence or travel outside the territorial jurisdiction of the Republic of the Philippines, the Vice-Governor, or if there be none or in case of his permanent or temporary incapacity or refusal to assume office, the Speaker of the Regional Assembly shall exercise the powers, duties and functions of the Regional Governor."}},{"id":"PH-H5231-A12_3","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor or the Vice-Governor may be removed from office for culpable violation of the Constitution or this Organic Act, treason, bribery, graft and corruption, other high crimes or betrayal of public trust by a three-fourths (3/4) vote of all the Members of the Regional Assembly.\nThe Regional Assembly may initiate the removal of the Regional Governor or the Vice-Governor under this Section by a majority vote of all its Members.\nThe Regional Assembly shall promulgate the necessary rules to carry out effectively the purposes of this Section."}},{"id":"PH-H5231-A13_3","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor or the Vice-Governor may be recalled once during his term of office for loss of confidence.\nThe Regional Assembly shall provide the procedure and system whereby such recall can be made: Provided, That no recall shall take place within one year from the date of the official's assumption of office or one year immediately preceding a regional election."}},{"id":"PH-H5231-A14_2","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor, the Vice-Governor, and the Members of the Cabinet and their deputies shall not hold any other office or employment during their tenure. They shall not, during said tenure, directly or indirectly, practice any other profession, participate in any business, or be financially interested in any contract with, or in any franchise, or special privilege granted by the Government or any subdivision, agency, or instrumentality thereof, including government-owned or controlled corporations or their subsidiaries. They shall strictly avoid conflicts of interest in the conduct of their office.\nThe spouse and relatives by consanguinity or affinity within the fourth civil degree of the Governor shall not, during his tenure, be appointed members of the regional Cabinet or chairmen of regional commissions, or heads of bureaus or offices, including government-owned or controlled corporations and their subsidiaries located in the Autonomous Region."}},{"id":"PH-H5231-A15_2","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Appointments extended by the Acting Governor within ninety (90) days before the assumption of office by the elected Governor shall remain effective, unless revoked by the elected Governor within ninety (90) days from such assumption or resumption of office."}},{"id":"PH-H5231-A16_2","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall not issue appointments, remove personnel, or unless authorized by the Commission on Elections, undertake public works projects, within the prohibited period before and after a regional election as provided by law."}},{"id":"PH-H5231-A17_2","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall appoint, in addition to the members of the Cabinet, their deputies, the chairmen and members of the commissions and the heads of bureaus of the Regional Government, and those whom he may be authorized by regional law to appoint. The Regional Assembly may, by law, vest the appointment of other officers or officials lower in rank in the heads of departments, agencies, commissions, or boards."}},{"id":"PH-H5231-A18_2","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Subject to the exceptions provided for in this Organic Act, the Regional Governor shall have control of all the regional executive commissions, boards, bureaus and offices. He shall ensure that the laws be faithfully executed. The Regional Governor shall exercise general supervision over the local government units within the Autonomous Region: Provided, however, That nothing herein shall authorize the diminution of the powers and functions already enjoyed by local government units."}},{"id":"PH-H5231-A19_2","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"(1) The Regional Governor shall submit to the Regional Assembly not later than two (2) months before the beginning of every regular session, as the basis of the regional appropriations bill, a budget of expenditures and sources of financing, including receipts from existing and proposed revenue measures.\nThe fiscal year of the Autonomous Region shall cover the period April 1 to March 31 of the succeeding year.\n(2) The Regional Assembly may not increase the appropriations recommended by the Regional Governor for the operation of the Autonomous Government as specified in the budget. The form, content and manner of preparation of the budget shall be prescribed by regional law: Provided, however, That pending the enactment of such regional law, the budgeting process shall be governed by existing national laws and rules and regulations prescribed by the Department of Budget and Management.\n(3) No provision or enactment shall be embraced in the regional appropriations bill unless it relates specifically to some particular appropriation therein. Any such provision or enactment shall be limited in its operation to the appropriation to which it relates.\n(4) The procedure in approving appropriations for the Regional Assembly shall strictly follow the procedure for approving appropriations for other departments and agencies of the Regional Government.\n(5) A special appropriations bill shall specify the purpose for which it is intended, and shall be supported by funds actually available as certified by the Regional Treasurer, or to be raised by a corresponding revenue proposal therein.\n(6) No regional law shall be passed authorizing any transfer of appropriations; however, the Regional Governor may, by regional law, be authorized to augment any item for his office from savings in other items of the appropriations for his office.\n(7) Discretionary funds appropriated for particular officials shall be disbursed only for public purposes to be supported by appropriate vouchers and subject to such guidelines as may be prescribed by regional law."}},{"id":"PH-H5231-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"If, by the end of the fiscal year, the Regional Assembly shall have failed to pass the regional appropriations bill for ensuing fiscal year, the Regional Appropriations Act for the preceding fiscal year shall be deemed automatically reenacted and shall remain in force and effect until the regional appropriations bill is passed by the Regional Assembly."}},{"id":"PH-H5231-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall have the power to veto any particular item or items in an appropriation or revenue bill, but the veto shall not affect the item or items to which he does not object. The veto may be reconsidered by the Assembly by a vote of two-thirds (2/3) of all its Members."}},{"id":"PH-H5231-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"(1) No money shall be paid out of the Regional Treasury except in pursuance of an appropriation made by regional law.\n(2) No public money or property shall be appropriated, applied, paid or employed, directly or indirectly, for the use, benefit, or support of any sect, church, denomination, sectarian institution, or system of religion or of any priest, imam, preacher, minister, or other religious teacher or dignitary as such, except when such priest, imam, preacher, minister or dignitary is assigned to the regional police force or to any penal institution, or government orphanage or leprosarium within the Region.\n(3) All money collected on any regional tax levied for a special purpose shall be treated as a special fund and paid out for such special purpose only. If the purpose for which a special fund was created has been fulfilled or abandoned, the balance, if any, shall accrue to the general funds of the Regional Government.\n(4) No funds or resources shall be disbursed unless duly approved by the Regional Governor or by his duly authorized representative.\n(5) Trust funds shall only be paid out of the Regional Treasury upon fulfillment of the specific purpose for which said funds were created or received."}},{"id":"PH-H5231-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall inform the Regional Assembly every quarter on the conduct of regional affairs and the state of regional finances."}},{"id":"PH-H5231-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The financial accounts of the expenditures and revenues of the Autonomous Region shall be audited by the Commission on Audit.\nThe financial accounts of the Autonomous Region, including all payments from the reserve fund, shall be submitted by the Regional Governor to the Regional Assembly, together with the statement of audit prepared by the Commission on Audit within ten (10) working days from receipt thereof."}},{"id":"PH-H5231-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Regional Governor shall address the Regional Assembly at the opening of its regular session. He may also appear before it at any time. The Regional Assembly may invite the President and other government officials to address it.\nAdministration of Justice"}},{"id":"PH-H5231-A1_9","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Supreme Court, the Court of Appeals, and other courts established by law shall continue to exercise their judicial powers as provided by the Constitution and national laws."}},{"id":"PH-H5231-A2_9","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"There is hereby created a Shari'ah Appellate Court which, together with other Shari'ah and tribal courts, shall have jurisdiction over cases involving persons, family and property relations.\nThe Regional Assembly shall, in consultation with the Supreme Court, determine the number and the territorial jurisdiction of these courts.\nShari'ah Appellate Court"}},{"id":"PH-H5231-A3_5","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Shari'ah Appellate Court shall be composed of one (1) Presiding Justice and two (2) Associate Justices. Any vacancy shall be filled within ninety (90) days from the occurrence thereof."}},{"id":"PH-H5231-A4_4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"(1) The Justices of the Shari'ah Appellate Court shall possess the same qualification as those of the Justices of the Court of Appeals and, in addition, shall also be learned in Islamic law and jurisprudence.\n(2) The members of the Shari'ah Appellate Court shall be appointed by the President from a list of at least three (3) nominees prepared by the Judicial and Bar Council. The nominees shall be chosen from a list of recommendees submitted by the Regional Assembly. Such appointments need no confirmation."}},{"id":"PH-H5231-A5_4","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Shari'ah Appellate Court shall have the following powers:\n(1) Exercise original jurisdiction over petitions for certiorari, prohibition, mandamus, habeas corpus, and other auxiliary writs and processes in aid of its appellate jurisdiction; and\n(2) Exercise exclusive appellate jurisdiction over all cases tried in the Shari'ah District Courts as established by law."}},{"id":"PH-H5231-A6_4","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The decisions of the Shari'ah Appellate Court shall be final and executory: Provided, however, That nothing herein contained shall affect the original and appellate jurisdiction of the Supreme Court as provided in the Constitution."}},{"id":"PH-H5231-A7_4","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Presiding and Associate Justices of the Shari'ah Appellate Court shall serve until they reach the age of seventy (70) years, unless sooner removed for cause in the same manner as Justices of the Court of Appeals or become incapacitated to discharge the duties of their office."}},{"id":"PH-H5231-A8_4","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Presiding Justice and Associate Justices of the Shari'ah Appellate Court shall receive the same compensation and enjoy the same privileges as the Presiding Justice and Associate Justices of the Court of Appeals, respectively."}},{"id":"PH-H5231-A9_4","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"(1) The Supreme Court shall, upon recommendation of the Presiding Justice of the Shari'ah Appellate Court, appoint the court administrator and clerk of court of said Appellate Court. Such other personnel as may be necessary for the Shari'ah Appellate Court shall be appointed by the Presiding Justice of said court.\n(2) The pertinent provisions of existing law regarding the qualifications, appointment, compensation, functions, duties and other matters relative to the personnel of the Court of Appeals shall apply to those of the Shari'ah Appellate Court."}},{"id":"PH-H5231-A10_4","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Members of the Shari'ah Appellate Court and of other Shari'ah Appellate courts established by law shall not be designated to any agency performing quasi-judicial or administrative functions."}},{"id":"PH-H5231-A11_4","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The official seat of the Shari'ah Appellate Court shall, unless the Supreme Court decides otherwise, be in the seat of the Autonomous Government."}},{"id":"PH-H5231-A12_4","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Proceedings in the Shari'ah Appellate Court and in the Shari'ah lower courts as are established in the Autonomous Regional shall be governed by such special rules as the Supreme Court may promulgate.\nShari'ah Courts"}},{"id":"PH-H5231-A13_4","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Shari'ah District Courts and the Shari'ah Circuit Courts created under existing laws shall continue to function as provided therein. The judges of the Shari'ah courts shall have the same qualifications as the judges of the Regional Trial Courts, the Metropolitan Trial Courts or the Municipal Trial Courts as the case may be in. In addition, they must be learned in Islamic law and jurisprudence.\nTribal Courts"}},{"id":"PH-H5231-A14_3","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"There is hereby created a system of tribal courts, which may include a Tribal Appellate Court, for the indigenous cultural communities in the Autonomous Region. These courts shall determine, settle and decide controversies and enforce decisions involving personal, family and property rights in accordance with the tribal codes of these communities. The Regional Assembly shall define their composition and jurisdiction in accordance with this Act.\nJurisconsult in Islamic Law"}},{"id":"PH-H5231-A15_3","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Provisions to put into effect the organization of the Office of Jurisconsult in Islamic Laws as established under existing law and facilities for its proper functioning shall receive priority consideration.\nCustomary Law"}},{"id":"PH-H5231-A16_3","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Regional Assembly shall provide for the codification of indigenous laws and compilation of customary laws in the Autonomous Region.\nApplication and Interpretation of Laws"}},{"id":"PH-H5231-A17_3","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"(1) The provisions of the Muslim Code and the Tribal Code shall be applicable only to Muslims and other members of indigenous cultural communities respectively and nothing herein shall be construed to operate to the prejudice of non-Muslims and nonmembers of indigenous cultural communities.\n(2) In case of conflict between the Muslim Code and the Tribal Code, the national law shall apply.\n(3) In case of conflict between the Muslim Code or the Tribal Code on the one hand, and the national law on the other, the latter shall prevail.\n(4) Except in cases of successional rights, the regular courts shall acquire jurisdiction over controversies involving real property located outside the area of autonomy."}},{"id":"PH-H5231-A18_3","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Subject to the provisions of the Constitution, the Shari'ah courts shall interpret Islamic law based on sources such as:\n(1) Al-Qur'an (The Koran);\n(2) Al-Sunnah (Prophetic traditions);\n(3) Al-Qiyas (Analogy); and\n(4) Al-Jima (Consensus).\nFiscal Autonomy"}},{"id":"PH-H5231-A1_10","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The Autonomous Region shall have the power to create its own sources of revenues and to levy taxes, fees and charges, subject to such guidelines and limitations as the Constitution and this Organic Act may provide, consistent with the basic policy of local autonomy."}},{"id":"PH-H5231-A2_10","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE X"},"text":{"en":"In enacting revenue-raising measures, the Regional Assembly shall observe the principle of uniformity and equity in taxation and shall not impose confiscatory taxes and fees of any kind. Income taxation, however, shall be solely the concern and prerogative of the National Government.\nThe Regional Assembly shall not revoke or amend, directly or indirectly, any city or municipal ordinances imposing taxes or fees on purely local businesses.\nNo tax, impost or assessment shall be imposed or charged upon goods or merchandise coming into, going out of, or passing through the Autonomous Region to other places of the Philippines, and vice versa."}},{"id":"PH-H5231-A3_6","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE X"},"text":{"en":"All corporations, partnerships, and other business entities directly engaged in business in the Autonomous Region shall pay through the Regional Government that portion of their annual income tax corresponding to the net income generated from business done in the area of autonomy.\nAll corporations, partnerships or business entities directly engaged in business in the Autonomous Region shall pay their corresponding taxes, fees, and charges in the province, city, or municipality where the establishment is doing business."}},{"id":"PH-H5231-A4_5","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The sources of revenues of the Autonomous Region shall include, but are not limited to, the following:\n(1) Taxes, except income taxes, imposed by the Regional Government;\n(2) Fees and charges imposed by the Regional Government;\n(3) Appropriations, internal revenue allotments and other budgetary allotments from the National Government;\n(4) Shares in revenues generated from the operations of public utilities within the Autonomous Region; and\n(5) Block grants derived from economic agreements or conventions authorized by the Autonomous Region, donations, endowments, foreign assistance, and other forms of aid, subject to the Constitution and national policies."}},{"id":"PH-H5231-A5_5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The total collections of a province or city from national internal revenue taxes, fees and charges, and taxes imposed on natural resources, shall be distributed as follows:\n(a) Thirty percent (30%) to the province or city;\n(b) Thirty percent (30%) to the Regional Government; and\n(c) Forty percent (40%) to the National Government.\nThe thirty percent (30%) share of the province shall be distributed equally as follows: ten percent (10%) to the province, ten percent (10%) to the municipality and ten percent (10%) to the barangay.\nThe thirty percent (30%) share of the city shall be distributed as follows: twenty percent (20%) to the city and ten percent (10%) to the barangay.\nThe province or city concerned shall automatically retain its share and remit the seventy percent (70%) to the Regional Government, which shall, after deducting its share, remit the balance to the National Government on a monthly basis.\nThe remittance procedure within the Autonomous Region shall be in accordance with the rules and regulations promulgated by the Regional Government, and remittances to the National Government by the rules and regulations promulgated by the Department of Finance."}},{"id":"PH-H5231-A6_5","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Subject to the Constitution and national policies, the Regional Government shall evolve a system of economic agreements and trade compacts to generate block grants for regional investments and improvements of regional economic structures. These economic agreements shall be authorized by regional legislation or by executive agreement. Pursuant to specific recommendations from the Regional Planning and Development Board, the Regional Government shall assist local government units in their requirements for counterpart funds for foreign assisted projects."}},{"id":"PH-H5231-A7_5","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Donations or grants to the Regional Government exclusively to finance, to provide, for, or to be used in undertaking projects in education, health, youth and culture, and in economic development, shall be deductible in full in determining the taxable income of the donor or grantor."}},{"id":"PH-H5231-A8_5","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The Regional Assembly may grant exemptions from regional taxes, only with the concurrence of a majority of all the Members of the Assembly."}},{"id":"PH-H5231-A9_5","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Foreign loans may be contracted only in accordance with the provisions of the Constitution and national laws: Provided, That the Regional Governor may contract domestic loans subject to the approval by the Regional Assembly.\nAncestral Domain, Ancestral Lands and Agrarian Reform"}},{"id":"PH-H5231-A1_11","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Subject to the Constitution and national policies, the Regional Government shall undertake measures to protect the ancestral domain and the ancestral lands of indigenous cultural communities.\nAll lands and natural resources in the Autonomous Region that have been possessed or occupied by indigenous cultural communities since time immemorial, except when prevented by war, force majeure, or other forms of forcible usurpation, shall form part of the ancestral domain. Such ancestral domain shall include pasture lands, worship areas, burial grounds, forests and fields, mineral resources, except: strategic minerals such as uranium, coal, petroleum, and other fossil fuels, mineral oils, and all sources of potential energy; lakes, rivers and lagoons; and national reserves and marine parks, as well as forest and watershed reservations.\nLands in the actual, open, notorious, and uninterrupted possession and occupation by an indigenous cultural community for at least thirty (30) years are ancestral lands."}},{"id":"PH-H5231-A2_11","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"The constructive or traditional possession of lands and resources by an indigenous cultural community may also be recognized subject to judicial affirmation, the petition for which shall be instituted within a period of ten (10) years from the effectivity of this Act. The procedure for judicial affirmation of imperfect titles under existing laws shall, as far as practicable, apply to the judicial affirmation of titles to ancestral lands.\nThe foregoing provisions notwithstanding, titles secured under the Torrens system, and rights already vested under the provisions of existing laws shall be respected."}},{"id":"PH-H5231-A3_7","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"As used in this Act, the phrase \"indigenous cultural community\" refers to Filipino citizens residing in the Autonomous Region who are:\n(1) Tribal peoples whose social, cultural and economic conditions distinguish them from other sectors of the national community and whose status is regulated wholly or partially by their own customs or traditions or by special laws or regulations; and\n(2) Bangsa Moro people regarded as indigenous on account of their descent from the populations that inhabited the country or a distinct geographical area at the time of conquest or colonization and who, irrespective of their legal status, retain some or all of their own socioeconomic, cultural and political institutions."}},{"id":"PH-H5231-A4_6","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"The customary laws, traditions, and practices of indigenous cultural communities on land claims and ownership and settlement of land disputes shall be implemented and enforced among the members of such community."}},{"id":"PH-H5231-A5_6","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"The Regional Government shall require corporations, companies and other entities within the ancestral domain of the indigenous cultural communities whose operations adversely affect the ecological balance to take the necessary preventive measures and safeguards in order to maintain such a balance."}},{"id":"PH-H5231-A6_6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Unless authorized by the Regional Assembly, lands of the ancestral domain titled to or owned by an indigenous cultural community shall not be disposed of to nonmembers."}},{"id":"PH-H5231-A7_6","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"No portion of the ancestral domain shall be open to resettlement by nonmembers of the indigenous cultural communities."}},{"id":"PH-H5231-A8_6","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Subject to the Constitution and national policies, the Regional Assembly shall enact an Agrarian Reform Law suitable to the special circumstances prevailing in the Autonomous Region.\nUrban and Rural Planning and Development"}},{"id":"PH-H5231-A1_12","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"The Regional Government shall promote and formulate comprehensive and integrated regional urban and rural development policies, plans, programs and projects responsive to the needs, aspirations and values of the people within the Region."}},{"id":"PH-H5231-A2_12","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Immediately after its organization, the Regional Government shall initiate, formulate and implement special development programs and projects, responsive to the particular aspirations, needs and values of the indigenous cultural communities."}},{"id":"PH-H5231-A3_8","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"The Regional Government shall provide equitable opportunities for the development of every province, city, municipality and barangay within its jurisdiction and shall strengthen their existing planning bodies to ensure wider public participation."}},{"id":"PH-H5231-A4_7","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Consistent with the Constitution and national policies, and subject to ecological considerations, the Regional Government shall adopt and implement a comprehensive urban land reform and land use program, to ensure the just utilization of lands within its jurisdiction."}},{"id":"PH-H5231-A5_7","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"There is hereby created a Regional Planning and Development Board which shall be composed of all the provincial governors and city mayors, two (2) members of the Regional Assembly to be designated by the Speaker, and such other members as may be prescribed by the Regional Assembly: Provided, That the private sector shall be represented therein.\nThe Board shall serve as the planning, monitoring and coordinating agency for the Autonomous Region. It shall identify, evaluate, and recommend the annual work programs and comprehensive development plans of the Autonomous Region to the Regional Assembly, to ensure their proper implementation.\nThe Board shall formulate a Magna Carta for the Development of the Region to serve as the master plan for a systematic, progressive and total development of the Region.\nEconomy and Patrimony"}},{"id":"PH-H5231-A1_13","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Consistent with the Constitution and national policies, the Regional Government may enact regional laws pertaining to the national economy and patrimony applicable and responsive to the needs of the Region. However, nothing herein shall be construed as to authorize the Regional Government to require lesser standards respecting the protection, conservation and enhancement of the natural resources than those required by the National Government."}},{"id":"PH-H5231-A2_13","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Except for strategic minerals such as uranium, coal, petroleum, and other fossil fuels, mineral oils, all sources of potential energy, as well as national reserves and aquatic parks, forest and watershed reservations as may be delimited by national law, the control and supervision over the exploration, utilization and development of the natural resources of the Autonomous Region is hereby delegated to the Regional Government in accordance with the Constitution and national laws.\nThe Regional Assembly shall have the authority to grant franchises and concessions but the Regional Governor may, by regional law, be authorized to grant leases, permits and licenses: Provided, That, any lease, permit, franchise or concession shall cover an area not exceeding the limits allowed by the Constitution and shall subsist for a period not exceeding twenty-five (25) years; Provided, further, That existing leases, permits, licenses, franchises and concessions shall be respected until their expiration unless legally terminated as provided by law; and Provided, finally, That when the natural resources are located within the ancestral domain, the permit, license, franchise or concession, shall be approved by the Regional Assembly after consultation with the cultural community concerned."}},{"id":"PH-H5231-A3_9","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The exploration, development and utilization of natural resources, except those enumerated in the first paragraph of Section 2 hereof, shall be allowed to all Filipinos and to private enterprises, including corporations, associations, cooperatives, and such other similar collective organizations with at least sixty percent (60%) of their capital investment or capital stocks directly controlled or owned by Filipinos who are preferably residents of the Region."}},{"id":"PH-H5231-A4_8","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Small-scale mining shall receive support from and be regulated by the Regional Government, considering ecological balance, the safety and health and the interest of the communities and the miners where such operations are conducted."}},{"id":"PH-H5231-A5_8","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government may, in the interest of regional welfare and security, establish and operate pioneering utilities. Upon payment of just compensation, it may transfer the ownership of such utilities to cooperatives or other collective organizations."}},{"id":"PH-H5231-A6_7","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government may, in times of regional emergency declared by the President, when the public interest so requires and under reasonable terms and safeguards prescribed by the Regional Assembly, temporarily take over or direct the operation of any privately-owned public utility or business affected with public interest."}},{"id":"PH-H5231-A7_7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Assembly shall enact laws for the just compensation, rehabilitation, relocation, and other similar measures of inhabitants adversely affected in the harnessing of natural and mineral resources in the Region.\nThe Regional Assembly shall likewise provide for the rehabilitation of the areas affected by said harnessing of natural and mineral resources in the Region."}},{"id":"PH-H5231-A8_7","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall actively and immediately pursue reforestation measures to ensure that at least fifty (50%) of the land surface of the Autonomous Region shall be covered with trees, giving priority to land strips along eighteen percent (18%) in slope or over by providing infrastructure, financial and technical support to upland communities especially the Lumads or tribal peoples."}},{"id":"PH-H5231-A9_6","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall prohibit the use, importation, deposit, disposal and dumping of toxic or hazardous substances within the Autonomous Region."}},{"id":"PH-H5231-A10_5","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall adopt policies to promote profit sharing and broaden the base of ownership of business enterprises."}},{"id":"PH-H5231-A11_5","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall provide incentives, including tax holidays, for investors in businesses that will contribute to the development of the Region.\nIt shall provide the same incentives to all companies doing business in the Region which reinvest at least fifty percent (50%) of their net profits therein, and to all cooperatives which reinvest at least ten percent (10%) of their surplus into socially-oriented projects in the Region."}},{"id":"PH-H5231-A12_5","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall give priority to the establishment of transportation and communication facilities for the economic development of the region."}},{"id":"PH-H5231-A13_5","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"In the delivery of power services, priority shall be given to provinces in the area of autonomy which do not have direct access to such services."}},{"id":"PH-H5231-A14_4","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government is hereby empowered to create pioneering firms and other business entities needed to boost economic development in the Region.\nAgriculture, Fisheries and Aquatic Resources"}},{"id":"PH-H5231-A15_4","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall recognize, promote and protect the rights and welfare of farmers, farmworkers, fishermen and fishworkers, as well as farmers, and fishworkers' cooperatives and associations."}},{"id":"PH-H5231-A16_4","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall encourage agricultural productivity and promote a diversified and organic farming system."}},{"id":"PH-H5231-A17_4","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall give top priority to the conservation, protection, utilization and development of soil and water resources for agricultural purposes."}},{"id":"PH-H5231-A18_4","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Assembly shall enact on Aquatic and Fisheries Code which shall enhance, develop, conserve and protect marine and aquatic resources, and shall protect the rights of subsistence fishermen to the preferential use of communal marine and fishing resources, including seaweeds. This protection shall extend to offshore fishing grounds, up to and including all waters twelve (12) nautical miles from the coastline of the Autonomous Region but within the territorial waters of the Philippines, regardless of depth, the seabed and the subsoil that are included between two (2) lines drawn perpendicular to the general coastline from points where the boundary lines of the Autonomous Region touch the sea at low tide and a third line parallel to the general coastline.\nFurther, it shall provide support to subsistence fishermen through appropriate technology and research, adequate financial, production and marketing assistance and other services.\nFishworkers shall also receive a just share from their labor in the utilization of marine and fishing resources.\nScience, technology and other disciplines shall be developed and employed to protect and maintain aquatic and marine ecology."}},{"id":"PH-H5231-A19_3","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Assembly may, by law, create a Bureau of Agriculture and Fisheries and define its composition, powers and functions.\nTrade and Industry"}},{"id":"PH-H5231-A20_2","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government recognizes the private sector as the prime mover of trade, commerce and industry. It shall encourage and support entrepreneurial capability in the Region and shall recognize, promote and protect cooperatives."}},{"id":"PH-H5231-A21_2","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall promote and protect small and medium-scale cottage industries by providing assistance such as marketing opportunities, financial support, tax incentives, appropriate and alternative technology and technical training to produce semi-finished and finished products."}},{"id":"PH-H5231-A22_2","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall give support and encouragement to the establishment of banks in accordance with the principles of the Islamic banking system, subject to the supervision by the central monetary authority of the National Government."}},{"id":"PH-H5231-A23_2","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Subject to national policies, the Regional Government shall regulate traditional barter trade and countertrade with neighboring countries."}},{"id":"PH-H5231-A24_2","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall encourage, promote, undertake and support the establishment of economic zones, industrial centers and ports in strategic areas and growth centers of the Region to attract local and foreign investments and business enterprises. casia"}},{"id":"PH-H5231-A25_2","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall undertake measures to promote consumer education and to ensure that the rights, interests and welfare of the consumers are protected."}},{"id":"PH-H5231-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall promote the preferential use of labor and locally produced goods and materials by adopting measures to increase their competitiveness."}},{"id":"PH-H5231-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Subject to the Constitution and national policies, the Regional Government shall regulate and exercise authority over foreign investments within its jurisdiction in accordance with its goals and priorities.\nTourism Development"}},{"id":"PH-H5231-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Government shall, with the assistance of the National Government and the participation of the private sector, develop tourism as a positive instrument toward accelerated regional development. Tourism development shall promote greater pride in and commitment to the nation: Provided, That the diverse cultural heritage, and moral and spiritual values of the people in the Autonomous Region shall be primarily considered and respected."}},{"id":"PH-H5231-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"The Regional Assembly may, by law, create a Tourism office, and shall define its composition, powers and functions.\nPublic Order and Security"}},{"id":"PH-H5231-A1_14","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The Regional Government shall give priority to the maintenance and preservation of peace and order and the protection of life, liberty and property in the Autonomous Region, in consonance with the provisions of the Constitution."}},{"id":"PH-H5231-A2_14","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The Regional Assembly shall, by law, create a Regional Police Force as an integral part of the Philippine National Police under the administration and control of the National Police Commission. It shall be headed by a police commissioner with two deputies, who shall all be inhabitants of the Autonomous Region, to be appointed by the President of the Philippines upon recommendation of the Regional Governor."}},{"id":"PH-H5231-A3_10","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The regional police shall be under the supervision of the Regional Governor: Provided, That city or municipal mayors, who are hereby constituted as representatives of the National Police Commission, shall have operational control and supervision of the police force within their constituent units in accordance with law and appropriate rules and regulations."}},{"id":"PH-H5231-A4_9","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The defense and security of the Autonomous Region shall be the responsibility of the National Government. Towards this end, there is hereby created a regional command of the Armed Forces of the Philippines for the Autonomous Region, which shall be organized, maintained and utilized in accordance with national laws. The National Government shall have the authority to station and deploy in the Autonomous Region sufficient elements of the Armed Forces of the Philippines: Provided, That inhabitants of the Autonomous Region shall be given preference in assignments therein."}},{"id":"PH-H5231-A5_9","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The provisions of the preceding sections notwithstanding, the Regional Governor may request the President of the Philippines to call upon the Armed Forces of the Philippines:\n(1) To prevent or suppress lawless violence, invasion or rebellion, when the public safety so requires, in accordance with the provisions of the Constitution;\n(2) To suppress the danger to or breach of peace in the area of autonomy, when the police forces of the autonomous Region are not able to do so; or\n(3) To avert any imminent danger to public order and security in the area of autonomy."}},{"id":"PH-H5231-A6_8","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The Regional Government shall recognize indigenous structures or systems which promote peace and order.\nEducation, Science and Technology, Arts and Sports"}},{"id":"PH-H5231-A1_15","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The Autonomous Region shall establish, maintain and support a complete and integrated system of quality education and adopt an educational framework that is meaningful, relevant and responsive to the needs, ideals and aspirations of the people in the Region.\nEducational Policies"}},{"id":"PH-H5231-A2_15","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Consistent with the basic State policy on education, the Autonomous Region shall adopt the following educational policies and principles:\n(1) Education in the Autonomous Region shall be committed to the total spiritual, intellectual, social, cultural, scientific and physical development of man, thus making him a God-fearing, peace-loving, and work-oriented citizen of the nation;\n(2) All schools in the Autonomous Region shall inculcate patriotism and nationalism, appreciation of the role of national and regional heroes in the historical development of the country and region, foster love of humanity, respect for human rights, and shall teach the rights and duties of citizenship, and the cultures of the Muslims, Christians, and tribal peoples in the Region to develop, promote and enhance unity in diversity;\n(3) The thrust, programs and administration of vocational, non-formal and special education shall be supported and made relevant to the manpower needs of the Region;\n(4) A system of scholarship programs, grants, student loans, subsidies and other incentives shall be made available to all poor but deserving students;\n(5) The active participation of the home, community, religious organizations and other sectors in the total educative process of the child shall be encouraged and supported;\n(6) (a) A regional language may be evolved and developed from the different dialects in the Region.\n(b) Filipino and English shall be the media of instruction in all schools in the Region. Major languages of the Region shall be auxiliary media of instruction.\n(c) The Arabic language shall be a compulsory subject for Muslims and optional for non-Muslims in all schools in the Region;\n(7) The education in the Autonomous Region shall develop consciousness and appreciation of one's ethnic identity and shall provide a better understanding of each other's cultural heritage for the attainment of national unity and harmony;\n(8) The Regional Government shall recognize the participation of private institutions of learning, including the Madaris (Arabic schools), in providing quality education to the people of the Region; and\n(9) Unless otherwise provided by regional law, the Regional Government may implement a four-year primary and a three-year intermediate education; a 2-2 secondary education; and a four-year or more college education in schools within the Region."}},{"id":"PH-H5231-A3_11","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The regional educational system shall develop curricula that are relevant to the economic, social, political, cultural, moral and spiritual needs of the people in the Region.\nEducational Structure"}},{"id":"PH-H5231-A4_10","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The Regional Assembly may, by law, create, support and maintain a Department of Education, Culture and Sports, and shall define its powers, functions and composition."}},{"id":"PH-H5231-A5_10","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"State colleges and universities within the Autonomous Region shall enjoy academic freedom and fiscal autonomy and shall continue to be governed by their respective charters: Provided, That the regional secretary of Education, Culture and Sports shall be a member of the governing boards of state colleges and universities in the Autonomous Region."}},{"id":"PH-H5231-A6_9","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"All state colleges and universities in the Autonomous Region shall assist and support the full development of the people and shall serve as regional centers for tertiary and post graduate education in their respective areas of competence."}},{"id":"PH-H5231-A7_8","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The Regional Assembly may establish a tribal state university system within the Autonomous Region.\nMadrasah Education"}},{"id":"PH-H5231-A8_8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Accredited madaris in the Autonomous Region shall be supervised by the Department of Education, Culture and Sports."}},{"id":"PH-H5231-A9_7","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Appropriate regional laws shall be enacted for the strengthening and development of the madrasah educational system in the Autonomous Region.\nScience and Technology"}},{"id":"PH-H5231-A10_6","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Science and technology are recognized as essential to national and regional progress and development."}},{"id":"PH-H5231-A11_6","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The Regional Assembly shall enact laws that shall:\n(1) Give priority to science, research, inventions, technology, education, and their development and utilization;\n(2) Provide incentives, including tax deductions and funding assistance, and encourage private participation in basic and applied scientific researches;\n(3) Regulate the transfer and promote the adoption of technology from all sources for regional benefit;\n(4) Secure and protect the exclusive rights of scientists, inventors, scholars, writers, artists and other gifted citizens to their intellectual properties; and\n(5) Introduce the full and effective participation of all sectors in the planning, programming, coordination and implementation of scientific and technological researches and the acquisition, adoption, innovation and application of science and technology for development.\nPhysical Education and Sports Development"}},{"id":"PH-H5231-A12_6","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The educational system shall develop and maintain an integrated and comprehensive physical education program. It shall develop healthy, disciplined, creative, innovative, productive individuals, and promote the spirit of sportsmanship, cooperation, teamwork, goodwill and understanding."}},{"id":"PH-H5231-A13_6","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The system shall encourage and support sports programs, league competitions, indigenous games, martial arts and amateur sports, including training for regional, national and international competitions.\nCultural Heritage"}},{"id":"PH-H5231-A14_5","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The cultural heritage of the people of the Autonomous Region shall be an integral component of regional development."}},{"id":"PH-H5231-A15_5","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"The Regional Government shall recognize, respect, protect, preserve, revive, develop, promote and enhance the culture, customs, traditions, beliefs and practices of the people in the area of autonomy. It shall encourage and undertake the recovery, collection, collation and restoration of historical and cultural properties for posterity."}},{"id":"PH-H5231-A16_5","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"A Bureau on Cultural Heritage may be created to plan, initiate, implement and monitor cultural programs, projects and activities that shall institutionalize the preservation and enhancement of the positive elements of the indigenous culture of the inhabitants of the Autonomous Region. It shall coordinate with other concerned agencies engaged in similar and related activities.\nSocial Justice, Services, Institutions, and Other Concerns"}},{"id":"PH-H5231-A1_16","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The promotion of social justice shall include the commitment to create social, political and economic opportunities based on freedom of initiative, resourcefulness and self-reliance."}},{"id":"PH-H5231-A2_16","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"(1) The Regional Assembly shall, consistent with the provisions of the Constitution and national policies, enact measures to provide and expand health and welfare services.\n(2) The Regional Government shall establish and maintain an effective food and drug regulatory system. It shall encourage the rational use of drugs through an essential drugs list and the use of generic medicines or drugs, as well as promote the use of herbal medicines and indigenous health resources whenever appropriate.\n(3) The Regional Assembly shall enact further legislation on the following:\n(a) Child health and development, including the support of the handicapped and other disadvantaged persons in need of welfare services;\n(b) Condition of women and status of indigenous population;\n(c) Registration of births, marriages and deaths; and\n(d) Fixing of regional public holidays."}},{"id":"PH-H5231-A3_12","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Government, in cooperation with the private sector, shall evolve its own housing program that will provide adequate, low-cost, and decent housing facilities and other basic services to the residents of the Region, especially the underprivileged."}},{"id":"PH-H5231-A4_11","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Assembly shall within one (1) year from its organization enact measures embodying reintegration programs responsive to the needs of returnees and rejoinees. A rehabilitation program shall be provided for displaced persons or communities and victims of manmade or natural calamities."}},{"id":"PH-H5231-A5_11","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Government recognizes the Filipino family as the foundation of the nation. It shall strengthen its solidarity and actively promote its total development."}},{"id":"PH-H5231-A6_10","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Government recognizes the role of women in nation-building and regional development. It shall promote their well-being and ensure their fundamental rights and equality with men before the law.\nThe Regional Government shall take appropriate measures against all forms of exploitation of and discrimination against women.\nIt shall ensure the representation of women in appropriate decision and policy-making bodies."}},{"id":"PH-H5231-A7_9","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Government recognizes the vital role of the youth in nation-building.\nThe Regional Assembly may, by law, create the Office of Youth Affairs and define its powers, functions and composition."}},{"id":"PH-H5231-A8_9","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Government shall protect the rights of people's organizations."}},{"id":"PH-H5231-A9_8","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Government recognizes labor as a primary social economic force for development. It shall afford full protection to labor, promote full employment, ensure equal work opportunities regardless of sex, race or creed, and regulate the relations between workers and employers.\nThe Regional Government shall ensure the right of labor to its just share in the fruits of production, and the right of enterprise to reasonable returns on investments and to expansion and growth."}},{"id":"PH-H5231-A10_7","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"The Regional Assembly may create a Commission on Human Rights, and define its powers and functions, subject to the Constitution, national laws, and to the supervision of the National Commission on Human Rights.\nGeneral Provisions"}},{"id":"PH-H5231-A1_17","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"The Regional Assembly is hereby empowered to pass a law adopting an official regional emblem, seal and hymn."}},{"id":"PH-H5231-A2_17","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"All public officers and employees, as well as members of the regional police force and the military establishment, shall be required to take an oath of allegiance to the Republic of the Philippines and to support and defend the Constitution and this Organic Act."}},{"id":"PH-H5231-A3_13","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"No member of the Armed Forces of the Philippines in the active service shall, at any time, be appointed or designated in any capacity to a civilian position in the Autonomous Government, including government-owned or controlled corporations, or in any of their subsidiaries or instrumentalities within the Autonomous Region."}},{"id":"PH-H5231-A4_12","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"This Organic Act shall be officially promulgated in Filipino, English and Arabic and translated into the dialects widely spoken in the Autonomous Region. In case of conflict, the English text shall prevail.\nAmendments or Revisions"}},{"id":"PH-H5231-A1_18","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XVIII"},"text":{"en":"Consistent with the provisions of the Constitution, this Organic Act may be amended or revised by the Congress of the Philippines upon a majority vote of the House of Representatives and of the Senate voting separately."}},{"id":"PH-H5231-A2_18","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XVIII"},"text":{"en":"The Regional Assembly shall have the power to initiate proposals for amendment to or revisions of this Organic Act by a vote of three-fourths (3/4) of all its Members or it may call for a Regional Consultative Commission to propose the amendment or revision. In any case, the amendment or revision shall require the approval of the Congress of the Philippines."}},{"id":"PH-H5231-A3_14","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XVIII"},"text":{"en":"Any amendment to or revision of this Organic Act shall become effective only when approved by a majority of the votes cast in a plebiscite called for the purpose, which shall be held not earlier than sixty (60) days or later than ninety (90) days after the approval of such amendment or revision.\nTransitory Provisions"}},{"id":"PH-H5231-A1_19","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"(1) The existing Sangguniang Pampook and the Lupong Tagapagpaganap ng Pook of Regions IX and XII shall be deemed abolished and the Members thereof considered as having ceased in office upon the election and qualification of their successors as provided in this Act.\n(2) All regular and permanent personnel of the Sangguniang Pampook and Lupong Tagapagpaganap ng Pook of Regions IX and XII shall continue to hold office unless they are replaced by the Regional Government within six (6) months from the organization thereof; otherwise, they shall be considered regular and permanent employees of the Regional Government.\nNothing in this Organic Act, however, shall derogate from any right or privilege enjoyed by any public official or employee under existing laws. Retiring employees shall be given full benefits under existing laws. Those who opt to transfer to another region shall be allowed, subject to the Civil Service laws and regulations.\n(3) Properties and assets of the present Autonomous Governments in Regions IX and XII shall be turned over to the Regional Government. Those lands, buildings and other permanent structures located in the provinces or cities that do not vote favorably in the plebiscite for the ratification of this Organic Act may be acquired by the province or city concerned for value."}},{"id":"PH-H5231-A2_19","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"All personnel of the National Government and of government-owned or controlled corporations who are absorbed by the Regional Government shall retain their seniority rights, compensation and the benefits."}},{"id":"PH-H5231-A3_15","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"Within one (1) month from the organization of the Regional Government an Oversight Committee composed of the Executive Secretary as Chairman, the Secretary of Budget and Management, the Secretary-General of the National Economic and Development Authority, the Regional Governor of the Autonomous Region, the Speaker of the Regional Assembly, two (2) Senators to be designated by the Senate President and two (2) Representatives to be designated by the Speaker of the House of Representatives, as Members, shall be organized for the purpose of supervising the transfer to the Autonomous Region of such powers and functions vested in it by this Organic Act and the appropriations of the offices or agencies, including the transfer of properties, assets and liabilities, and such personnel as may be necessary, and of identifying the other line agencies and government-owned or controlled corporations that may be absorbed by the Regional Government and, with respect to the latter, also the terms and conditions of their turnover.\nWithin six (6) months after its organization, the Oversight Committee shall submit its report and recommendations to the President of the Philippines who shall act on the report and recommendations within ninety (90) days after receipt thereof: Provided, however, That if the President fails to act within said period, the recommendations of the Oversight Committee shall be deemed approved."}},{"id":"PH-H5231-A4_13","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"Upon the organization of the Autonomous Region, the line agencies and offices of the National Government dealing with local government, social services, science and technology, labor, natural resources, and tourism, including their personnel, equipment, properties and budgets, shall be immediately placed under the control and supervision of the Regional Government.\nOther National Government offices and agencies in the Autonomous Region which are not excluded under paragraph (9), Sec. 2, Article V of this Organic Act, together with their personnel, equipment, properties and budgets, shall be placed under the control and supervision of the Regional government pursuant to a schedule prescribed by the Oversight Committee mentioned in Section 3, Article XIX of this Organic Act: Provided, however, That the transfer of these offices and agencies and their personnel, equipment, properties and budget shall be accomplished within six (6) years from the organization of the Regional Government.\nThe National Government shall continue such levels of expenditures as may be necessary to carry out the functions devolved under this Act: Provided, however, That the annual budgetary support shall, as soon as practicable, terminate as to the line agencies or offices devolved to the Regional Government."}},{"id":"PH-H5231-A5_12","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"Notwithstanding the provisions of the preceding Section, the Government Service Insurance System, the Social Security System, the Pagtutulungan-Ikaw, Bangko, Industriya't Gobyerno (PAG-IBIG) and other funds of similar trust or fiduciary nature shall be exempt from the coverage of this Organic Act."}},{"id":"PH-H5231-A6_11","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"Pending the enactment of a regional budgetary law, the budgeting process of the Regional Government shall be governed by pertinent rules and regulations prescribed by the Department of Budget and Management."}},{"id":"PH-H5231-A7_10","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"The first regular elections of the Regional Governor, Vice-Governor and Members of the Regional Assembly under this Organic Act shall be held not earlier than sixty (60) days or later than ninety (90) days after the ratification of this Act. The Commission on Elections shall promulgate such rules and regulations as may be necessary for the conduct of said election."}},{"id":"PH-H5231-A8_10","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"Within one (1) year from its organization, the Regional Assembly shall, by law, create a Code Commission on Muslim Laws and a Code Commission on Tribal Laws which shall not exceed three (3) members per commission, and shall define their powers and functions.\nThe Code Commissions shall codify tribal laws and Islamic laws and jurisprudence within three (3) years from their creation and submit the same to the Regional Assembly for enactment into law."}},{"id":"PH-H5231-A9_9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"The sum of Fifteen million pesos (P15,000,000.00) which shall be charged against the Contingent Fund, is hereby appropriated for the initial organizational requirements of the Regional Government, and funding for any deficiency shall be taken from savings of the National Government: Provided, That Five million pesos (P5,000,000.00) thereof shall be allotted to the Commission on Elections to undertake an information campaign on this Organic Act: Provided, further, That the Commission on Elections shall determine the manner of campaigning and the deputization of government agencies for the purpose: Provided, finally, That the Commission on Elections shall adopt measures that will ensure an impartial information campaign."}},{"id":"PH-H5231-A10_8","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"The National Government shall, in addition to its regular annual allotment to the Autonomous Region, provide the Regional Government Two billion pesos (P2,000,000,000.00) as annual assistance for five (5) years, to fund infrastructure projects duly identified, endorsed and approved by the Regional Planning and Development Board herein created: Provided, however, That the annual assistance herein mentioned shall be appropriated and disbursed through a Public Works Act duly enacted by the Regional Assembly: Provided, further, that this annual assistance may be adjusted proportionately in accordance with the number of provinces and cities joining the Autonomous Region: and Provided, finally, That the national programs and projects in the Autonomous Region shall continue to be financed out of national funds."}},{"id":"PH-H5231-A11_7","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"The provisions of this Organic Act are hereby declared to be separate and in the event one or more of such provisions are held unconstitutional, the validity of other provisions shall not be affected thereby."}},{"id":"PH-H5231-A12_7","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"All laws, decrees, orders, rules and regulations, and all other issuances, or parts thereof, which are inconsistent with this Organic Act are hereby repealed or modified accordingly."}},{"id":"PH-H5231-A13_7","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"The creation of the Autonomous Region in Muslim Mindanao shall take effect when approved by a majority of the votes cast by the constituent units provided in paragraph (2) of Sec. 1 of Article II of this Act in a plebiscite which shall be held not earlier than ninety (90) days or later than one hundred twenty (120) days after the approval of this Act: Provided, That only the provinces and cities voting favorably in such plebiscite shall be included in the Autonomous Region in Muslim Mindanao. The provinces and cities which in the plebiscite do not vote for inclusion in the Autonomous Region shall remain in the existing administrative regions: Provided, however, That the President may, by administrative determination, merge the existing regions."}},{"id":"PH-H5231-A14_6","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"This Act shall take effect after fifteen (15) days following its complete publication in at least two (2) national local newspapers and one (1) newspaper of general circulation in the Autonomous Region."}}],"pack":"ph-p74"};
  FT["PH-H5232"] = {"id":"PH-H5232","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6735_1989.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":null,"en":"The Initiative and Referendum Act","orig":"The Initiative and Referendum Act An Act Providing for a System of Initiative and Referendum and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6735","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-04","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6735_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5232-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. — This Act shall be known as \" The Initiative and Referendum Act. \""}},{"id":"PH-H5232-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of Policy. — The power of the people under a system of initiative and referendum to directly propose, enact, approve or reject, in whole or in part, the Constitution, laws, ordinances, or resolutions passed by any legislative body upon compliance with the requirements of this Act is hereby affirmed, recognized and guaranteed."}},{"id":"PH-H5232-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. — For purposes of this Act, the following terms shall mean:\n(a) \"Initiative\" is the power of the people to propose amendments to the Constitution or to propose and enact legislations through an election called for the purpose.\nThere are three (3) systems of initiative, namely: a.1 Initiative on the Constitution which refers to a petition proposing amendments to the Constitution; a.2. Initiative on statutes which refers to a petition proposing to enact a national legislation; and a.3. Initiative on local legislation which refers to a petition proposing to enact a regional, provincial, city, municipal, or barangay law, resolution or ordinance.\n(b) \"Indirect initiative\" is exercise of initiative by the people through a proposition sent to Congress or the local legislative body for action.\n(c) \"Referendum\" is the power of the electorate to approve or reject a legislation through an election called for the purpose. It may be of two classes, namely: c.1. Referendum on statutes which refers to a petition to approve or reject an act or law, or part thereof, passed by Congress; and c.2. Referendum on local law which refers to a petition to approve or reject a law, resolution or ordinance enacted by regional assemblies and local legislative bodies.\n(d) \"Proposition\" is the measure proposed by the voters.\n(e) \"Plebiscite\" is the electoral process by which an initiative on the Constitution is approved or rejected by the people.\n(f) \"Petition\" is the written instrument containing the proposition and the required number of signatories. It shall be in a form to be determined by and submitted to the Commission on Elections, hereinafter referred to as the Commission.\n(g) \"Local government units\" refers to provinces, cities, municipalities and barangays.\n(h) \"Local legislative bodies\" refers to the Sangguniang Panlalawigan, Sangguniang Panlungsod, Sangguniang Bayan, and Sangguniang Nayon.\n(i) \"Local executives\" refers to the Provincial Governors, City or Municipal Mayors and Punong Barangay, as the case may be."}},{"id":"PH-H5232-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Who may exercise. — The power of initiative and referendum may be exercised by all registered voters of the country, autonomous regions, provinces, cities, municipalities and barangays."}},{"id":"PH-H5232-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Requirements. — (a) To exercise the power of initiative or referendum, at least ten per centum (10%) of the total number of the registered voters, of which every legislative district is represented by at least three per centum (3%) of the registered voters thereof, shall sign a petition for the purpose and register the same with the Commission.\n(b) A petition for an initiative on the 1987 Constitution must have at least twelve per centum (12%) of the total number of registered voters as signatories, of which every legislative district must be represented by at least three per centum (3%) of the registered voters therein. Initiative on the Constitution may be exercised only after five (5) years from the ratification of the 1987 Constitution and only once every five (5) years thereafter.\n(c) The petition shall state the following: c.1. contents or text of the proposed law sought to be enacted, approved or rejected, amended or repealed, as the case may be; c.2. the proposition; c.3. the reason or reasons therefor; c.4. that it is not one of the exceptions provided herein; c.5. signatures of the petitioners or registered voters; and c.6. an abstract or summary in not more than one hundred (100) words which shall be legibly written or printed at the top of every page of the petition.\n(d) A referendum or initiative affecting a law, resolution or ordinance passed by the legislative assembly of an autonomous region, province or city is deemed validly initiated if the petition thereof is signed by at least ten per centum (10%) of the registered voters in the province or city, of which every legislative district must be represented by at least three per centum (3%) of the registered voters therein; Provided, however, That if the province or city is composed only of one (1) legislative district, then at least each municipality in a province or each barangay in a city should be represented by at least three per centum (3%) of the registered voters therein.\n(e) A referendum of initiative on an ordinance passed in a municipality shall be deemed validly initiated if the petition therefor is signed by at least ten per centum (10%) of the registered voters in the municipality, of which every barangay is represented by at least three per centum (3%) of the registered voters therein.\n(f) A referendum or initiative on a barangay resolution or ordinance is deemed validly initiated if signed by at least ten per centum (10%) of the registered voters in said barangay."}},{"id":"PH-H5232-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Special Registration. — The Commission on Election shall set a special registration day at least three (3) weeks before a scheduled initiative or referendum."}},{"id":"PH-H5232-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Verification of Signatures. — The Election Registrar shall verify the signatures on the basis of the registry list of voters, voters' affidavits and voters identification cards used in the immediately preceding election.\nII. — National Initiative and Referendum"}},{"id":"PH-H5232-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Conduct and Date of Initiative or Referendum. — The Commission shall call and supervise the conduct of initiative or referendum.\nWithin a period of thirty (30) days from receipt of the petition, the Commission shall, upon determining the sufficiency of the petition, publish the same in Filipino and English at least twice in newspapers of general and local circulation and set the date of the initiative or referendum which shall not be earlier than forty-five (45) days but not later than ninety (90) days from the determination by the Commission of the sufficiency of the petition."}},{"id":"PH-H5232-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Effectivity of Initiative or Referendum Proposition. — (a) The Proposition of the enactment, approval, amendment or rejection of a national law shall be submitted to and approved by a majority of the votes cast by all the registered voters of the Philippines.\nIf, as certified to by the Commission, the proposition is approved by a majority of the votes cast, the national law proposed for enactment, approval, or amendment shall become effective fifteen (15) days following completion of its publication in the Official Gazette or in a newspaper of general circulation in the Philippines. If, as certified by the Commission, the proposition to reject a national law is approved by a majority of the votes cast, the said national law shall be deemed repealed and the repeal shall become effective fifteen (15) days following the completion of publication of the proposition and the certification by the Commission in the Official Gazette or in a newspaper of general circulation in the Philippines.\nHowever, if the majority vote is not obtained, the national law sought to be rejected or amended shall remain in full force and effect.\n(b) The proposition in an initiative on the Constitution approved by a majority of the votes cast in the plebiscite shall become effective as to the day of the plebiscite.\n(c) A national or local initiative proposition approved by majority of the votes cast in an election called for the purpose shall become effective fifteen (15) days after certification and proclamation by the Commission."}},{"id":"PH-H5232-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Prohibited Measures. — The following cannot be the subject of an initiative or referendum petition:\n(a) No petition embracing more than one (1) subject shall be submitted to the electorate; and\n(b) Statutes involving emergency measures, the enactment of which are specifically vested in Congress by the Constitution, cannot be subject to referendum until ninety (90) days after its effectivity."}},{"id":"PH-H5232-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Indirect Initiative. — Any duly accredited people's organization, as defined by law, may file a petition for indirect initiative with the House of Representatives, and other legislative bodies. The petition shall contain a summary of the chief purposes and contents of the bill that the organization proposes to be enacted into law by the legislature.\nThe procedure to be followed on the initiative bill shall be the same as the enactment of any legislative measure before the House of Representatives except that the said initiative bill shall have precedence over the pending legislative measures on the committee."}},{"id":"PH-H5232-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Appeal. — The decision of the Commission on the findings of the sufficiency or insufficiency of the petition for initiative or referendum may be appealed to the Supreme Court within thirty (30) days from notice thereof.\nIII. — Local Initiative and Referendum"}},{"id":"PH-H5232-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Procedure in Local Initiative. — (a) Not less than two thousand (2,000) registered voters in case of autonomous regions, one thousand (1,000) in case of provinces and cities, one hundred (100) in case of municipalities, and fifty (50) in case of barangays, may file a petition with the Regional Assembly or local legislative body, respectively, proposing the adoption, enactment, repeal, or amendment, of any law, ordinance or resolution.\n(b) If no favorable action thereon is made by local legislative body within (30) days from its presentation, the proponents through their duly authorized and registered representative may invoke their power of initiative, giving notice thereof to the local legislative body concerned.\n(c) The proposition shall be numbered serially starting from one (1). The Secretary of Local Government or his designated representative shall extend assistance in the formulation of the proposition.\n(d) Two or more propositions may be submitted in an initiative.\n(e) Proponents shall have one hundred twenty (120) days in case of autonomous regions, ninety (90) days in case of provinces and cities, sixty (60) days in case of municipalities, and thirty (30) days in case of barangays, from notice mentioned in subsection (b) hereof to collect the required number of signatures.\n(f) The petition shall be signed before the Election Registrar, or his designated representative, in the presence of a representative of the proponent, and a representative of the regional assemblies and local legislative bodies concerned in a public place in the autonomous region or local government unit, as the case may be. Signature stations may be established in as many places as may be warranted.\n(g) Upon the lapse of the period herein provided, the Commission on Elections, through its office in the local government unit concerned shall certify as to whether or not the required number of signatures has been obtained. Failure to obtain the required number is a defeat of the proposition.\n(h) If the required number of the signatures is obtained, the Commission shall then set a date for the initiative at which the proposition shall be submitted to the registered voters in the local government unit concerned for their approval within ninety (90) days from the date of certification by the Commission, as provided in subsection (g) hereof, in case of autonomous regions, sixty (60) days in case of the provinces and cities, forty-five (45) days in case of municipalities, and thirty (30) days in case of barangays. The initiative shall then be held on the date set, after which the results thereof shall be certified and proclaimed by the Commission on Elections."}},{"id":"PH-H5232-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity of Local Propositions. — If the proposition is approved by a majority of the votes cast, it shall take effect fifteen (15) days after certification by the Commission as if affirmative action thereon had been made by the local legislative body and local executive concerned. If it fails to obtain said number of votes, the proposition is considered defeated."}},{"id":"PH-H5232-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Limitations on Local Initiatives. — (a) The power of local initiative shall not be exercised more than once a year.\n(b) Initiative shall extend only to subjects or matters which are within the legal powers of the local legislative bodies to enact.\n(c) If at any time before the initiative is held, the local legislative body shall adopt in toto the proposition presented, the initiative shall be cancelled. However, those against such action may, if they so desire, apply for initiative in the manner herein provided."}},{"id":"PH-H5232-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Limitations Upon Local Legislative Bodies. — Any proposition or ordinance or resolution approved through the system of initiative and referendum as herein provided shall not be repealed, modified or amended, by the local legislative body concerned within six (6) months from the date therefrom, and may be amended, modified or repealed by the local legislative body within three (3) years thereafter by a vote of three-fourths (3/4) of all its members: Provided, however, that in case of barangays, the period shall be one (1) year after the expiration of the first six (6) months."}},{"id":"PH-H5232-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Local Referendum. — Notwithstanding the provisions of Section 4 hereof, any local legislative body may submit to the registered voters of autonomous region, provinces, cities, municipalities and barangays for the approval or rejection, any ordinance or resolution duly enacted or approved.\nSaid referendum shall be held under the control and direction of the Commission within sixty (60) days in case of provinces and cities, forty-five (45) days in case of municipalities and thirty (30) days in case of barangays.\nThe Commission shall certify and proclaim the results of the said referendum."}},{"id":"PH-H5232-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Authority of Courts. — Nothing in this Act shall prevent or preclude the proper courts from declaring null and void any proposition approved pursuant to this Act for violation of the Constitution or want of capacity of the local legislative body to enact the said measure.\nIV. — Final Provisions"}},{"id":"PH-H5232-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Applicability of the Omnibus Election Code. — The Omnibus Election Code and other election laws, not inconsistent with the provisions of this Act, shall apply to all initiatives and referenda."}},{"id":"PH-H5232-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Rules and Regulations. — The Commission is hereby empowered to promulgate such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5232-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Appropriations. — The amount necessary to defray the cost of the initial implementation of this Act shall be charged against the Contingent Fund in the General Appropriations Act of the current year. Thereafter, such sums as may be necessary for the full implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H5232-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause. — If any part or provision of this Act is held invalid or unconstitutional, the other parts or provisions thereof shall remain valid and effective."}},{"id":"PH-H5232-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Effectivity. — This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5233"] = {"id":"PH-H5233","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6736_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Bolitoc Barangay High School in the Municipality of Santa Cruz, Province of Zambales, to Mena Memorial High School","orig":"An Act Changing the Name of the Bolitoc Barangay High School in the Municipality of Santa Cruz, Province of Zambales, to Mena Memorial High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 6736","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6736_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5233-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Bolitoc Barangay High School in the Municipality of Sta. Cruz, Province of Zambales, is hereby changed to Mena Memorial High School."}},{"id":"PH-H5233-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5234"] = {"id":"PH-H5234","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6737_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Villasis National High School in Villasis, Pangasinan, to Don Ramon E. Costales Memorial National High School","orig":"An Act Changing the Name of the Villasis National High School in Villasis, Pangasinan, to Don Ramon E. Costales Memorial National High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6737","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6737_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5234-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Villasis National High School in Villasis, Pangasinan, shall, upon the effectivity of this Act, be known and referred to as the Don Ramon E. Costales Memorial National High School."}},{"id":"PH-H5234-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
