  FT["PH-H5236"] = {"id":"PH-H5236","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6740_1989.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming the Basey National Agricultural School in the Municipality of Basey, Province of Samar, as the Valeriano C. Yancha Memorial","orig":"An Act Renaming the Basey National Agricultural School in the Municipality of Basey, Province of Samar, as the Valeriano C. Yancha Memorial"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 6740","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-04","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6740_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5236-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Basey National Agricultural School in the Municipality of Basey, Province of Samar, is hereby renamed as the Valeriano C. Yancha Memorial Agricultural School."}},{"id":"PH-H5236-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports is hereby directed to take cognizance and implement the provision of Section 1 hereof."}},{"id":"PH-H5236-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5237"] = {"id":"PH-H5237","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6741_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring August Nineteen of Each Year a Special Working Holiday Throughout the Entire Philippines and a Special Non-working Public Holiday in the Provinces of Quezon and Aurora and Quezon City, to Commemorate the Birth Anniversary of Former President Manuel L. Quezon","orig":"An Act Declaring August Nineteen of Each Year a Special Working Holiday Throughout the Entire Philippines and a Special Non-working Public Holiday in the Provinces of Quezon and Aurora and Quezon City, to Commemorate the Birth Anniversary of Former President Manuel L. Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6741","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6741_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5237-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to commemorate the birth anniversary of former President Manuel L. Quezon, August Nineteen of each year is hereby declared as a special working holiday throughout the entire Philippines with the exception of the Provinces of Quezon and Aurora and Quezon City where it shall be a non-working holiday."}},{"id":"PH-H5237-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p74"};
  FT["PH-H5238"] = {"id":"PH-H5238","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6742_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"N Act Changing the Name of the Bataan National School of Arts and Trades in Balanga, Bataan, to Medina Lacson De Leon National School of Arts and Trades","orig":"N Act Changing the Name of the Bataan National School of Arts and Trades in Balanga, Bataan, to Medina Lacson De Leon National School of Arts and Trades"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 6742","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6742_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5238-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Bataan National School of Arts and Trades in Balanga, Bataan, is hereby changed to Medina Lacson de Leon National School of Arts and Trades."}},{"id":"PH-H5238-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5239"] = {"id":"PH-H5239","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6743_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Ozamiz市","en":"An Act Declaring July Sixteen of Every Year as Ozamiz City Charter Day and a Special Public Non-working Holiday in the City of Ozamiz","orig":"An Act Declaring July Sixteen of Every Year as Ozamiz City Charter Day and a Special Public Non-working Holiday in the City of Ozamiz"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6743","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6743_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5239-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July Sixteen of every year is hereby declared as Ozamiz City Charter Day and a special public non-working holiday in the City of Ozamiz."}},{"id":"PH-H5239-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
  FT["PH-H5240"] = {"id":"PH-H5240","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6744_1989.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Integrating the Candon Community College in the Municipality of Candon, Province of Ilocos Sur, Into the University of Northern Philippines in the Municipality of Vigan, Province of Ilocos Sur","orig":"An Act Integrating the Candon Community College in the Municipality of Candon, Province of Ilocos Sur, Into the University of Northern Philippines in the Municipality of Vigan, Province of Ilocos Sur"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6744","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-08-11","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6744_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5240-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Candon Community College in the Municipality of Candon, Province of Ilocos Sur, is hereby integrated into the University of Northern Philippines in the Municipality of Vigan, Province of Ilocos Sur, as branch or unit thereof to be known as the Candon Community College, University of Northern Philippines Branch."}},{"id":"PH-H5240-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In addition to its present curricular offerings, the Candon Community College shall offer courses which are or may be offered by the University of Northern Philippines."}},{"id":"PH-H5240-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets, liabilities, and appropriations of the Candon Community College are hereby transferred to or absorbed by the University of Northern Philippines."}},{"id":"PH-H5240-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p74"};
